const CATALOG = {"title":"TwistedPear Handbook","version":"0.2.0","manifestCapabilities":[{"id":"identity","description":"Use an app-scoped identity for signing and addressing."},{"id":"presence","description":"Read coarse peer/interface presence and host info."},{"id":"announce:publish","description":"Publish the app destination."},{"id":"announce:subscribe","description":"Receive announces in the app namespace."},{"id":"lxmf:send","description":"Send LXMF messages from the app destination."},{"id":"lxmf:receive","description":"Receive LXMF messages for the app destination."},{"id":"storage:kv","description":"Store local key/value data for this app."},{"id":"storage:hyperbee","description":"Store ordered local Hyperbee data for this app."},{"id":"resource:fetch","description":"Fetch package resources through host budget rules."},{"id":"workspace","description":"Read and write project source files in this app's private workspace."},{"id":"ai:chat","description":"Send prompts to the host-configured AI service; prompts may include workspace content."},{"id":"ai:embed","description":"Send bounded text to the host-configured embedding model and rank vectors locally."},{"id":"share:cas","description":"Store and retrieve bounded content-addressed data shared by 256t id."},{"id":"apps:preview","description":"Run a built app in the host's sandboxed dev-preview slot."},{"id":"apps:package","description":"Package and sign apps under this device's publisher identity (asks each time)."},{"id":"apps:publish","description":"Publish signed apps so other users can find and install them (asks each time)."},{"id":"apps:install","description":"Ask the host to install apps from a 256t id (asks each time, with capability review)."}],"parts":[{"id":"part-1-concepts","title":"Part I — Concepts","chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is"},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals"},{"id":"pears-bulk-plane","title":"Pears bulk plane"},{"id":"concepts-in-practice","title":"Concepts in practice"}]},{"id":"part-2-hosts","title":"Part II — The hosts","chapters":[{"id":"host-android","title":"Android host"},{"id":"host-ios","title":"iOS host"},{"id":"host-desktop","title":"Desktop host"},{"id":"host-web","title":"Web host"},{"id":"host-headless","title":"Headless node & seeder"},{"id":"difference-matrix","title":"Live difference matrix"}]},{"id":"part-3-sdk","title":"Part III — Developing mini-apps","chapters":[{"id":"sdk-identity","title":"Identity & signing"},{"id":"sdk-presence","title":"Presence"},{"id":"sdk-storage-kv","title":"Key/value storage"},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage"},{"id":"sdk-lxmf","title":"LXMF messaging"},{"id":"sdk-announce","title":"Announce & subscribe"},{"id":"sdk-resource-fetch","title":"Resource fetch"},{"id":"sdk-budgets","title":"Budgets & quotas"},{"id":"sdk-workspace","title":"Workspace"},{"id":"sdk-share-cas","title":"Content-addressed share"},{"id":"sdk-capabilities","title":"Capability model"},{"id":"sdk-apps-package","title":"Packaging & preview"},{"id":"sdk-apps-publish","title":"Publish & install"},{"id":"sdk-apps-update","title":"Publish, install & update"},{"id":"sdk-devstudio","title":"DevStudio walkthrough"},{"id":"sdk-ai-chat","title":"AI chat"},{"id":"sdk-widget-gallery","title":"Widget gallery"}]},{"id":"part-4-diagnostics","title":"Part IV — Diagnostics","chapters":[{"id":"running-diagnostics","title":"Running diagnostics"},{"id":"device-gated-probes","title":"Device-gated probes"}]},{"id":"part-5-reference","title":"Part V — Reference","chapters":[{"id":"ref-capabilities","title":"Capabilities"},{"id":"ref-widgets","title":"Widget protocol"},{"id":"ref-host-api","title":"Host API"},{"id":"ref-packages","title":"Package format"},{"id":"ref-interfaces","title":"Network interfaces"},{"id":"ref-quotas","title":"Quotas & limits"},{"id":"ref-host-config","title":"Host configuration"},{"id":"ref-cli","title":"CLI commands"},{"id":"ref-limitations","title":"Known limitations"}]}],"chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"What TwistedPear is"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"TwistedPear is a peer-to-peer app platform. A **host** on each device is a full Reticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the host only through the SDK."},{"type":"heading","level":2,"text":"Two planes"},{"type":"list","items":["**Control plane** — Reticulum handles identity, announces, links, LXMF, and"]},{"type":"paragraph","text":"off-grid Resource transfer."},{"type":"list","items":["**Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package"]},{"type":"paragraph","text":"syncs when IP connectivity exists. Pears bulk plane."},{"type":"chapter-link","label":"Pears bulk plane","chapterId":"pears-bulk-plane"},{"type":"heading","level":2,"text":"Trust model"},{"type":"paragraph","text":"Publisher identity **is** network identity. Packages are Ed25519-signed with the developer's Reticulum key, so discovering an app and trusting its author use the same root."},{"type":"heading","level":2,"text":"This Handbook"},{"type":"paragraph","text":"This document is itself a mini-app. If it installed and rendered on *this* host, you have already exercised packaging, install, sandbox, broker, and the widget renderer. Chapters later add interactive applets that probe live capabilities."},{"type":"paragraph","text":"Open **Diagnostics** from the table of contents to run every probe, export a report, or compare against another device. Reference pages in Part V are generated from the same runtime sources the host uses. Host-specific behavior: Part II — The hosts."},{"type":"chapter-link","label":"Part II — The hosts","chapterId":"host-desktop"}],"searchText":"what twistedpear is part i — concepts what twistedpear is <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> twistedpear is a peer-to-peer app platform. a **host** on each device is a full reticulum peer; **mini-apps** are sandboxed javascript bundles that talk to the host only through the sdk. two planes **control plane** — reticulum handles identity, announces, links, lxmf, and off-grid resource transfer. **bulk plane** — hypercore / hyperdrive / hyperswarm carry large package syncs when ip connectivity exists. pears bulk plane. trust model publisher identity **is** network identity. packages are ed25519-signed with the developer's reticulum key, so discovering an app and trusting its author use the same root. this handbook this document is itself a mini-app. if it installed and rendered on *this* host, you have already exercised packaging, install, sandbox, broker, and the widget renderer. chapters later add interactive applets that probe live capabilities. open **diagnostics** from the table of contents to run every probe, export a report, or compare against another device. reference pages in part v are generated from the same runtime sources the host uses. host-specific behavior: part ii — the hosts."},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Reticulum fundamentals"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Reticulum is a cryptography-based networking stack designed for constrained and unreliable links. TwistedPear uses it as the only hard networking constraint."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.","**Announce** — a signed public advertisement that a destination is reachable.","**Link** — an encrypted channel between two destinations.","**Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).","**LXMF** — store-and-forward messaging on top of Reticulum."]},{"type":"heading","level":2,"text":"App-scoped destinations"},{"type":"paragraph","text":"Mini-apps never hold private keys. The host derives an **app destination** from the device identity plus the app id. Bulk transfer when IP is available: Pears bulk plane. See Concepts in practice for a live identity probe, or Identity & signing."},{"type":"chapter-link","label":"Pears bulk plane","chapterId":"pears-bulk-plane"},{"type":"chapter-link","label":"Concepts in practice","chapterId":"concepts-in-practice"},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"}],"searchText":"reticulum fundamentals part i — concepts reticulum fundamentals <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> reticulum is a cryptography-based networking stack designed for constrained and unreliable links. twistedpear uses it as the only hard networking constraint. building blocks **identity** — an x25519/ed25519 keypair. destinations are derived hashes. **announce** — a signed public advertisement that a destination is reachable. **link** — an encrypted channel between two destinations. **resource** — a bulk transfer over a link (used when hyperswarm is unavailable). **lxmf** — store-and-forward messaging on top of reticulum. app-scoped destinations mini-apps never hold private keys. the host derives an **app destination** from the device identity plus the app id. bulk transfer when ip is available: pears bulk plane. see concepts in practice for a live identity probe, or identity & signing."},{"id":"pears-bulk-plane","title":"Pears bulk plane","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Pears bulk plane"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Reticulum is the **control plane** — identity, announces, links, LXMF, and off-grid Resource transfer. When IP connectivity exists, large package syncs prefer the **Pears bulk plane**: Hypercore, Hyperdrive, and Hyperswarm."},{"type":"heading","level":2,"text":"Why two planes"},{"type":"paragraph","text":"Reticulum links are optimized for constrained carriers (BLE, LoRa) with small MTUs and high latency. Shipping a multi-megabyte `.tpkg` over those links works but is slow. Hyperswarm discovery plus Hyperdrive replication uses TCP where available and falls back to Reticulum Resources when it is not."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Hypercore** — append-only signed logs. Each app package is a deterministic"]},{"type":"paragraph","text":"archive keyed by the publisher's feed."},{"type":"list","items":["**Hyperdrive** — a filesystem view over one or more Hypercores. `tp publish`"]},{"type":"paragraph","text":"seeds the signed `.tpkg`; peers replicate blocks from seeders on the LAN or DHT."},{"type":"list","items":["**Hyperswarm** — topic-based peer discovery for Hyperdrive replication. Desktop"]},{"type":"paragraph","text":"and headless hosts run seeders by default; phones are usually leaf consumers."},{"type":"heading","level":2,"text":"In practice"},{"type":"table","headers":["Operation","Typical plane"],"rows":[["Discover an app announce","Reticulum control plane"],["Install over LAN / internet","Hyperdrive bulk fetch"],["Install with no IP path","Reticulum Resource transfer"],["LXMF chat message","Reticulum only"],["Handbook diagnostic report (`share.put`)","CAS + optional Hyperdrive seed"]]},{"type":"paragraph","text":"Headless seeding: Headless node & seeder. Distribution tutorial: Publish & install."},{"type":"chapter-link","label":"Headless node & seeder","chapterId":"host-headless"},{"type":"chapter-link","label":"Publish & install","chapterId":"sdk-apps-publish"}],"searchText":"pears bulk plane part i — concepts pears bulk plane <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> reticulum is the **control plane** — identity, announces, links, lxmf, and off-grid resource transfer. when ip connectivity exists, large package syncs prefer the **pears bulk plane**: hypercore, hyperdrive, and hyperswarm. why two planes reticulum links are optimized for constrained carriers (ble, lora) with small mtus and high latency. shipping a multi-megabyte `.tpkg` over those links works but is slow. hyperswarm discovery plus hyperdrive replication uses tcp where available and falls back to reticulum resources when it is not. building blocks **hypercore** — append-only signed logs. each app package is a deterministic archive keyed by the publisher's feed. **hyperdrive** — a filesystem view over one or more hypercores. `tp publish` seeds the signed `.tpkg`; peers replicate blocks from seeders on the lan or dht. **hyperswarm** — topic-based peer discovery for hyperdrive replication. desktop and headless hosts run seeders by default; phones are usually leaf consumers. in practice operation typical plane discover an app announce reticulum control plane install over lan / internet hyperdrive bulk fetch install with no ip path reticulum resource transfer lxmf chat message reticulum only handbook diagnostic report (`share.put`) cas + optional hyperdrive seed headless seeding: headless node & seeder. distribution tutorial: publish & install."},{"id":"concepts-in-practice","title":"Concepts in practice","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Concepts in practice"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The applets below run on **this** host — the same probes used in Part III and Part IV diagnostics, grouped for readers who want to see Reticulum building blocks work before diving into SDK chapters."},{"type":"paragraph","text":"If the Handbook installed and these applets pass, you have verified identity derivation, announce loopback, and LXMF self-delivery on your current host."},{"type":"heading","level":2,"text":"Identity"},{"type":"paragraph","text":"Derives the app destination hash from the host identity. No private keys in the sandbox."},{"type":"applet","appletId":"identity-hash"},{"type":"heading","level":2,"text":"Announce loop"},{"type":"paragraph","text":"Publishes then subscribes in a local namespace — the discovery primitive apps use before install."},{"type":"applet","appletId":"announce-loop"},{"type":"heading","level":2,"text":"LXMF self-message"},{"type":"paragraph","text":"Sends and receives a message to this app’s own destination — store-and-forward on Reticulum."},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"Next: Identity & signing · Running diagnostics"},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"},{"type":"chapter-link","label":"Running diagnostics","chapterId":"running-diagnostics"}],"searchText":"concepts in practice part i — concepts concepts in practice <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the applets below run on **this** host — the same probes used in part iii and part iv diagnostics, grouped for readers who want to see reticulum building blocks work before diving into sdk chapters. if the handbook installed and these applets pass, you have verified identity derivation, announce loopback, and lxmf self-delivery on your current host. identity derives the app destination hash from the host identity. no private keys in the sandbox. announce loop publishes then subscribes in a local namespace — the discovery primitive apps use before install. lxmf self-message sends and receives a message to this app’s own destination — store-and-forward on reticulum. next: identity & signing · running diagnostics"},{"id":"host-android","title":"Android host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Android host"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The Android host is a React Native shell around the same **Bare worklet** used on iOS and desktop. Reticulum, LXMF, catalog install, and the mini-app runtime all run in the worklet; the JVM layer supplies lifecycle, BLE, multicast bridges, and a foreground service so the node can stay reachable in the background."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Expo / RN shell** — settings, grants, confirmations, widget renderer.","**Bare worklet child** — `reticulum-ts`, `host-core` leaf roles, broker, sandboxes.","**Native bridges** — TCP, AutoInterface multicast, Bonjour, BLE central/peripheral,"]},{"type":"paragraph","text":"RNode serial-over-BLE, camera (QR install)."},{"type":"heading","level":2,"text":"Roles"},{"type":"paragraph","text":"Android phones default to **leaf** peers: transport routing and package seeding are off unless the operator enables them on a dedicated device. Most users run a leaf that dials LAN peers or a desktop gateway."},{"type":"heading","level":2,"text":"Lifecycle"},{"type":"list","items":["**Foreground** — full interface set, mini-app execution, BLE active.","**Background** — `NodeForegroundService` keeps the worklet alive; interfaces"]},{"type":"paragraph","text":"quiesce on a grace timer then reconnect on resume (see Known limitations §3)."},{"type":"chapter-link","label":"Known limitations","chapterId":"ref-limitations"},{"type":"list","items":["**Suspended** — no mini-app execution; LXMF store-and-forward only."]},{"type":"heading","level":2,"text":"Storage"},{"type":"paragraph","text":"App data lives under the host's private app storage. Identity keys and package archives are worklet-managed; clearing app data resets the peer."},{"type":"heading","level":2,"text":"What to expect on this host"},{"type":"paragraph","text":"Use the live difference matrix on a real device or emulator — `host.info()` reports `platform=android`, interface types, and roles for **this** install. BLE pair, RNode, multicast, and camera probes are device-gated in CI."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"chapter-link","label":"device-gated","chapterId":"device-gated-probes"}],"searchText":"android host part ii — the hosts android host <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the android host is a react native shell around the same **bare worklet** used on ios and desktop. reticulum, lxmf, catalog install, and the mini-app runtime all run in the worklet; the jvm layer supplies lifecycle, ble, multicast bridges, and a foreground service so the node can stay reachable in the background. architecture **expo / rn shell** — settings, grants, confirmations, widget renderer. **bare worklet child** — `reticulum-ts`, `host-core` leaf roles, broker, sandboxes. **native bridges** — tcp, autointerface multicast, bonjour, ble central/peripheral, rnode serial-over-ble, camera (qr install). roles android phones default to **leaf** peers: transport routing and package seeding are off unless the operator enables them on a dedicated device. most users run a leaf that dials lan peers or a desktop gateway. lifecycle **foreground** — full interface set, mini-app execution, ble active. **background** — `nodeforegroundservice` keeps the worklet alive; interfaces quiesce on a grace timer then reconnect on resume (see known limitations §3). **suspended** — no mini-app execution; lxmf store-and-forward only. storage app data lives under the host's private app storage. identity keys and package archives are worklet-managed; clearing app data resets the peer. what to expect on this host use the live difference matrix on a real device or emulator — `host.info()` reports `platform=android`, interface types, and roles for **this** install. ble pair, rnode, multicast, and camera probes are device-gated in ci."},{"id":"host-ios","title":"iOS host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"iOS host"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The iOS host mirrors Android: a React Native shell supervising a **Bare worklet** with the same protocol stack. Platform entitlements and background rules shape which interfaces stay online when the app is not in the foreground."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Expo / RN shell** — peer browser, grants, confirmations, widget renderer.","**Bare worklet child** — identical broker and sandbox model to Android/desktop.","**Native bridges** — TCP client, Bonjour, BLE (central/peripheral), RNode"]},{"type":"paragraph","text":"over BLE only (no USB serial on iOS)."},{"type":"heading","level":2,"text":"Lifecycle (no foreground-service equivalent)"},{"type":"paragraph","text":"iOS has no Android-style foreground service. Backgrounding is a **state transition**:"},{"type":"list","items":["**Foreground** — interfaces and the active mini-app run normally.","**Background grace** — native lifecycle sends `suspend-node`; worklet quiesces"]},{"type":"paragraph","text":"TCP/multicast timers; existing BLE links may survive briefly."},{"type":"list","items":["**Suspended** — no mini-app execution; pending LXMF is persisted for later sync."]},{"type":"paragraph","text":"Store-posture builds refuse catalog install and dev side-load; development builds keep parity with Android for `tp dev` and Handbook installs."},{"type":"heading","level":2,"text":"Entitlements"},{"type":"paragraph","text":"Local network, Bonjour (`_reticulum._udp`), Bluetooth, and multicast require usage strings and (for multicast) the networking multicast entitlement. Until entitlement filing completes, multicast may report unavailable even though the code path exists — check `host.info()` on **this** device."},{"type":"heading","level":2,"text":"Simulator vs device"},{"type":"paragraph","text":"The simulator validates worklet boot, TCP/localhost, store-posture refusal, and Handbook software-tier slices. BLE, real background timing, and LAN multicast need hardware — see Device-gated probes."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"},{"type":"paragraph","text":"Compare live signals: Live difference matrix."},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"}],"searchText":"ios host part ii — the hosts ios host <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the ios host mirrors android: a react native shell supervising a **bare worklet** with the same protocol stack. platform entitlements and background rules shape which interfaces stay online when the app is not in the foreground. architecture **expo / rn shell** — peer browser, grants, confirmations, widget renderer. **bare worklet child** — identical broker and sandbox model to android/desktop. **native bridges** — tcp client, bonjour, ble (central/peripheral), rnode over ble only (no usb serial on ios). lifecycle (no foreground-service equivalent) ios has no android-style foreground service. backgrounding is a **state transition**: **foreground** — interfaces and the active mini-app run normally. **background grace** — native lifecycle sends `suspend-node`; worklet quiesces tcp/multicast timers; existing ble links may survive briefly. **suspended** — no mini-app execution; pending lxmf is persisted for later sync. store-posture builds refuse catalog install and dev side-load; development builds keep parity with android for `tp dev` and handbook installs. entitlements local network, bonjour (`_reticulum._udp`), bluetooth, and multicast require usage strings and (for multicast) the networking multicast entitlement. until entitlement filing completes, multicast may report unavailable even though the code path exists — check `host.info()` on **this** device. simulator vs device the simulator validates worklet boot, tcp/localhost, store-posture refusal, and handbook software-tier slices. ble, real background timing, and lan multicast need hardware — see device-gated probes. compare live signals: live difference matrix."},{"id":"host-desktop","title":"Desktop host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Desktop host"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The desktop host is the **always-on peer** in a typical mesh: transport routing, package seeding, optional LXMF propagation, and a gateway for browser tabs via the WebSocket Reticulum interface."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Electron shell** (`apps/host-desktop`) — tray, power events, native multicast/"]},{"type":"paragraph","text":"Bonjour bridges, crash supervision, DOM widget renderer."},{"type":"list","items":["**Bare worklet child** — same stack as mobile; stdio IPC to the shell.","**`host-core`** — shared engine with headless `tp node` / `tp seed`."]},{"type":"heading","level":2,"text":"Default roles"},{"type":"table","headers":["Role","Default","Notes"],"rows":[["Transport node","on","Off when `--attach-rnsd` leaf mode"],["Seeder / LAN mirror","on","Quota'd Hyperdrive serving"],["Propagation server","off","Enable in UI or `--propagation`"],["WebSocket gateway","off","`--ws-listen` for web-host tabs"]]},{"type":"heading","level":2,"text":"Lifecycle"},{"type":"list","items":["**Suspend** (system sleep) — worklet quiesces interfaces.","**Resume** — reconnect and re-announce.","**Crash** — supervisor restarts the worklet with exponential backoff."]},{"type":"heading","level":2,"text":"First-boot apps"},{"type":"paragraph","text":"Fresh desktop installs seed **handbook**, **devstudio**, and **chat** from the TwistedPear platform publisher. Open **Installed** and launch **handbook** — you are reading it."},{"type":"heading","level":2,"text":"Config & data"},{"type":"paragraph","text":"Platform data directory (identity, `config.json`, quotas):"},{"type":"list","items":["macOS: `~/Library/Application Support/TwistedPear/host`","Linux: `~/.local/share/twistedpear/host`","Windows: `%APPDATA%/TwistedPear/host`"]},{"type":"paragraph","text":"Full schema: Host configuration."},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"},{"type":"paragraph","text":"Opt-in status JSON: `http://127.0.0.1:9473/status` when `--status-endpoint` is set."},{"type":"paragraph","text":"Live capability view: Live difference matrix. Storage paths and roles: Host configuration."},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"}],"searchText":"desktop host part ii — the hosts desktop host <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the desktop host is the **always-on peer** in a typical mesh: transport routing, package seeding, optional lxmf propagation, and a gateway for browser tabs via the websocket reticulum interface. architecture **electron shell** (`apps/host-desktop`) — tray, power events, native multicast/ bonjour bridges, crash supervision, dom widget renderer. **bare worklet child** — same stack as mobile; stdio ipc to the shell. **`host-core`** — shared engine with headless `tp node` / `tp seed`. default roles role default notes transport node on off when `--attach-rnsd` leaf mode seeder / lan mirror on quota'd hyperdrive serving propagation server off enable in ui or `--propagation` websocket gateway off `--ws-listen` for web-host tabs lifecycle **suspend** (system sleep) — worklet quiesces interfaces. **resume** — reconnect and re-announce. **crash** — supervisor restarts the worklet with exponential backoff. first-boot apps fresh desktop installs seed **handbook**, **devstudio**, and **chat** from the twistedpear platform publisher. open **installed** and launch **handbook** — you are reading it. config & data platform data directory (identity, `config.json`, quotas): macos: `~/library/application support/twistedpear/host` linux: `~/.local/share/twistedpear/host` windows: `%appdata%/twistedpear/host` full schema: host configuration. opt-in status json: `http://127.0.0.1:9473/status` when `--status-endpoint` is set. live capability view: live difference matrix. storage paths and roles: host configuration."},{"id":"host-web","title":"Web host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Web host"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The web host is a **browser tab** running the full mini-app stack in-page — not a remote UI for another node. `reticulum-ts` executes in a core Web Worker; per-app sandboxes use opaque-origin iframes plus workers; the host UI renders widgets with React Native for Web."},{"type":"heading","level":2,"text":"Leaf-only posture"},{"type":"paragraph","text":"Browsers cannot accept inbound connections or open raw TCP/UDP. The web host is permanently a **leaf peer**:"},{"type":"list","items":["No transport-node, seeder, or propagation roles — ever.","Reticulum reachability goes through a **WebSocket gateway** on a desktop or"]},{"type":"paragraph","text":"`tp node` peer (`--ws-listen`)."},{"type":"list","items":["Bulk installs use the gateway's `/bulk-fetch` proxy; offline fallback is"]},{"type":"paragraph","text":"Reticulum Resource transfer."},{"type":"heading","level":2,"text":"Architecture"},{"type":"code","documentId":"chapters/host-web/sample-0.txt","language":"text"},{"type":"heading","level":2,"text":"Security notes"},{"type":"paragraph","text":"Identity keys live in IndexedDB encrypted with WebCrypto — weaker than a hardware keystore. The **page origin is part of the trust base**: default posture is self-serving from your own node (`tp node --serve-web`). See Known limitations §8."},{"type":"chapter-link","label":"Known limitations","chapterId":"ref-limitations"},{"type":"heading","level":2,"text":"Radios & serial"},{"type":"paragraph","text":"No BLE peripheral, no multicast AutoInterface. WebSerial RNode (Chromium) is a stretch path; real USB LoRa E2E is device-gated. Probes report `unavailable` honestly on `platform=web`."},{"type":"paragraph","text":"Gateway spec: WebSocket interface. Live matrix: Live difference matrix."},{"type":"chapter-link","label":"WebSocket interface","chapterId":"ref-interfaces"},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"}],"searchText":"web host part ii — the hosts web host <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the web host is a **browser tab** running the full mini-app stack in-page — not a remote ui for another node. `reticulum-ts` executes in a core web worker; per-app sandboxes use opaque-origin iframes plus workers; the host ui renders widgets with react native for web. leaf-only posture browsers cannot accept inbound connections or open raw tcp/udp. the web host is permanently a **leaf peer**: no transport-node, seeder, or propagation roles — ever. reticulum reachability goes through a **websocket gateway** on a desktop or `tp node` peer (`--ws-listen`). bulk installs use the gateway's `/bulk-fetch` proxy; offline fallback is reticulum resource transfer. architecture security notes identity keys live in indexeddb encrypted with webcrypto — weaker than a hardware keystore. the **page origin is part of the trust base**: default posture is self-serving from your own node (`tp node --serve-web`). see known limitations §8. radios & serial no ble peripheral, no multicast autointerface. webserial rnode (chromium) is a stretch path; real usb lora e2e is device-gated. probes report `unavailable` honestly on `platform=web`. gateway spec: websocket interface. live matrix: live difference matrix."},{"id":"host-headless","title":"Headless node & seeder","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Headless node & seeder"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`tp node` and `tp seed` run **`host-core`** without a UI — the same engine as the desktop worklet, suitable for servers, CI, and LAN gateways."},{"type":"heading","level":2,"text":"`tp node`"},{"type":"paragraph","text":"Always-on desktop-class peer from the CLI:"},{"type":"code","documentId":"chapters/host-headless/sample-0.txt","language":"text"},{"type":"paragraph","text":"Common flags:"},{"type":"list","items":["`--no-transport` / `--no-seeder` — leaf or attach-only modes","`--ws-listen [host:]port` — WebSocket gateway for browser tabs","`--ws-token <token>` — optional shared secret on the gateway","`--serve-web [dir]` — serve the built web-host bundle from this machine","`--status-endpoint` — localhost JSON status on port 9473"]},{"type":"heading","level":2,"text":"`tp seed`"},{"type":"paragraph","text":"Headless package mirror focused on Hyperdrive seeding:"},{"type":"code","documentId":"chapters/host-headless/sample-1.txt","language":"text"},{"type":"paragraph","text":"Use when you want seeding without the Electron shell. Quotas match desktop defaults (see Quotas & limits)."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"heading","level":2,"text":"When to use headless vs desktop"},{"type":"table","headers":["Need","Headless","Desktop host"],"rows":[["WebSocket gateway for web tabs","`tp node --ws-listen`","enable in config / CLI"],["Tray UI + crash supervision","—","Electron shell"],["CI / docker interop","`tp node` in containers","optional"],["Developer mini-app side-load","`tp dev` targets either","`tp dev`"]]},{"type":"heading","level":2,"text":"Handbook on node"},{"type":"paragraph","text":"CI runs the Handbook with `npm run test:handbook` — pack, install, render every chapter, execute applets on the Node Worker sandbox backend. This is the same catalog desktop seeds, without graphics."},{"type":"paragraph","text":"CLI reference: CLI commands."},{"type":"chapter-link","label":"CLI commands","chapterId":"ref-cli"}],"searchText":"headless node & seeder part ii — the hosts headless node & seeder <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `tp node` and `tp seed` run **`host-core`** without a ui — the same engine as the desktop worklet, suitable for servers, ci, and lan gateways. `tp node` always-on desktop-class peer from the cli: common flags: `--no-transport` / `--no-seeder` — leaf or attach-only modes `--ws-listen [host:]port` — websocket gateway for browser tabs `--ws-token <token>` — optional shared secret on the gateway `--serve-web [dir]` — serve the built web-host bundle from this machine `--status-endpoint` — localhost json status on port 9473 `tp seed` headless package mirror focused on hyperdrive seeding: use when you want seeding without the electron shell. quotas match desktop defaults (see quotas & limits). when to use headless vs desktop need headless desktop host websocket gateway for web tabs `tp node --ws-listen` enable in config / cli tray ui + crash supervision — electron shell ci / docker interop `tp node` in containers optional developer mini-app side-load `tp dev` targets either `tp dev` handbook on node ci runs the handbook with `npm run test:handbook` — pack, install, render every chapter, execute applets on the node worker sandbox backend. this is the same catalog desktop seeds, without graphics. cli reference: cli commands."},{"id":"difference-matrix","title":"Live difference matrix","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Live difference matrix"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Hosts share one SDK and widget protocol, but platform sandboxes and entitlements shape what is actually available. Per-host chapters describe architecture and lifecycle; `host.info()` returns the facts for **this** host — platform id, host / API versions, enabled roles, interface types, and quota snapshot — instead of asserting differences in stale prose."},{"type":"list","items":["Android host · iOS host ·"]},{"type":"paragraph","text":"Desktop host · Web host · Headless node & seeder"},{"type":"chapter-link","label":"Desktop host","chapterId":"host-desktop"},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"chapter-link","label":"Headless node & seeder","chapterId":"host-headless"},{"type":"heading","level":2,"text":"Probe"},{"type":"applet","appletId":"host-info"},{"type":"heading","level":2,"text":"How to read differences"},{"type":"table","headers":["Signal","Typical cause","See also"],"rows":[["`platform=web` + no `auto`/`ble`","Browser leaf: WebSocket gateway only","[Web host](chapter:host-web), [Known limitations](chapter:ref-limitations) §8"],["`platform=ios` + missing multicast","Multicast entitlement / Bonjour path","[iOS host](chapter:host-ios), [Known limitations](chapter:ref-limitations) §4"],["`transport=false` on phones","Leaf role; desktops default transport + seeder","[Android](chapter:host-android) / [Desktop](chapter:host-desktop)"],["Interface listed but offline","Feature present; peer/hardware not connected","Part IV diagnostics"],["`not-granted` applet cards","User withheld a manifest capability","[Capability model](chapter:sdk-capabilities)"],["BLE / RNode / camera `device-gated`","Hardware or second device required","[Device-gated probes](chapter:device-gated-probes)"],["Large install over BLE slow","Bulk plane vs Resource fallback","[Budgets & quotas](chapter:sdk-budgets)"]]},{"type":"paragraph","text":"Cross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all applets, export a report via `share:cas`, then paste another device's 256t id to diff results side-by-side."}],"searchText":"live difference matrix part ii — the hosts live difference matrix <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> hosts share one sdk and widget protocol, but platform sandboxes and entitlements shape what is actually available. per-host chapters describe architecture and lifecycle; `host.info()` returns the facts for **this** host — platform id, host / api versions, enabled roles, interface types, and quota snapshot — instead of asserting differences in stale prose. android host · ios host · desktop host · web host · headless node & seeder probe how to read differences signal typical cause see also `platform=web` + no `auto`/`ble` browser leaf: websocket gateway only [web host](chapter:host-web), [known limitations](chapter:ref-limitations) §8 `platform=ios` + missing multicast multicast entitlement / bonjour path [ios host](chapter:host-ios), [known limitations](chapter:ref-limitations) §4 `transport=false` on phones leaf role; desktops default transport + seeder [android](chapter:host-android) / [desktop](chapter:host-desktop) interface listed but offline feature present; peer/hardware not connected part iv diagnostics `not-granted` applet cards user withheld a manifest capability [capability model](chapter:sdk-capabilities) ble / rnode / camera `device-gated` hardware or second device required [device-gated probes](chapter:device-gated-probes) large install over ble slow bulk plane vs resource fallback [budgets & quotas](chapter:sdk-budgets) cross-check with presence (`presence.snapshot`) and part iv diagnostics: run all applets, export a report via `share:cas`, then paste another device's 256t id to diff results side-by-side."},{"id":"sdk-identity","title":"Identity & signing","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Identity & signing"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The `identity` capability grants an app-scoped destination and brokered signing. Private keys never enter the sandbox — the host derives an app destination from the device identity plus app id and performs crypto on the broker."},{"type":"heading","level":2,"text":"Why app-scoped destinations"},{"type":"paragraph","text":"Publisher trust and app addressing share one root: the Reticulum keypair. Mini-apps never see private key material; they receive hashes and signatures only."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-identity/sample-0.js","language":"javascript"},{"type":"paragraph","text":"`destinationHash` is stable for a given install. `sign` accepts raw bytes and returns a signature verifiable against the app destination."},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — hash and signing path work on this host.","`not-granted` — identity capability withheld at install."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet below calls `identity.destinationHash()` on this host and reports pass / fail / not-granted."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Use **Open in DevStudio** on any applet to copy the sample into a DevStudio project via `share:cas`. Concept overview: Concepts in practice."},{"type":"chapter-link","label":"Concepts in practice","chapterId":"concepts-in-practice"}],"searchText":"identity & signing part iii — developing mini-apps identity & signing <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the `identity` capability grants an app-scoped destination and brokered signing. private keys never enter the sandbox — the host derives an app destination from the device identity plus app id and performs crypto on the broker. why app-scoped destinations publisher trust and app addressing share one root: the reticulum keypair. mini-apps never see private key material; they receive hashes and signatures only. api `destinationhash` is stable for a given install. `sign` accepts raw bytes and returns a signature verifiable against the app destination. outcomes `pass` — hash and signing path work on this host. `not-granted` — identity capability withheld at install. live probe the applet below calls `identity.destinationhash()` on this host and reports pass / fail / not-granted. use **open in devstudio** on any applet to copy the sample into a devstudio project via `share:cas`. concept overview: concepts in practice."},{"id":"sdk-presence","title":"Presence","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Presence"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`presence` exposes coarse peer and interface state: how many peers are visible, which interface is preferred, and whether the host considers itself online. It complements `host.info()` for the live difference matrix."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":2,"text":"What presence is not"},{"type":"paragraph","text":"Presence is not a full routing table. It is a snapshot for UI and diagnostics — enough to tell whether BLE, TCP, or WebSocket paths look healthy on **this** host."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-presence/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Grant `presence` at install. Without it, host info and presence probes become `not-granted` teaching cards."},{"type":"heading","level":2,"text":"Reading results"},{"type":"list","items":["`peers === 0` on a phone may be normal in CI; on LAN with a second peer it often"]},{"type":"paragraph","text":"indicates discovery still warming up."},{"type":"list","items":["Compare with `host.info().interfaceTypes` — an interface can be listed but offline."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"presence-snapshot"},{"type":"paragraph","text":"See also the live difference matrix (`host.info` applet)."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"}],"searchText":"presence part iii — developing mini-apps presence <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `presence` exposes coarse peer and interface state: how many peers are visible, which interface is preferred, and whether the host considers itself online. it complements `host.info()` for the live difference matrix. what presence is not presence is not a full routing table. it is a snapshot for ui and diagnostics — enough to tell whether ble, tcp, or websocket paths look healthy on **this** host. api grant `presence` at install. without it, host info and presence probes become `not-granted` teaching cards. reading results `peers === 0` on a phone may be normal in ci; on lan with a second peer it often indicates discovery still warming up. compare with `host.info().interfacetypes` — an interface can be listed but offline. live probe see also the live difference matrix (`host.info` applet)."},{"id":"sdk-storage-kv","title":"Key/value storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Key/value storage"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`storage:kv` is a per-app local store with a byte quota enforced by the host. Values are opaque byte arrays — encode JSON or UTF-8 in the sandbox before writing."},{"type":"heading","level":2,"text":"When to use KV"},{"type":"paragraph","text":"Use KV for small persistent state: settings, last-read positions, cached tokens. For ordered iteration or large datasets, prefer Hyperbee storage."},{"type":"chapter-link","label":"Hyperbee storage","chapterId":"sdk-storage-hyperbee"},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-kv/sample-0.js","language":"javascript"},{"type":"paragraph","text":"The Handbook persists reading position and seed version in KV."},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — round-trip write/read/delete succeeded.","`not-granted` — `storage:kv` withheld."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-kv"},{"type":"paragraph","text":"Quotas: Quotas & limits."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"}],"searchText":"key/value storage part iii — developing mini-apps key/value storage <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `storage:kv` is a per-app local store with a byte quota enforced by the host. values are opaque byte arrays — encode json or utf-8 in the sandbox before writing. when to use kv use kv for small persistent state: settings, last-read positions, cached tokens. for ordered iteration or large datasets, prefer hyperbee storage. api the handbook persists reading position and seed version in kv. outcomes `pass` — round-trip write/read/delete succeeded. `not-granted` — `storage:kv` withheld. live probe quotas: quotas & limits."},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Hyperbee storage"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee) namespaced to the app. Keys stay sorted so list ranges are useful for feeds and indexes."},{"type":"heading","level":2,"text":"KV vs Hyperbee"},{"type":"table","headers":["Store","Best for"],"rows":[["KV","Small opaque blobs, settings"],["Hyperbee","Sorted keys, pagination, indexes"]]},{"type":"paragraph","text":"Both are local to the app install and quota-enforced by the host. Hyperbee data does not sync to other devices unless your app implements its own exchange."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-hyperbee/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — put/get/list/delete round-trip succeeded.","`not-granted` — `storage:hyperbee` withheld."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-hyperbee"},{"type":"paragraph","text":"See also Key/value storage."},{"type":"chapter-link","label":"Key/value storage","chapterId":"sdk-storage-kv"}],"searchText":"hyperbee storage part iii — developing mini-apps hyperbee storage <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `storage:hyperbee` opens a local-only ordered key/value store (hyperbee) namespaced to the app. keys stay sorted so list ranges are useful for feeds and indexes. kv vs hyperbee store best for kv small opaque blobs, settings hyperbee sorted keys, pagination, indexes both are local to the app install and quota-enforced by the host. hyperbee data does not sync to other devices unless your app implements its own exchange. api outcomes `pass` — put/get/list/delete round-trip succeeded. `not-granted` — `storage:hyperbee` withheld. live probe see also key/value storage."},{"id":"sdk-lxmf","title":"LXMF messaging","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"LXMF messaging"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"LXMF is store-and-forward messaging on top of Reticulum. Mini-apps use it for app-to-app mailboxes without holding private keys — the host signs and decrypts on behalf of the app destination."},{"type":"heading","level":2,"text":"When to use LXMF"},{"type":"paragraph","text":"Use LXMF when you need asynchronous messages between app destinations: chat, notifications, or command/response patterns that tolerate delay. For bulk binary payloads, use Resource fetch instead."},{"type":"chapter-link","label":"Resource fetch","chapterId":"sdk-resource-fetch"},{"type":"heading","level":2,"text":"Capabilities"},{"type":"list","items":["`lxmf:send` — enqueue an outbound message from this app’s destination.","`lxmf:receive` — read deliveries addressed to this app."]},{"type":"paragraph","text":"Withholding either capability turns the probe below into a `not-granted` card."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-lxmf/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Messages are namespaced to the app id. The host never exposes the device private key."},{"type":"heading","level":2,"text":"Common outcomes"},{"type":"list","items":["`pass` — round-trip to self succeeded on this host.","`unavailable` — LXMF path not configured (leaf without gateway, etc.).","`not-granted` — send or receive capability withheld at install."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"See also Identity & signing and Announce & subscribe."},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"},{"type":"chapter-link","label":"Announce & subscribe","chapterId":"sdk-announce"}],"searchText":"lxmf messaging part iii — developing mini-apps lxmf messaging <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> lxmf is store-and-forward messaging on top of reticulum. mini-apps use it for app-to-app mailboxes without holding private keys — the host signs and decrypts on behalf of the app destination. when to use lxmf use lxmf when you need asynchronous messages between app destinations: chat, notifications, or command/response patterns that tolerate delay. for bulk binary payloads, use resource fetch instead. capabilities `lxmf:send` — enqueue an outbound message from this app’s destination. `lxmf:receive` — read deliveries addressed to this app. withholding either capability turns the probe below into a `not-granted` card. api messages are namespaced to the app id. the host never exposes the device private key. common outcomes `pass` — round-trip to self succeeded on this host. `unavailable` — lxmf path not configured (leaf without gateway, etc.). `not-granted` — send or receive capability withheld at install. live probe see also identity & signing and announce & subscribe."},{"id":"sdk-announce","title":"Announce & subscribe","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Announce & subscribe"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Announces are signed advertisements that a destination is reachable. Subscribe lets a mini-app observe announces in a namespace — useful for discovery without polling links."},{"type":"heading","level":2,"text":"Control-plane role"},{"type":"paragraph","text":"Announces are part of the Reticulum **control plane**. They do not carry bulk data; they tell peers *where* to open a link or which 256t id to fetch."},{"type":"heading","level":2,"text":"Capabilities"},{"type":"list","items":["`announce:publish` — publish this app’s destination.","`announce:subscribe` — receive matching announces."]},{"type":"paragraph","text":"Both are required for the loopback probe below."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-announce/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Namespaces are app-scoped. Publishing without subscribe (or vice versa) limits what probes can demonstrate."},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"announce-loop"},{"type":"paragraph","text":"Concept background: Reticulum fundamentals. Distribution uses announces for app discovery — Publish & install."},{"type":"chapter-link","label":"Reticulum fundamentals","chapterId":"reticulum-fundamentals"},{"type":"chapter-link","label":"Publish & install","chapterId":"sdk-apps-publish"}],"searchText":"announce & subscribe part iii — developing mini-apps announce & subscribe <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> announces are signed advertisements that a destination is reachable. subscribe lets a mini-app observe announces in a namespace — useful for discovery without polling links. control-plane role announces are part of the reticulum **control plane**. they do not carry bulk data; they tell peers *where* to open a link or which 256t id to fetch. capabilities `announce:publish` — publish this app’s destination. `announce:subscribe` — receive matching announces. both are required for the loopback probe below. api namespaces are app-scoped. publishing without subscribe (or vice versa) limits what probes can demonstrate. live probe concept background: reticulum fundamentals. distribution uses announces for app discovery — publish & install."},{"id":"sdk-resource-fetch","title":"Resource fetch","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Resource fetch"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`resource:fetch` asks the host to pull a Resource through its budget rules. The mini-app never sees sockets or peer handles — only bytes (or a typed error)."},{"type":"paragraph","text":"Resources are the Reticulum bulk path when Hyperswarm is unavailable. Budgets vary by link type — see Budgets & quotas."},{"type":"chapter-link","label":"Budgets & quotas","chapterId":"sdk-budgets"},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-resource-fetch/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Exceeding `budgetBytes` fails before transfer starts. The host enforces per-link caps documented in Known limitations §6."},{"type":"chapter-link","label":"Known limitations","chapterId":"ref-limitations"},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — fetch completed within budget.","`unavailable` — no resource server or peer path on this host.","`not-granted` — `resource:fetch` withheld."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"resource-fetch"}],"searchText":"resource fetch part iii — developing mini-apps resource fetch <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `resource:fetch` asks the host to pull a resource through its budget rules. the mini-app never sees sockets or peer handles — only bytes (or a typed error). resources are the reticulum bulk path when hyperswarm is unavailable. budgets vary by link type — see budgets & quotas. api exceeding `budgetbytes` fails before transfer starts. the host enforces per-link caps documented in known limitations §6. outcomes `pass` — fetch completed within budget. `unavailable` — no resource server or peer path on this host. `not-granted` — `resource:fetch` withheld. live probe"},{"id":"sdk-budgets","title":"Budgets & quotas","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Budgets & quotas"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Hosts enforce limits at several layers so constrained links (BLE, LoRa) and shared devices stay predictable. Budgets are not optional hints — exceeding them returns typed errors or truncated transfers."},{"type":"heading","level":2,"text":"Resource fetch (per call)"},{"type":"paragraph","text":"`resource:fetch` takes an explicit `budgetBytes` cap. The host pulls through its link strategy without exposing sockets to the sandbox."},{"type":"code","documentId":"chapters/sdk-budgets/sample-0.js","language":"javascript"},{"type":"applet","appletId":"resource-fetch"},{"type":"heading","level":2,"text":"Package install (per transport)"},{"type":"paragraph","text":"`conformance/budgets/measured.json` records install time at measured bitrates. The BLE guidance target is ~180 KiB for under-one-minute installs; the **full** Handbook is ~295 KiB (~100 s at measured BLE rates) — intentionally above the tiny-app example budget."},{"type":"table","headers":["Package","Size","LAN","BLE","RNode"],"rows":[["tiny hello","< 1 KiB","~1 s","~1 s","~6 s"],["handbook (full)","~304 KiB","~1 s","~100 s","~34 min"],["handbook-part-1-concepts","~62 KiB","~1 s","~21 s","~7 min"],["handbook-part-2-hosts","~76 KiB","~1 s","~26 s","~9 min"],["handbook-part-3-sdk","~147 KiB","~1 s","~49 s","~17 min"],["handbook-part-4-diagnostics","~61 KiB","~1 s","~21 s","~7 min"],["handbook-part-5-reference","~114 KiB","~1 s","~38 s","~13 min"]]},{"type":"paragraph","text":"**Per-part packages** (`handbook-part-1-concepts`, …) are built alongside the full Handbook (`npm run build:handbook` → `generated/part-packages/`). Install one part at a time when BLE bandwidth is tight."},{"type":"heading","level":2,"text":"Host & workspace quotas"},{"type":"paragraph","text":"Node seeding, propagation store, bandwidth caps, workspace file limits, widget tree size, and AI message caps are listed in Quotas & limits. Override desktop/node defaults in `<data-dir>/config.json` — see Host configuration."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"}],"searchText":"budgets & quotas part iii — developing mini-apps budgets & quotas <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> hosts enforce limits at several layers so constrained links (ble, lora) and shared devices stay predictable. budgets are not optional hints — exceeding them returns typed errors or truncated transfers. resource fetch (per call) `resource:fetch` takes an explicit `budgetbytes` cap. the host pulls through its link strategy without exposing sockets to the sandbox. package install (per transport) `conformance/budgets/measured.json` records install time at measured bitrates. the ble guidance target is ~180 kib for under-one-minute installs; the **full** handbook is ~295 kib (~100 s at measured ble rates) — intentionally above the tiny-app example budget. package size lan ble rnode tiny hello < 1 kib ~1 s ~1 s ~6 s handbook (full) ~304 kib ~1 s ~100 s ~34 min handbook-part-1-concepts ~62 kib ~1 s ~21 s ~7 min handbook-part-2-hosts ~76 kib ~1 s ~26 s ~9 min handbook-part-3-sdk ~147 kib ~1 s ~49 s ~17 min handbook-part-4-diagnostics ~61 kib ~1 s ~21 s ~7 min handbook-part-5-reference ~114 kib ~1 s ~38 s ~13 min **per-part packages** (`handbook-part-1-concepts`, …) are built alongside the full handbook (`npm run build:handbook` → `generated/part-packages/`). install one part at a time when ble bandwidth is tight. host & workspace quotas node seeding, propagation store, bandwidth caps, workspace file limits, widget tree size, and ai message caps are listed in quotas & limits. override desktop/node defaults in `<data-dir>/config.json` — see host configuration."},{"id":"sdk-workspace","title":"Workspace","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Workspace"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"`workspace` is a private per-app project filesystem of relative paths (strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this Handbook use it for sources and applet seeds."},{"type":"heading","level":2,"text":"Content-by-reference"},{"type":"paragraph","text":"Large chapter text and applet sources live in workspace files. Widget trees reference them via `code-editor` `documentId` — keeping render payloads under the byte budget."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-workspace/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Paths are relative; traversal outside the app root is rejected. Patch offsets are UTF-16 string indexes. Edits must be ordered and non-overlapping; a stale base length is rejected."},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — write/read/list/remove succeeded.","`not-granted` — `workspace` withheld."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"workspace-rw"},{"type":"paragraph","text":"Packaging reads workspace projects — Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}],"searchText":"workspace part iii — developing mini-apps workspace <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> `workspace` is a private per-app project filesystem of relative paths (strings; 256 kib/file, 4 mib and 512 files per app). devstudio and this handbook use it for sources and applet seeds. content-by-reference large chapter text and applet sources live in workspace files. widget trees reference them via `code-editor` `documentid` — keeping render payloads under the byte budget. api paths are relative; traversal outside the app root is rejected. patch offsets are utf-16 string indexes. edits must be ordered and non-overlapping; a stale base length is rejected. outcomes `pass` — write/read/list/remove succeeded. `not-granted` — `workspace` withheld. live probe packaging reads workspace projects — packaging & preview."},{"id":"sdk-share-cas","title":"Content-addressed share","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Content-addressed share"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`share:cas` stores a bounded string and returns a 94-character 256t id. Paste or scan that id on another device to `share.get` the same bytes — diagnostics reports and DevStudio hand-offs use this path."},{"type":"heading","level":2,"text":"Why CAS for reports"},{"type":"paragraph","text":"Diagnostic JSON can be large. `share.put` returns a stable id suitable for QR codes on the Diagnostics screen. Compare report pastes that id to diff against another host."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-share-cas/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Payload size is capped by the host quota snapshot in `host.info()`."},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — put/get round-trip matched.","`not-granted` — `share:cas` withheld."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"share-cas"},{"type":"paragraph","text":"Used by Running diagnostics export and **Open in DevStudio**."},{"type":"chapter-link","label":"Running diagnostics","chapterId":"running-diagnostics"}],"searchText":"content-addressed share part iii — developing mini-apps content-addressed share <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `share:cas` stores a bounded string and returns a 94-character 256t id. paste or scan that id on another device to `share.get` the same bytes — diagnostics reports and devstudio hand-offs use this path. why cas for reports diagnostic json can be large. `share.put` returns a stable id suitable for qr codes on the diagnostics screen. compare report pastes that id to diff against another host. api payload size is capped by the host quota snapshot in `host.info()`. outcomes `pass` — put/get round-trip matched. `not-granted` — `share:cas` withheld. live probe used by running diagnostics export and **open in devstudio**."},{"id":"sdk-capabilities","title":"Capability model","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Capability model"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Mini-apps declare every SDK surface they may use in `app.manifest.json`. At install the host shows the full list; the user may grant a **subset**. The broker enforces grants on every call — withheld capabilities are not errors in the Handbook, they become `not-granted` teaching cards."},{"type":"heading","level":2,"text":"Manifest"},{"type":"code","documentId":"chapters/sdk-capabilities/sample-0.json","language":"json"},{"type":"paragraph","text":"Only ids from `CAPABILITY_DEFINITIONS` are valid. The reference list is generated at build time: Capabilities."},{"type":"chapter-link","label":"Capabilities","chapterId":"ref-capabilities"},{"type":"heading","level":2,"text":"Typed errors"},{"type":"paragraph","text":"The runtime throws `CapabilityError` with a stable `code`:"},{"type":"table","headers":["Code","Meaning"],"rows":[["`UNKNOWN_CAPABILITY`","Manifest names a capability the host does not recognize"],["`UNDECLARED_CAPABILITY`","Code calls a capability not listed in the manifest"],["`CAPABILITY_DENIED`","Manifest lists it but the user withheld the grant"]]},{"type":"code","documentId":"chapters/sdk-capabilities/sample-1.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Withhold `identity` at install (or tap **Revoke** in host settings) and re-run the applet — it reports `not-granted` instead of throwing into your UI."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Double-gated capabilities (`apps:package`, `apps:publish`, `apps:install`, `apps:preview`) also require a host-chrome confirmation the sandbox cannot dismiss. See Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}],"searchText":"capability model part iii — developing mini-apps capability model <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> mini-apps declare every sdk surface they may use in `app.manifest.json`. at install the host shows the full list; the user may grant a **subset**. the broker enforces grants on every call — withheld capabilities are not errors in the handbook, they become `not-granted` teaching cards. manifest only ids from `capability_definitions` are valid. the reference list is generated at build time: capabilities. typed errors the runtime throws `capabilityerror` with a stable `code`: code meaning `unknown_capability` manifest names a capability the host does not recognize `undeclared_capability` code calls a capability not listed in the manifest `capability_denied` manifest lists it but the user withheld the grant live probe withhold `identity` at install (or tap **revoke** in host settings) and re-run the applet — it reports `not-granted` instead of throwing into your ui. double-gated capabilities (`apps:package`, `apps:publish`, `apps:install`, `apps:preview`) also require a host-chrome confirmation the sandbox cannot dismiss. see packaging & preview."},{"id":"sdk-apps-package","title":"Packaging & preview","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Packaging & preview"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`apps:package` and `apps:preview` are double-gated: the capability grant plus a host-chrome confirmation the mini-app cannot dismiss. Package signs under the device publisher identity; preview runs the project in the single sandboxed dev-preview slot."},{"type":"heading","level":2,"text":"Deterministic packages"},{"type":"paragraph","text":"`tp pack` and `apps.packageProject` produce deterministic `.tpkg` archives — same inputs yield the same hash. That makes 256t ids stable for distribution and CI."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-package/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Only one preview slot exists per host. Stop preview before starting another."},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Use **Run applet** for the automated inline probe (package → preview → stop, used in CI)."},{"type":"paragraph","text":"Use **Run as real app** to launch the sample in the host dev-preview slot — the full sandbox/grant/launch loop with host confirmation. Stop preview when finished."},{"type":"applet","appletId":"apps-package-preview"},{"type":"paragraph","text":"Next: Publish & install. Format reference: Package format."},{"type":"chapter-link","label":"Publish & install","chapterId":"sdk-apps-publish"},{"type":"chapter-link","label":"Package format","chapterId":"ref-packages"}],"searchText":"packaging & preview part iii — developing mini-apps packaging & preview <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `apps:package` and `apps:preview` are double-gated: the capability grant plus a host-chrome confirmation the mini-app cannot dismiss. package signs under the device publisher identity; preview runs the project in the single sandboxed dev-preview slot. deterministic packages `tp pack` and `apps.packageproject` produce deterministic `.tpkg` archives — same inputs yield the same hash. that makes 256t ids stable for distribution and ci. api only one preview slot exists per host. stop preview before starting another. live probe use **run applet** for the automated inline probe (package → preview → stop, used in ci). use **run as real app** to launch the sample in the host dev-preview slot — the full sandbox/grant/launch loop with host confirmation. stop preview when finished. next: publish & install. format reference: package format."},{"id":"sdk-apps-publish","title":"Publish & install","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Publish & install"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"`apps:publish` announces a packaged 256t id under the publisher identity. `apps:install` asks the host to fetch, verify, and review capabilities before anything runs. Both raise a confirmation dialog on every call."},{"type":"heading","level":2,"text":"Discover → trust → install"},{"type":"paragraph","text":"Discovery is announce-driven: users find a 256t id, verify the publisher signature, grant capabilities, then launch. There is no central store — trust is signature-based."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-publish/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Package first with `apps.packageProject` — see Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — publish and install succeeded with host confirmations approved.","`not-granted` — `apps:publish` or `apps:install` withheld.","`unavailable` — distribution backend not configured on this host."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"apps-publish-install"},{"type":"paragraph","text":"OTA updates reuse the same APIs with a bumped semver — Publish, install & update."},{"type":"chapter-link","label":"Publish, install & update","chapterId":"sdk-apps-update"}],"searchText":"publish & install part iii — developing mini-apps publish & install <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> `apps:publish` announces a packaged 256t id under the publisher identity. `apps:install` asks the host to fetch, verify, and review capabilities before anything runs. both raise a confirmation dialog on every call. discover → trust → install discovery is announce-driven: users find a 256t id, verify the publisher signature, grant capabilities, then launch. there is no central store — trust is signature-based. api package first with `apps.packageproject` — see packaging & preview. outcomes `pass` — publish and install succeeded with host confirmations approved. `not-granted` — `apps:publish` or `apps:install` withheld. `unavailable` — distribution backend not configured on this host. live probe ota updates reuse the same apis with a bumped semver — publish, install & update."},{"id":"sdk-apps-update","title":"Publish, install & update","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Publish, install & update"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"Distribution is a three-step loop: **package** a signed `.tpkg`, **publish** its 256t id under your publisher identity, and **install** on any host that discovers the announce. **Update** is the same path with a bumped semver — the host fetches the newer archive and replaces the installed copy."},{"type":"heading","level":2,"text":"Why confirmations exist"},{"type":"paragraph","text":"`apps:publish` and `apps:install` are double-gated: the manifest must declare the capability and the host shows a confirmation on every call. That mirrors how end users experience installs outside DevStudio."},{"type":"heading","level":2,"text":"Publish & install"},{"type":"code","documentId":"chapters/sdk-apps-update/sample-0.js","language":"javascript"},{"type":"paragraph","text":"See Publish & install for the first-install probe."},{"type":"chapter-link","label":"Publish & install","chapterId":"sdk-apps-publish"},{"type":"heading","level":2,"text":"OTA update"},{"type":"paragraph","text":"Bump `version` in the manifest, repack, and publish again. Hosts that already installed the app resolve the new 256t id through Hyperdrive or Resource fallback."},{"type":"code","documentId":"chapters/sdk-apps-update/sample-1.js","language":"javascript"},{"type":"paragraph","text":"CLI equivalent: `tp update <app-dir> --version <semver>` — see CLI commands."},{"type":"chapter-link","label":"CLI commands","chapterId":"ref-cli"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"apps-update"},{"type":"paragraph","text":"Transport budgets for large packages: Budgets & quotas. Package format: Package format."},{"type":"chapter-link","label":"Budgets & quotas","chapterId":"sdk-budgets"},{"type":"chapter-link","label":"Package format","chapterId":"ref-packages"}],"searchText":"publish, install & update part iii — developing mini-apps publish, install & update <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> distribution is a three-step loop: **package** a signed `.tpkg`, **publish** its 256t id under your publisher identity, and **install** on any host that discovers the announce. **update** is the same path with a bumped semver — the host fetches the newer archive and replaces the installed copy. why confirmations exist `apps:publish` and `apps:install` are double-gated: the manifest must declare the capability and the host shows a confirmation on every call. that mirrors how end users experience installs outside devstudio. publish & install see publish & install for the first-install probe. ota update bump `version` in the manifest, repack, and publish again. hosts that already installed the app resolve the new 256t id through hyperdrive or resource fallback. cli equivalent: `tp update <app-dir> --version <semver>` — see cli commands. live probe transport budgets for large packages: budgets & quotas. package format: package format."},{"id":"sdk-devstudio","title":"DevStudio walkthrough","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"DevStudio walkthrough"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"DevStudio is a mini-app IDE — same sandbox and capability model as any other app. Desktop first-boot seeds it alongside this Handbook."},{"type":"heading","level":2,"text":"Development loop"},{"type":"paragraph","text":"1. **New project** — DevStudio seeds `hello-app/app.json` + `bundle.js` in the app workspace. 2. **Edit** — the `code-editor` widget is content-by-reference: the tree carries a `documentId`; edits flow back as events and persist with `workspace.write`. 3. **AI assist** — with `ai:chat` granted, describe a change; the host holds the API key and model (never in the sandbox). Review whole-file proposals before **Apply**. 4. **Preview** — `apps:preview` runs the project in the single dev-preview slot while DevStudio keeps running. 5. **Package & sign** — host confirmation; deterministic `.tpkg` under the device publisher identity; 256t id + QR. 6. **Publish** — host confirmation; seed on Hyperdrive and announce the locator."},{"type":"heading","level":2,"text":"Open in DevStudio from the Handbook"},{"type":"paragraph","text":"Every applet card includes **Open in DevStudio**. The Handbook exports the applet source plus a `tp.devstudio.workspace.v1` handoff via `share:cas`; paste or scan the QR in DevStudio to import the sample as a starting project."},{"type":"paragraph","text":"Try it on the identity probe below, then continue in DevStudio with Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"},{"type":"applet","appletId":"identity-hash"}],"searchText":"devstudio walkthrough part iii — developing mini-apps devstudio walkthrough <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> devstudio is a mini-app ide — same sandbox and capability model as any other app. desktop first-boot seeds it alongside this handbook. development loop 1. **new project** — devstudio seeds `hello-app/app.json` + `bundle.js` in the app workspace. 2. **edit** — the `code-editor` widget is content-by-reference: the tree carries a `documentid`; edits flow back as events and persist with `workspace.write`. 3. **ai assist** — with `ai:chat` granted, describe a change; the host holds the api key and model (never in the sandbox). review whole-file proposals before **apply**. 4. **preview** — `apps:preview` runs the project in the single dev-preview slot while devstudio keeps running. 5. **package & sign** — host confirmation; deterministic `.tpkg` under the device publisher identity; 256t id + qr. 6. **publish** — host confirmation; seed on hyperdrive and announce the locator. open in devstudio from the handbook every applet card includes **open in devstudio**. the handbook exports the applet source plus a `tp.devstudio.workspace.v1` handoff via `share:cas`; paste or scan the qr in devstudio to import the sample as a starting project. try it on the identity probe below, then continue in devstudio with packaging & preview."},{"id":"sdk-ai-chat","title":"AI chat","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"AI chat"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint; `ai:embed` sends bounded text to its separately configured embedding model. The host clamps budgets, enforces a model allowlist, and allows one in-flight request per app. The API key never enters the sandbox."},{"type":"heading","level":2,"text":"Host configuration"},{"type":"paragraph","text":"Desktop hosts configure AI under **Settings → AI** or in `config.json`. Until an endpoint is set, probes report `unavailable` — that is honest, not a failure. Embeddings remain unavailable until an embedding model is also set."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-ai-chat/sample-0.js","language":"javascript"},{"type":"paragraph","text":"Whole responses and final stream events include model id and usage counters when the host provides them. Stream deltas are coalesced and are not token boundaries. Both calls share one in-flight slot per app; breaking out of iteration cancels the stream. Embedding and search calls share that slot. Search accepts at most 63 documents and returns ids plus cosine scores; it does not create a persistent host index."},{"type":"heading","level":2,"text":"Outcomes"},{"type":"list","items":["`pass` — round-trip succeeded.","`unavailable` — no AI endpoint configured.","`not-granted` — `ai:chat` withheld.","`not-granted` — `ai:embed` withheld for embedding/search probes."]},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Hosts without an AI endpoint report `unavailable`. When configured, the applet below exercises a single round-trip."},{"type":"applet","appletId":"ai-chat"},{"type":"paragraph","text":"DevStudio uses the same proxy for whole-file edits — DevStudio walkthrough."},{"type":"chapter-link","label":"DevStudio walkthrough","chapterId":"sdk-devstudio"}],"searchText":"ai chat part iii — developing mini-apps ai chat <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> `ai:chat` sends prompts to the host-configured openrouter-compatible endpoint; `ai:embed` sends bounded text to its separately configured embedding model. the host clamps budgets, enforces a model allowlist, and allows one in-flight request per app. the api key never enters the sandbox. host configuration desktop hosts configure ai under **settings → ai** or in `config.json`. until an endpoint is set, probes report `unavailable` — that is honest, not a failure. embeddings remain unavailable until an embedding model is also set. api whole responses and final stream events include model id and usage counters when the host provides them. stream deltas are coalesced and are not token boundaries. both calls share one in-flight slot per app; breaking out of iteration cancels the stream. embedding and search calls share that slot. search accepts at most 63 documents and returns ids plus cosine scores; it does not create a persistent host index. outcomes `pass` — round-trip succeeded. `unavailable` — no ai endpoint configured. `not-granted` — `ai:chat` withheld. `not-granted` — `ai:embed` withheld for embedding/search probes. live probe hosts without an ai endpoint report `unavailable`. when configured, the applet below exercises a single round-trip. devstudio uses the same proxy for whole-file edits — devstudio walkthrough."},{"id":"sdk-widget-gallery","title":"Widget gallery","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Widget gallery"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"The widget protocol is the cross-platform UI seam. Allowed components: `view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`, `progress`, `divider`, `spacer`, `code-editor`, `qr-code`."},{"type":"paragraph","text":"Hosts on Android, iOS, desktop, and web render the same declarative tree — mini-apps do not ship native UI code."},{"type":"heading","level":2,"text":"Content-by-reference"},{"type":"paragraph","text":"`code-editor` loads workspace files by `documentId`; `qr-code` accepts up to 512 characters (94-char 256t ids fit). The host rejects unknown props, styles, duplicate ids, and oversized trees."},{"type":"heading","level":2,"text":"Component roles"},{"type":"list","items":["**Layout** — `view`, `scroll`, `spacer`, `divider`","**Input** — `button`, `text-input`, `switch`","**Display** — `text`, `image`, `progress`, `list`, `qr-code`","**Docs** — `code-editor` for samples and applet sources"]},{"type":"paragraph","text":"Schema reference: Widget protocol."},{"type":"chapter-link","label":"Widget protocol","chapterId":"ref-widgets"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet submits a tree that includes every component type. After it reports, the Handbook re-renders this chapter with the result card."},{"type":"applet","appletId":"widget-gallery"}],"searchText":"widget gallery part iii — developing mini-apps widget gallery <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> the widget protocol is the cross-platform ui seam. allowed components: `view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`, `progress`, `divider`, `spacer`, `code-editor`, `qr-code`. hosts on android, ios, desktop, and web render the same declarative tree — mini-apps do not ship native ui code. content-by-reference `code-editor` loads workspace files by `documentid`; `qr-code` accepts up to 512 characters (94-char 256t ids fit). the host rejects unknown props, styles, duplicate ids, and oversized trees. component roles **layout** — `view`, `scroll`, `spacer`, `divider` **input** — `button`, `text-input`, `switch` **display** — `text`, `image`, `progress`, `list`, `qr-code` **docs** — `code-editor` for samples and applet sources schema reference: widget protocol. live probe the applet submits a tree that includes every component type. after it reports, the handbook re-renders this chapter with the result card."},{"id":"running-diagnostics","title":"Running diagnostics","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Running diagnostics"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Each applet reports `{ appletId, status, details, timings }` with first-class `unavailable` and `not-granted` outcomes — teaching moments, not hard errors."},{"type":"heading","level":2,"text":"On this screen"},{"type":"paragraph","text":"From the Handbook **Contents**, open **Diagnostics** to:"},{"type":"list","items":["**Run all diagnostics** — runs every catalog applet inline on this host, grouped"]},{"type":"paragraph","text":"by area (crypto, interfaces, storage, distribution, runtime)"},{"type":"list","items":["**Export report** — packs host info + results into JSON, stores via `share.put`,"]},{"type":"paragraph","text":"shows a 256t id / QR"},{"type":"list","items":["**Compare report** — paste another device's report id to render a status matrix"]},{"type":"paragraph","text":"with expected platform differences marked"},{"type":"paragraph","text":"Open an SDK chapter and tap **Run applet** for a single probe."},{"type":"heading","level":2,"text":"Software-tier probes"},{"type":"list","items":["Host info — `host.info` (`presence`)","App destination hash — `identity`","Presence snapshot — `presence`","KV round-trip — `storage:kv`","Hyperbee round-trip — `storage:hyperbee`","LXMF self-message — `identity`, `lxmf:*`","Announce publish/subscribe — `announce:*`","Resource fetch — `resource:fetch`","Workspace read/write — `workspace`","CAS share — `share:cas`","Package + preview — `apps:package`, `apps:preview`","Publish + install — `apps:publish`, `apps:install`","OTA update — republish with bumped semver","AI chat / embedding configuration — `ai:chat`, `ai:embed`","Widget gallery — widget protocol"]},{"type":"paragraph","text":"Device-gated probes (BLE peer, RNode, multicast, camera QR) live in Device-gated probes — they report `unavailable` in CI and simulators with guided procedures for real hardware."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"},{"type":"paragraph","text":"Compare matrices use each applet’s expectation table to label platform differences as expected (`≈`) or unexpected (`≠`)."}],"searchText":"running diagnostics part iv — diagnostics running diagnostics <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> each applet reports `{ appletid, status, details, timings }` with first-class `unavailable` and `not-granted` outcomes — teaching moments, not hard errors. on this screen from the handbook **contents**, open **diagnostics** to: **run all diagnostics** — runs every catalog applet inline on this host, grouped by area (crypto, interfaces, storage, distribution, runtime) **export report** — packs host info + results into json, stores via `share.put`, shows a 256t id / qr **compare report** — paste another device's report id to render a status matrix with expected platform differences marked open an sdk chapter and tap **run applet** for a single probe. software-tier probes host info — `host.info` (`presence`) app destination hash — `identity` presence snapshot — `presence` kv round-trip — `storage:kv` hyperbee round-trip — `storage:hyperbee` lxmf self-message — `identity`, `lxmf:*` announce publish/subscribe — `announce:*` resource fetch — `resource:fetch` workspace read/write — `workspace` cas share — `share:cas` package + preview — `apps:package`, `apps:preview` publish + install — `apps:publish`, `apps:install` ota update — republish with bumped semver ai chat / embedding configuration — `ai:chat`, `ai:embed` widget gallery — widget protocol device-gated probes (ble peer, rnode, multicast, camera qr) live in device-gated probes — they report `unavailable` in ci and simulators with guided procedures for real hardware. compare matrices use each applet’s expectation table to label platform differences as expected (`≈`) or unexpected (`≠`)."},{"id":"device-gated-probes","title":"Device-gated probes","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Device-gated probes"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-10 register: none -->"},{"type":"paragraph","text":"These applets need **real hardware or a guided manual step** on a phone. In CI and simulators they report `unavailable` with the procedure below — that is expected, not a failure."},{"type":"paragraph","text":"When you complete a procedure on real hardware, register the run in the repo’s `STATUS-HARDWARE.md` (Handbook rows H21–H22)."},{"type":"heading","level":2,"text":"Before you start"},{"type":"list","items":["Use two peers on the same LAN for BLE and AutoInterface probes when possible.","Keep the host app in the **foreground** during discovery windows.","Export a diagnostic report on each device and use **Compare report** to diff results."]},{"type":"heading","level":2,"text":"BLE peer"},{"type":"paragraph","text":"Requires two phones with BLE enabled and the BLE interface turned on in host settings. Expect `unavailable` in simulators; on hardware you should see at least one peer in presence before the applet reports `pass`."},{"type":"applet","appletId":"ble-peer"},{"type":"heading","level":2,"text":"RNode serial / LoRa"},{"type":"paragraph","text":"Connect an RNode per the host interface docs. Enable the RNode interface, then run the probe. Desktop and Android support USB serial; iOS uses BLE to the RNode."},{"type":"applet","appletId":"rnode-serial"},{"type":"heading","level":2,"text":"Multicast / AutoInterface"},{"type":"paragraph","text":"Two LAN peers with AutoInterface or Bonjour discovery enabled. iOS may need the multicast entitlement — see Known limitations §4."},{"type":"chapter-link","label":"Known limitations","chapterId":"ref-limitations"},{"type":"applet","appletId":"multicast-auto"},{"type":"heading","level":2,"text":"Camera QR scan"},{"type":"paragraph","text":"Point the device camera at a Handbook diagnostic report QR or any valid 256t id QR generated on another screen. Simulators lack a camera path and report `unavailable`."},{"type":"applet","appletId":"camera-qr-scan"},{"type":"paragraph","text":"After hardware runs, compare reports: Running diagnostics."},{"type":"chapter-link","label":"Running diagnostics","chapterId":"running-diagnostics"}],"searchText":"device-gated probes part iv — diagnostics device-gated probes <!-- tp-doc lifecycle: live audited: 2026-07-10 register: none --> these applets need **real hardware or a guided manual step** on a phone. in ci and simulators they report `unavailable` with the procedure below — that is expected, not a failure. when you complete a procedure on real hardware, register the run in the repo’s `status-hardware.md` (handbook rows h21–h22). before you start use two peers on the same lan for ble and autointerface probes when possible. keep the host app in the **foreground** during discovery windows. export a diagnostic report on each device and use **compare report** to diff results. ble peer requires two phones with ble enabled and the ble interface turned on in host settings. expect `unavailable` in simulators; on hardware you should see at least one peer in presence before the applet reports `pass`. rnode serial / lora connect an rnode per the host interface docs. enable the rnode interface, then run the probe. desktop and android support usb serial; ios uses ble to the rnode. multicast / autointerface two lan peers with autointerface or bonjour discovery enabled. ios may need the multicast entitlement — see known limitations §4. camera qr scan point the device camera at a handbook diagnostic report qr or any valid 256t id qr generated on another screen. simulators lack a camera path and report `unavailable`. after hardware runs, compare reports: running diagnostics."},{"id":"ref-capabilities","title":"Capabilities","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Capabilities"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Generated from `CAPABILITY_DEFINITIONS` in `packages/miniapp-runtime`. Every id below must be exercised by at least one Handbook applet (coverage gate)."},{"type":"list","items":["**`identity`** — Use an app-scoped identity for signing and addressing.","**`presence`** — Read coarse peer/interface presence and host info.","**`announce:subscribe`** — Receive announces in the app namespace.","**`announce:publish`** — Publish the app destination.","**`lxmf:send`** — Send LXMF messages from the app destination.","**`lxmf:receive`** — Receive LXMF messages for the app destination.","**`storage:kv`** — Store local key/value data for this app.","**`storage:hyperbee`** — Store ordered local Hyperbee data for this app.","**`resource:fetch`** — Fetch package resources through host budget rules.","**`workspace`** — Read and write project source files in this app's private workspace.","**`ai:chat`** — Send prompts to the host-configured AI service; prompts may include workspace content.","**`ai:embed`** — Send bounded text to the host-configured embedding model and rank vectors locally.","**`apps:package`** — Package and sign apps under this device's publisher identity (asks each time).","**`apps:publish`** — Publish signed apps so other users can find and install them (asks each time).","**`apps:install`** — Ask the host to install apps from a 256t id (asks each time, with capability review).","**`apps:preview`** — Run a built app in the host's sandboxed dev-preview slot.","**`share:cas`** — Store and retrieve bounded content-addressed data shared by 256t id."]},{"type":"paragraph","text":"Manifests declare the full list; users may grant a subset at install. Withholding a capability turns matching probes into `not-granted` cards."},{"type":"paragraph","text":"Tutorial: Capability model. Per-namespace guides: Developing mini-apps."},{"type":"chapter-link","label":"Capability model","chapterId":"sdk-capabilities"},{"type":"chapter-link","label":"Developing mini-apps","chapterId":"sdk-identity"}],"searchText":"capabilities part v — reference capabilities <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> generated from `capability_definitions` in `packages/miniapp-runtime`. every id below must be exercised by at least one handbook applet (coverage gate). **`identity`** — use an app-scoped identity for signing and addressing. **`presence`** — read coarse peer/interface presence and host info. **`announce:subscribe`** — receive announces in the app namespace. **`announce:publish`** — publish the app destination. **`lxmf:send`** — send lxmf messages from the app destination. **`lxmf:receive`** — receive lxmf messages for the app destination. **`storage:kv`** — store local key/value data for this app. **`storage:hyperbee`** — store ordered local hyperbee data for this app. **`resource:fetch`** — fetch package resources through host budget rules. **`workspace`** — read and write project source files in this app's private workspace. **`ai:chat`** — send prompts to the host-configured ai service; prompts may include workspace content. **`ai:embed`** — send bounded text to the host-configured embedding model and rank vectors locally. **`apps:package`** — package and sign apps under this device's publisher identity (asks each time). **`apps:publish`** — publish signed apps so other users can find and install them (asks each time). **`apps:install`** — ask the host to install apps from a 256t id (asks each time, with capability review). **`apps:preview`** — run a built app in the host's sandboxed dev-preview slot. **`share:cas`** — store and retrieve bounded content-addressed data shared by 256t id. manifests declare the full list; users may grant a subset at install. withholding a capability turns matching probes into `not-granted` cards. tutorial: capability model. per-namespace guides: developing mini-apps."},{"id":"ref-widgets","title":"Widget protocol","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Widget protocol"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Generated from `WIDGET_TYPES` / `WIDGET_PROP_KEYS` in `packages/miniapp-runtime`."},{"type":"paragraph","text":"Hosts render a declarative tree (`ui.render`). Unknown types, props, styles, duplicate ids, or oversized trees are rejected."},{"type":"heading","level":2,"text":"Components"},{"type":"list","items":["**`button`** — props: `event`, `label`","**`code-editor`** — props: `documentId`, `event`, `language`, `readOnly`","**`divider`** — props: none","**`image`** — props: `alt`, `asset`","**`list`** — props: `event`, `items`","**`progress`** — props: `max`, `value`","**`qr-code`** — props: `caption`, `size`, `value`","**`scroll`** — props: `event`, `scrollOffset`","**`spacer`** — props: `size`","**`switch`** — props: `event`, `value`","**`text`** — props: `value`","**`text-input`** — props: `event`, `placeholder`, `value`","**`view`** — props: `accessibilityLabel`"]},{"type":"heading","level":2,"text":"Styles"},{"type":"list","items":["`alignItems`","`backgroundColor`","`color`","`display`","`flexDirection`","`fontSize`","`fontWeight`","`gap`","`height`","`justifyContent`","`margin`","`padding`","`width`"]},{"type":"heading","level":2,"text":"Limits"},{"type":"list","items":["Widget tree JSON budget: 256 KiB (default validator)","`code-editor` languages: javascript, json, text","`qr-code` value: up to 512 characters (94-char 256t ids fit)"]},{"type":"paragraph","text":"Live gallery: Widget gallery."},{"type":"chapter-link","label":"Widget gallery","chapterId":"sdk-widget-gallery"}],"searchText":"widget protocol part v — reference widget protocol <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> generated from `widget_types` / `widget_prop_keys` in `packages/miniapp-runtime`. hosts render a declarative tree (`ui.render`). unknown types, props, styles, duplicate ids, or oversized trees are rejected. components **`button`** — props: `event`, `label` **`code-editor`** — props: `documentid`, `event`, `language`, `readonly` **`divider`** — props: none **`image`** — props: `alt`, `asset` **`list`** — props: `event`, `items` **`progress`** — props: `max`, `value` **`qr-code`** — props: `caption`, `size`, `value` **`scroll`** — props: `event`, `scrolloffset` **`spacer`** — props: `size` **`switch`** — props: `event`, `value` **`text`** — props: `value` **`text-input`** — props: `event`, `placeholder`, `value` **`view`** — props: `accessibilitylabel` styles `alignitems` `backgroundcolor` `color` `display` `flexdirection` `fontsize` `fontweight` `gap` `height` `justifycontent` `margin` `padding` `width` limits widget tree json budget: 256 kib (default validator) `code-editor` languages: javascript, json, text `qr-code` value: up to 512 characters (94-char 256t ids fit) live gallery: widget gallery."},{"id":"ref-host-api","title":"Host API","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Host API"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Current `HOST_API_VERSION`: **`0.7.0`**. Manifests pin `minHostApi`; hosts reject packages that require a newer API."},{"type":"heading","level":2,"text":"Changelog"},{"type":"list","items":["**`0.1.0`** — Initial mini-app host API: capabilities, broker, lifecycle, widget tree UI, and SDK v1 namespaces.","**`0.2.0`** — Dev-environment capabilities (workspace, ai:chat, apps:*, share:cas), host confirmation channel, dynamic resource limits, pre-launch capability review, code-editor and qr-code widgets.","**`0.3.0`** — host.info() — platform id, host version, HOST_API_VERSION, enabled roles, interface types, and quota snapshot for Handbook diagnostics.","**`0.4.0`** — host.info() includes grantedCapabilities for the calling mini-app (Handbook grant intro and diagnostics).","**`0.5.0`** — ai.chatStream() adds cancellable, coalesced streaming while preserving ai.chat().","**`0.6.0`** — ai.embed() and ai.search() add host-proxied embeddings and bounded cosine vector search.","**`0.7.0`** — workspace.patch() and delta code-editor events add conflict-safe incremental editing."]},{"type":"heading","level":2,"text":"host.info()"},{"type":"paragraph","text":"Returns platform id, host version, API version, roles, interface types, and quota snapshot — used by the live difference matrix."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":2,"text":"Workspace quotas"},{"type":"list","items":["262144 bytes/file","4194304 bytes total per app","512 files per app"]}],"searchText":"host api part v — reference host api <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> current `host_api_version`: **`0.7.0`**. manifests pin `minhostapi`; hosts reject packages that require a newer api. changelog **`0.1.0`** — initial mini-app host api: capabilities, broker, lifecycle, widget tree ui, and sdk v1 namespaces. **`0.2.0`** — dev-environment capabilities (workspace, ai:chat, apps:*, share:cas), host confirmation channel, dynamic resource limits, pre-launch capability review, code-editor and qr-code widgets. **`0.3.0`** — host.info() — platform id, host version, host_api_version, enabled roles, interface types, and quota snapshot for handbook diagnostics. **`0.4.0`** — host.info() includes grantedcapabilities for the calling mini-app (handbook grant intro and diagnostics). **`0.5.0`** — ai.chatstream() adds cancellable, coalesced streaming while preserving ai.chat(). **`0.6.0`** — ai.embed() and ai.search() add host-proxied embeddings and bounded cosine vector search. **`0.7.0`** — workspace.patch() and delta code-editor events add conflict-safe incremental editing. host.info() returns platform id, host version, api version, roles, interface types, and quota snapshot — used by the live difference matrix. workspace quotas 262144 bytes/file 4194304 bytes total per app 512 files per app"},{"id":"ref-packages","title":"Package format","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Package format"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Mini-apps ship as deterministic **`.tpkg`** archives:"},{"type":"list","items":["Signed manifest (name, version, entry, capabilities, publisher key, `minHostApi`)","Entry bundle (`bundle.js`) and assets","Ed25519 signature over the manifest hash"]},{"type":"paragraph","text":"Packaging flow: Packaging & preview. Distribution tutorial: Publish, install & update."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"},{"type":"chapter-link","label":"Publish, install & update","chapterId":"sdk-apps-update"}],"searchText":"package format part v — reference package format <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> mini-apps ship as deterministic **`.tpkg`** archives: signed manifest (name, version, entry, capabilities, publisher key, `minhostapi`) entry bundle (`bundle.js`) and assets ed25519 signature over the manifest hash packaging flow: packaging & preview. distribution tutorial: publish, install & update."},{"id":"ref-interfaces","title":"Network interfaces","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Network interfaces"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Reticulum peers attach through typed **PacketInterface** implementations. The live difference matrix lists which types `host.info()` reports for **this** host."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":2,"text":"WebSocket (browser gateway)"},{"type":"list","items":["**Leaf client** — browser tab or CI harness dials `ws://` / `wss://` on a gateway.","**Gateway** — desktop host or `tp node --ws-listen [host:]port`.","**Framing** — one Reticulum wire packet per binary WebSocket message.","**Auth** — optional shared token (`--ws-token`)."]},{"type":"paragraph","text":"Web host chapter: Web host."},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"paragraph","text":"WebSocket wire format is documented in the platform repo under `docs/websocket-interface.md` (not shipped inside the Handbook bundle)."},{"type":"heading","level":2,"text":"TCP / AutoInterface / Bonjour"},{"type":"paragraph","text":"Desktop and mobile worklets enable TCP client mode, LAN multicast (AutoInterface), and Bonjour discovery when the platform permits. iOS multicast requires the networking multicast entitlement; web hosts omit these entirely."},{"type":"heading","level":2,"text":"BLE phone pipe"},{"type":"paragraph","text":"Android and iOS expose a BLE GATT byte stream for peer links. Web Bluetooth is central-only and not used for the phone-pipe role. Device-gated Handbook probes: Device-gated probes."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"},{"type":"heading","level":2,"text":"RNode serial"},{"type":"paragraph","text":"USB serial on desktop/Android; BLE-only on iOS. WebSerial (Chromium) is optional. LoRa bandwidth budgets apply — see Known limitations §6."},{"type":"chapter-link","label":"Known limitations","chapterId":"ref-limitations"}],"searchText":"network interfaces part v — reference network interfaces <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> reticulum peers attach through typed **packetinterface** implementations. the live difference matrix lists which types `host.info()` reports for **this** host. websocket (browser gateway) **leaf client** — browser tab or ci harness dials `ws://` / `wss://` on a gateway. **gateway** — desktop host or `tp node --ws-listen [host:]port`. **framing** — one reticulum wire packet per binary websocket message. **auth** — optional shared token (`--ws-token`). web host chapter: web host. websocket wire format is documented in the platform repo under `docs/websocket-interface.md` (not shipped inside the handbook bundle). tcp / autointerface / bonjour desktop and mobile worklets enable tcp client mode, lan multicast (autointerface), and bonjour discovery when the platform permits. ios multicast requires the networking multicast entitlement; web hosts omit these entirely. ble phone pipe android and ios expose a ble gatt byte stream for peer links. web bluetooth is central-only and not used for the phone-pipe role. device-gated handbook probes: device-gated probes. rnode serial usb serial on desktop/android; ble-only on ios. webserial (chromium) is optional. lora bandwidth budgets apply — see known limitations §6."},{"id":"ref-quotas","title":"Quotas & limits","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Quotas & limits"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Generated from `DEFAULT_QUOTAS` (`host-core`) and miniapp-runtime defaults. `host.info()` includes a quota snapshot for diagnostics."},{"type":"heading","level":2,"text":"Host node quotas (desktop / `tp node`)"},{"type":"list","items":["Seed storage: 2147483648 bytes","Propagation store: 268435456 bytes","Propagation messages: 10000","Bandwidth cap: 524288 bytes/s"]},{"type":"paragraph","text":"Override in `<data-dir>/config.json` — see Host configuration."},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"},{"type":"heading","level":2,"text":"Mini-app workspace (`workspace` capability)"},{"type":"list","items":["262144 bytes per file","4194304 bytes total per app","512 files per app"]},{"type":"heading","level":2,"text":"Widget & AI limits"},{"type":"list","items":["Widget tree JSON: 256 KiB (default validator)","AI chat: 64 messages, 8192 max tokens cap"]},{"type":"heading","level":2,"text":"Transport budgets"},{"type":"paragraph","text":"BLE install budgets (~180 KiB at measured rates) and Resource fetch caps are enforced per link type. See Resource fetch and `conformance/budgets/measured.json`."},{"type":"chapter-link","label":"Resource fetch","chapterId":"sdk-resource-fetch"}],"searchText":"quotas & limits part v — reference quotas & limits <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> generated from `default_quotas` (`host-core`) and miniapp-runtime defaults. `host.info()` includes a quota snapshot for diagnostics. host node quotas (desktop / `tp node`) seed storage: 2147483648 bytes propagation store: 268435456 bytes propagation messages: 10000 bandwidth cap: 524288 bytes/s override in `<data-dir>/config.json` — see host configuration. mini-app workspace (`workspace` capability) 262144 bytes per file 4194304 bytes total per app 512 files per app widget & ai limits widget tree json: 256 kib (default validator) ai chat: 64 messages, 8192 max tokens cap transport budgets ble install budgets (~180 kib at measured rates) and resource fetch caps are enforced per link type. see resource fetch and `conformance/budgets/measured.json`."},{"id":"ref-host-config","title":"Host configuration","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Host configuration"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Generated from `defaultHostConfig()` defaults in `packages/host-core`. Desktop and `tp node` persist overrides in `<data-dir>/config.json`."},{"type":"heading","level":2,"text":"Data directory"},{"type":"list","items":["macOS: `~/Library/Application Support/TwistedPear/host`","Linux: `~/.local/share/twistedpear/host`","Windows: `%APPDATA%/TwistedPear/host`","Identity: `<data-dir>/identity`","Config: `<data-dir>/config.json`"]},{"type":"paragraph","text":"Platform paths: Desktop host. Headless flags: CLI commands."},{"type":"chapter-link","label":"Desktop host","chapterId":"host-desktop"},{"type":"chapter-link","label":"CLI commands","chapterId":"ref-cli"},{"type":"heading","level":2,"text":"Roles (desktop defaults)"},{"type":"list","items":["Transport node: true","Seeder / LAN mirror: true","Propagation server: false","Attach to external rnsd: off"]},{"type":"paragraph","text":"Web hosts force leaf roles — see Web host."},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"heading","level":2,"text":"Interfaces (desktop defaults)"},{"type":"list","items":["TCP client: off (target 127.0.0.1:4242)","WebSocket gateway: off (listen 127.0.0.1:9480)","AutoInterface multicast: true","Bonjour discovery: true","I2P SAM: false","RNode serial: false"]},{"type":"paragraph","text":"Interface behavior: Network interfaces."},{"type":"chapter-link","label":"Network interfaces","chapterId":"ref-interfaces"},{"type":"heading","level":2,"text":"Quotas"},{"type":"paragraph","text":"Seed storage, propagation store, message count, and bandwidth caps match Quotas & limits. Override under the `quotas` key."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"heading","level":2,"text":"AI endpoint"},{"type":"paragraph","text":"`ai` is `null` until configured (desktop **Settings → AI** or `config.json`). Chat and embedding models are configured separately. Mini-apps use `ai:chat` and `ai:embed` through the host proxy — see AI chat."},{"type":"chapter-link","label":"AI chat","chapterId":"sdk-ai-chat"},{"type":"heading","level":2,"text":"Status endpoint"},{"type":"paragraph","text":"Opt-in JSON at `http://127.0.0.1:9473/status` when `statusEndpoint: true` or `tp node --status-endpoint`."}],"searchText":"host configuration part v — reference host configuration <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> generated from `defaulthostconfig()` defaults in `packages/host-core`. desktop and `tp node` persist overrides in `<data-dir>/config.json`. data directory macos: `~/library/application support/twistedpear/host` linux: `~/.local/share/twistedpear/host` windows: `%appdata%/twistedpear/host` identity: `<data-dir>/identity` config: `<data-dir>/config.json` platform paths: desktop host. headless flags: cli commands. roles (desktop defaults) transport node: true seeder / lan mirror: true propagation server: false attach to external rnsd: off web hosts force leaf roles — see web host. interfaces (desktop defaults) tcp client: off (target 127.0.0.1:4242) websocket gateway: off (listen 127.0.0.1:9480) autointerface multicast: true bonjour discovery: true i2p sam: false rnode serial: false interface behavior: network interfaces. quotas seed storage, propagation store, message count, and bandwidth caps match quotas & limits. override under the `quotas` key. ai endpoint `ai` is `null` until configured (desktop **settings → ai** or `config.json`). chat and embedding models are configured separately. mini-apps use `ai:chat` and `ai:embed` through the host proxy — see ai chat. status endpoint opt-in json at `http://127.0.0.1:9473/status` when `statusendpoint: true` or `tp node --status-endpoint`."},{"id":"ref-cli","title":"CLI commands","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"CLI commands"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"The `tp` CLI scaffolds, packs, publishes, and runs headless peers. Publisher identity comes from `tp init` (Reticulum keypair in the project or data dir)."},{"type":"heading","level":2,"text":"Project workflow"},{"type":"list","items":["`tp init [--force]` — create or load publisher identity","`tp create <hello|chat-min> [app-dir]` — scaffold a mini-app template","`tp dev <app-dir> [--host host:port]` — build and side-load to a dev-mode host","`tp pack <app-dir> [--out file.tpkg]` — build unsigned `.tpkg` archive","`tp sign <file.tpkg>` — re-sign an existing package","`tp publish <app-dir>` — pack, sign, publish to Hyperdrive","`tp update <app-dir> --version <semver>` — bump version and republish"]},{"type":"heading","level":2,"text":"Headless hosts"},{"type":"list","items":["`tp node` — transport/seeder/propagation peer (`--ws-listen`, `--serve-web`, …)","`tp seed` — headless Hyperdrive seeder (`--transport`, `--state-dir`)"]},{"type":"heading","level":2,"text":"Trust"},{"type":"list","items":["`tp trust list|show|add|remove` — manage trusted publisher keys"]},{"type":"paragraph","text":"Handbook packaging in CI: `npm run build:handbook` then `tp pack` in a temp dir. Tutorial: Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}],"searchText":"cli commands part v — reference cli commands <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> the `tp` cli scaffolds, packs, publishes, and runs headless peers. publisher identity comes from `tp init` (reticulum keypair in the project or data dir). project workflow `tp init [--force]` — create or load publisher identity `tp create <hello|chat-min> [app-dir]` — scaffold a mini-app template `tp dev <app-dir> [--host host:port]` — build and side-load to a dev-mode host `tp pack <app-dir> [--out file.tpkg]` — build unsigned `.tpkg` archive `tp sign <file.tpkg>` — re-sign an existing package `tp publish <app-dir>` — pack, sign, publish to hyperdrive `tp update <app-dir> --version <semver>` — bump version and republish headless hosts `tp node` — transport/seeder/propagation peer (`--ws-listen`, `--serve-web`, …) `tp seed` — headless hyperdrive seeder (`--transport`, `--state-dir`) trust `tp trust list|show|add|remove` — manage trusted publisher keys handbook packaging in ci: `npm run build:handbook` then `tp pack` in a temp dir. tutorial: packaging & preview."},{"id":"ref-limitations","title":"Known limitations","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Known limitations"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: live audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Platform compromises and measured constraints. Cross-linked from host chapters and the live difference matrix."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":1,"text":"Limitations, Compromises, and Restrictions"},{"type":"paragraph","text":"<!-- tp-doc lifecycle: reference audited: 2026-07-21 register: none -->"},{"type":"paragraph","text":"Companion to archive/design/plan-v0.md. Reticulum compatibility is the only hard constraint; everything below is a known cost of the chosen design or of the platforms involved."},{"type":"heading","level":2,"text":"1. Reticulum implementation"},{"type":"list","items":["**No production JS implementation exists.** The reference RNS is Python. The only JS"]},{"type":"paragraph","text":"implementation, `rns.js` (v0.0.4), is self-described as extremely limited: no transport-node routing, no ratchets, no Resources, no link heartbeats, no UDP interface, no LXMF signature validation, no rate limiting. We are committing to building and maintaining `reticulum-ts` — a substantial, ongoing engineering effort, not an integration task."},{"type":"list","items":["**Wire-format chase.** Reticulum evolves (ratchets were added relatively recently). Every"]},{"type":"paragraph","text":"protocol change in the reference must be re-implemented and re-verified; until parity is reached, some network features may silently not work with newer Python peers."},{"type":"list","items":["**Crypto parity risk.** We must match X25519/Ed25519/AES-256-CBC/HMAC-SHA256 semantics"]},{"type":"paragraph","text":"byte-for-byte. Any deviation is a security bug, not just an interop bug. JS crypto is also slower than the C-backed Python primitives; older phones may see slow link setup and hashing (mitigated by libsodium native bindings in Bare)."},{"type":"paragraph","text":"**Measured Node pure-provider throughput (200 iterations, CI baseline):**"},{"type":"table","headers":["Operation","ops/s (Node pure)"],"rows":[["x25519-keygen","1,134"],["x25519-shared-secret","1,158"],["hkdf-link-key","31,470"],["aes-256-cbc-encrypt-512","57,823"],["ed25519-sign-64","2,807"],["sha256-resource-chunk","206,950"]]},{"type":"paragraph","text":"Source: `conformance/bare-runtime/baseline-node.json` (`npm run test:bare-benchmark-compare`)."},{"type":"paragraph","text":"**Measured sodium-native provider on host Node (200 iterations, CI baseline):**"},{"type":"table","headers":["Operation","ops/s (sodium-native)"],"rows":[["x25519-keygen","50,000"],["x25519-shared-secret","25,000"],["hkdf-link-key","28,571"],["aes-256-cbc-encrypt-512","50,000"],["ed25519-sign-64","33,333"],["sha256-resource-chunk","200,000"]]},{"type":"paragraph","text":"Source: `conformance/bare-runtime/baseline-bare.json` (`npm run test:bare-benchmark-bare-compare`). Bare worklet on-device numbers remain open until H11. Link-setup latency (Node pure, docker link-echo peer): see `conformance/link-benchmark/measured.json` (`INTEROP=1 npm run test:link-benchmark`; CI `interop` job records with `LINK_BENCHMARK_RECORD=1`)."},{"type":"heading","level":2,"text":"2. Expo Go — sacrificed"},{"type":"list","items":["The system requires native modules (bare-kit worklet, BLE central+peripheral, IPv6"]},{"type":"paragraph","text":"multicast, foreground service, USB serial). **Expo Go cannot load custom native modules, so the host app will not run in Expo Go.**"},{"type":"list","items":["Compromise: keep the Expo toolchain but use **development builds** (`expo-dev-client`)"]},{"type":"paragraph","text":"and config plugins. Developers get most of the Expo DX; they just install a custom dev client instead of Expo Go. *Mini-app* developers are unaffected (pure JS against our SDK)."},{"type":"heading","level":2,"text":"3. Bluetooth"},{"type":"list","items":["**Reticulum has no phone-to-phone Bluetooth interface today.** Official BLE support is"]},{"type":"paragraph","text":"only for connecting to RNode LoRa hardware. Our phone-to-phone BLE interface is a custom interface we define. Reticulum explicitly supports custom interfaces (≥5 bps, 500-byte MTU), so it is protocol-legal — but until other implementations adopt our spec, BLE meshing only works host-app-to-host-app."},{"type":"list","items":["**BLE is slow.** Practical GATT throughput is tens of kbps at best; fine for messaging"]},{"type":"paragraph","text":"and announces, marginal for app installs (a 1 MB mini-app can take minutes). MTU ~185–512 bytes forces fragmentation/reassembly below Reticulum's 500-byte MTU."},{"type":"list","items":["**No Bluetooth Classic on iOS** (no SPP for arbitrary apps); BLE only. Android OEM BLE"]},{"type":"paragraph","text":"stacks vary wildly; peripheral mode is unsupported on some older/cheap devices."},{"type":"list","items":["Simultaneous central+peripheral roles, background advertising limits (iOS rotates/strips"]},{"type":"paragraph","text":"advertisement data in background), and pairing UX are all sources of flakiness."},{"type":"heading","level":2,"text":"4. iOS restrictions (most constrained platform)"},{"type":"list","items":["**Background execution:** iOS will suspend the app; there is no equivalent of Android's"]},{"type":"paragraph","text":"foreground service for a general network daemon. An iPhone cannot be a reliable always-on Reticulum transport node. Compromise: opportunistic connectivity (foreground, brief background windows, BLE background modes) and reliance on desktop/Android peers for routing."},{"type":"list","items":["**Multicast entitlement:** AutoInterface peer discovery uses IPv6 multicast, which"]},{"type":"paragraph","text":"requires `com.apple.developer.networking.multicast` — granted by Apple on application, with lead time and no guarantee. Application draft prepared (Phase 2 M8); **status: not yet submitted / H12 pending** — see docs/ios-multicast-entitlement.md and STATUS-HARDWARE.md (H12–H15). Fallback: LAN discovery via Bonjour (`_reticulum._udp`) + direct UDP, or manual/TCP peers."},{"type":"list","items":["**Bonjour fallback gap:** an un-entitled iPhone can discover TS nodes that advertise"]},{"type":"paragraph","text":"`_reticulum._udp`, but cannot discover stock Python RNS AutoInterface peers through Bonjour. Reaching those peers requires the multicast entitlement, a TCP link, or a TS peer relaying as a transport node."},{"type":"list","items":["**Downloaded code (App Review 3.3.2):** mini-apps are downloaded JS. Apple permits"]},{"type":"paragraph","text":"downloaded JS executed by Apple frameworks when it doesn't change the app's core purpose — an app *store inside an app* is exactly the gray zone Apple scrutinizes. Compromises: declarative UI whitelist (host renders, mini-apps don't ship arbitrary UI code paths), curated capability model, and acceptance that **the iOS build may need a reduced distribution feature set** or TestFlight/enterprise/EU-alternative-distribution channels. Phase 5 adds a store-posture build flag and dossier in docs/ios-submission.md; no submission is attempted in this phase."},{"type":"list","items":["**No sideloading escape hatch** outside the EU. If Apple rejects the concept, iOS becomes"]},{"type":"paragraph","text":"a client (messaging, using apps already vetted) rather than a full open platform."},{"type":"heading","level":2,"text":"5. Android restrictions"},{"type":"list","items":["Persistent mesh participation requires a **foreground service** with a permanent"]},{"type":"paragraph","text":"notification; Doze and OEM battery managers can still throttle networking. Battery cost of always-on BLE + multicast is real and must be budgeted/opt-in."},{"type":"list","items":["**Google Play policy** restricts apps that download executable code. Interpreted JS in a"]},{"type":"paragraph","text":"sandbox is a recognized carve-out, but a P2P app store pushes the boundary. Escape hatch (which iOS lacks): distribute the host APK directly / via F-Droid — itself fitting the project's P2P ethos."},{"type":"list","items":["Wi-Fi Direct / Aware are inconsistent across OEMs; plan treats them as future"]},{"type":"paragraph","text":"opportunistic interfaces, not committed ones. LAN AutoInterface + BLE are the committed local transports."},{"type":"heading","level":2,"text":"6. Pears stack scope"},{"type":"list","items":["**Hyperswarm/Hyperdrive require IP connectivity** (UDX over UDP, DHT access). They do not"]},{"type":"paragraph","text":"run over Reticulum. Off-grid (LoRa/BLE-only) distribution therefore falls back to Reticulum Resource transfer, which is orders of magnitude slower — a mini-app must be assumed installable at LoRa speeds only if it is very small. Compromise: size budgets for bundles, delta updates, and LAN/desktop seeding as the primary bulk path."},{"type":"paragraph","text":"**Measured install budgets (Phase 3 M9, conservative bitrates):**"},{"type":"table","headers":["Package","Size","LAN (~8 Mbps)","BLE (~24 kbps)","RNode (~1.2 kbps)"],"rows":[["`tiny` (budget hello-world)","~900 B","<1 s","<1 s","~6 s"],["`example-app` (minimal mini-app)","~780 B","<1 s","<1 s","~6 s"],["`chat` (Phase 4 example)","~2.6 KiB","<1 s","<1 s","~18 s"],["`file-drop` (Phase 4 example)","~1.8 KiB","<1 s","<1 s","~12 s"],["`board` (Phase 4 example)","~2.1 KiB","<1 s","<1 s","~15 s"]]},{"type":"paragraph","text":"Under-one-minute ceilings at these rates: LAN ~60 MiB, BLE ~180 KiB, RNode ~9 KiB. `bridge-hyper` blocks automatic bulk fetch over RNode-only links above 64 KiB and warns above 32 KiB; BLE warnings start at 256 KiB. See   `conformance/budgets/measured.json` for regenerated numbers (`npm run test:budgets`)."},{"type":"list","items":["Android emulator Bare Worker spawn/kill/busy-loop metrics: `conformance/android-emulator/measured-worker.json`"]},{"type":"paragraph","text":"(`ANDROID_BENCHMARK_RECORD=1 npm run test:android-emulator:e5` on KVM emulator)."},{"type":"list","items":["Holepunch's DHT bootstrap nodes are an external dependency; fully-sovereign deployments"]},{"type":"paragraph","text":"need self-hosted bootstrap or LAN-only swarm mode."},{"type":"list","items":["The Pears components are the most replaceable part of the design (per the constraint"]},{"type":"paragraph","text":"hierarchy): if bare-kit or Hyperdrive proves unworkable on mobile, fallbacks are Node (nodejs-mobile) + plain RNS Resources for distribution."},{"type":"list","items":["**Desktop host (Phase 6):** `apps/host-desktop` runs the same Bare worklet as mobile under"]},{"type":"paragraph","text":"Electron supervision (stdio IPC, not in-process Node). Windows NSIS artifacts are built in CI but not verified until register **H17**. Propagation node-to-node peering is a stretch goal — client sync against `lxmd` is implemented; meshed multi-node stores should use `lxmd` until peering ships."},{"type":"heading","level":2,"text":"7. Mini-app model"},{"type":"list","items":["**Embeddings are request-scoped, not a vector database:** `ai.embed` and `ai.search`"]},{"type":"paragraph","text":"require a separate grant and host-configured embedding model, share the per-app AI in-flight slot, cap each input at 16,384 characters, cap batches at 64 inputs and vectors at 4,096 dimensions, and persist no index. `ai.search` accepts at most 63 documents because the query occupies the remaining batch slot."},{"type":"list","items":["Mini-apps are **not native apps**: no arbitrary native modules, no background autonomy,"]},{"type":"paragraph","text":"capabilities only via the host SDK. Some app categories (games needing native perf, apps needing exotic hardware) won't fit; the tiered-APK channel was deliberately deferred."},{"type":"list","items":["JS sandboxing inside one runtime is a real attack surface. Phase 7 completed a software-tier"]},{"type":"paragraph","text":"adversarial review of the broker chokepoint (docs/security-review.md); mini-app installation still trusts the publisher signature for declared behavior."},{"type":"list","items":["Phase 4 ships a broker chokepoint, deny-by-default capability grants, data-only widget"]},{"type":"paragraph","text":"trees, and hostile-input conformance tests. Capability substitution and broker UI-event forgery gaps found in review are fixed; **Bare Worker hostile parity on device** remains open (H11). Watchdog thresholds may false-positive on low-end devices."},{"type":"list","items":["Desktop Node Worker sandbox metrics: `conformance/miniapp-benchmark/measured-desktop.json`"]},{"type":"paragraph","text":"(`npm run test:miniapp-benchmark`; record with `MINIAPP_BENCHMARK_RECORD=1`)."},{"type":"list","items":["One foreground mini-app at a time in v1; no background execution. Dev side-loading is"]},{"type":"paragraph","text":"localhost/adb-only, off by default, and badged **DEV** in the UI."},{"type":"list","items":["No central registry means **no central moderation**: discovery is by announce/registry"]},{"type":"paragraph","text":"subscription, and malicious-app defense rests on signatures, capability grants, and user/community trust. LXMF block/mute lists and report records are local; exporting a report does not submit it or cause a network-wide ban."},{"type":"list","items":["Multipart propagation is a TwistedPear framing convention over ordinary signed LXMF"]},{"type":"paragraph","text":"messages, not an LXMF attachment standard. It defaults to 64 KiB, hard-stops at 1,000,000 bytes, and uses 32-byte content frames with 16-byte titles to remain on the packet propagation path. It is resumable but airtime-expensive; use Resources or content-addressed sharing for bulk data."},{"type":"list","items":["`ai.chatStream` coalesces provider events before crossing the broker; deltas are not token"]},{"type":"paragraph","text":"boundaries. Streaming and whole-response chat share one in-flight request per app, and stopping iteration cancels the host-side stream."},{"type":"list","items":["**Dev environment (DevStudio) v1 limits:** projects are single-file bundles (no"]},{"type":"paragraph","text":"in-host bundler); workspace files are capped at 256 KiB as a host safety quota, while `code-editor` changes use conflict-checked deltas; AI editing streams a whole-file proposal through an OpenRouter-compatible endpoint configured host-side; one dev-preview slot; desktop QR support renders codes but accepts pasted 256t strings only (camera scan is a mobile-host follow-up); memory-limit changes apply at the next launch, while rate and storage-quota changes apply live; 256t locator announces must have been received before an install can resolve (no locator re-request yet)."},{"type":"heading","level":2,"text":"8. Web platform (see docs/web-host.md)"},{"type":"list","items":["**Leaf-only, gateway-dependent:** browsers cannot accept inbound connections or open raw"]},{"type":"paragraph","text":"TCP/UDP sockets, so the web host reaches Reticulum only through the WebSocket interface of a gateway node it can dial. No transport-node, seeder, or propagation roles — ever, on this target."},{"type":"list","items":["**No radios (gateway path):** Web Bluetooth is central-only (cannot run the peripheral"]},{"type":"paragraph","text":"GATT stream), and there is no multicast/AutoInterface. RNode over WebSerial (Chromium-only) is implemented as a stretch path with simulated-serial CI (`test:web-rnode`); real USB LoRa E2E remains device-gated."},{"type":"list","items":["**Weaker key custody:** identity keys sit in IndexedDB encrypted under a WebCrypto key;"]},{"type":"paragraph","text":"the portable `.tpidentity` and recovery-word settings flow is not yet exposed by the web host — no hardware keystore equivalent. The serving origin is part of the TCB: whoever serves the page bytes can substitute them. Default posture is self-serving from the user's own node (`tp node --serve-web`)."},{"type":"list","items":["**Sandbox mechanism differs:** mini-app isolation rests on opaque-origin sandboxed"]},{"type":"paragraph","text":"iframes + workers and CSP rather than OS processes; it must pass the same adversarial review as the native backends before any web release."},{"type":"list","items":["**Bulk plane via gateway:** Hyperswarm/Hyperdrive do not run in the browser tab. The web"]},{"type":"paragraph","text":"host installs over Hyperdrive by calling the gateway's `/bulk-fetch` HTTP proxy (the node joins Hyperswarm and streams the archive). Reticulum Resource transfer remains the offline/fallback path. Direct WS DHT-relay client lookup still depends on `@hyperswarm/dht-relay` ↔ `hyperdht` compatibility and is treated as experimental."},{"type":"list","items":["**Storage is evictable:** OPFS/IndexedDB live under browser quota and can be cleared by"]},{"type":"paragraph","text":"the user agent; `navigator.storage.persist()` mitigates but does not guarantee."},{"type":"heading","level":2,"text":"9. General"},{"type":"list","items":["**Reader-guide image coverage:** 33 of 106 referenced images are reproducible captures"]},{"type":"paragraph","text":"from the actual desktop renderer, mini-app runtime, or built web host. The other 73 remain placeholders where the exact caption needs hardware, a multi-peer or populated-app fixture, a clean terminal session, DevStudio interaction state, or editorial composition. The three `images/README.md` files name every remainder; startup-only or invented UI is not substituted."},{"type":"list","items":["**Identity recovery UI coverage:** encrypted vaults, portable backup import/export, and"]},{"type":"paragraph","text":"two-part BIP-39 recovery are implemented in `tp` and the desktop host. Mobile and browser host settings do not yet expose those operations. Recovery does not rotate or revoke a key, and simultaneous use of a restored identity on two hosts remains unsupported."},{"type":"list","items":["**Anonymity/privacy caveats:** BLE MAC addresses, WiFi multicast presence, and always-on"]},{"type":"paragraph","text":"radios are locally observable even though Reticulum payloads are encrypted and packets carry no source address. Physical-layer observability is out of scope for the stack."},{"type":"list","items":["**Time-to-usefulness:** a mesh platform is only as useful as its peer density; early"]},{"type":"paragraph","text":"deployments depend on desktop transport nodes and TCP testnet links, not pure phone meshes. Phase 6 adds always-on desktop peers (`tp node`, `host-desktop`) with transport + seeding on by default; measured always-on quota behavior is tracked in register **H20**."},{"type":"list","items":["Amateur-radio carriers (AX.25/KISS) carry legal restrictions (no encryption on ham bands"]},{"type":"paragraph","text":"in most jurisdictions) — supported by Reticulum but out of scope for this app's defaults."}],"searchText":"known limitations part v — reference known limitations <!-- tp-doc lifecycle: live audited: 2026-07-21 register: none --> platform compromises and measured constraints. cross-linked from host chapters and the live difference matrix. limitations, compromises, and restrictions <!-- tp-doc lifecycle: reference audited: 2026-07-21 register: none --> companion to archive/design/plan-v0.md. reticulum compatibility is the only hard constraint; everything below is a known cost of the chosen design or of the platforms involved. 1. reticulum implementation **no production js implementation exists.** the reference rns is python. the only js implementation, `rns.js` (v0.0.4), is self-described as extremely limited: no transport-node routing, no ratchets, no resources, no link heartbeats, no udp interface, no lxmf signature validation, no rate limiting. we are committing to building and maintaining `reticulum-ts` — a substantial, ongoing engineering effort, not an integration task. **wire-format chase.** reticulum evolves (ratchets were added relatively recently). every protocol change in the reference must be re-implemented and re-verified; until parity is reached, some network features may silently not work with newer python peers. **crypto parity risk.** we must match x25519/ed25519/aes-256-cbc/hmac-sha256 semantics byte-for-byte. any deviation is a security bug, not just an interop bug. js crypto is also slower than the c-backed python primitives; older phones may see slow link setup and hashing (mitigated by libsodium native bindings in bare). **measured node pure-provider throughput (200 iterations, ci baseline):** operation ops/s (node pure) x25519-keygen 1,134 x25519-shared-secret 1,158 hkdf-link-key 31,470 aes-256-cbc-encrypt-512 57,823 ed25519-sign-64 2,807 sha256-resource-chunk 206,950 source: `conformance/bare-runtime/baseline-node.json` (`npm run test:bare-benchmark-compare`). **measured sodium-native provider on host node (200 iterations, ci baseline):** operation ops/s (sodium-native) x25519-keygen 50,000 x25519-shared-secret 25,000 hkdf-link-key 28,571 aes-256-cbc-encrypt-512 50,000 ed25519-sign-64 33,333 sha256-resource-chunk 200,000 source: `conformance/bare-runtime/baseline-bare.json` (`npm run test:bare-benchmark-bare-compare`). bare worklet on-device numbers remain open until h11. link-setup latency (node pure, docker link-echo peer): see `conformance/link-benchmark/measured.json` (`interop=1 npm run test:link-benchmark`; ci `interop` job records with `link_benchmark_record=1`). 2. expo go — sacrificed the system requires native modules (bare-kit worklet, ble central+peripheral, ipv6 multicast, foreground service, usb serial). **expo go cannot load custom native modules, so the host app will not run in expo go.** compromise: keep the expo toolchain but use **development builds** (`expo-dev-client`) and config plugins. developers get most of the expo dx; they just install a custom dev client instead of expo go. *mini-app* developers are unaffected (pure js against our sdk). 3. bluetooth **reticulum has no phone-to-phone bluetooth interface today.** official ble support is only for connecting to rnode lora hardware. our phone-to-phone ble interface is a custom interface we define. reticulum explicitly supports custom interfaces (≥5 bps, 500-byte mtu), so it is protocol-legal — but until other implementations adopt our spec, ble meshing only works host-app-to-host-app. **ble is slow.** practical gatt throughput is tens of kbps at best; fine for messaging and announces, marginal for app installs (a 1 mb mini-app can take minutes). mtu ~185–512 bytes forces fragmentation/reassembly below reticulum's 500-byte mtu. **no bluetooth classic on ios** (no spp for arbitrary apps); ble only. android oem ble stacks vary wildly; peripheral mode is unsupported on some older/cheap devices. simultaneous central+peripheral roles, background advertising limits (ios rotates/strips advertisement data in background), and pairing ux are all sources of flakiness. 4. ios restrictions (most constrained platform) **background execution:** ios will suspend the app; there is no equivalent of android's foreground service for a general network daemon. an iphone cannot be a reliable always-on reticulum transport node. compromise: opportunistic connectivity (foreground, brief background windows, ble background modes) and reliance on desktop/android peers for routing. **multicast entitlement:** autointerface peer discovery uses ipv6 multicast, which requires `com.apple.developer.networking.multicast` — granted by apple on application, with lead time and no guarantee. application draft prepared (phase 2 m8); **status: not yet submitted / h12 pending** — see docs/ios-multicast-entitlement.md and status-hardware.md (h12–h15). fallback: lan discovery via bonjour (`_reticulum._udp`) + direct udp, or manual/tcp peers. **bonjour fallback gap:** an un-entitled iphone can discover ts nodes that advertise `_reticulum._udp`, but cannot discover stock python rns autointerface peers through bonjour. reaching those peers requires the multicast entitlement, a tcp link, or a ts peer relaying as a transport node. **downloaded code (app review 3.3.2):** mini-apps are downloaded js. apple permits downloaded js executed by apple frameworks when it doesn't change the app's core purpose — an app *store inside an app* is exactly the gray zone apple scrutinizes. compromises: declarative ui whitelist (host renders, mini-apps don't ship arbitrary ui code paths), curated capability model, and acceptance that **the ios build may need a reduced distribution feature set** or testflight/enterprise/eu-alternative-distribution channels. phase 5 adds a store-posture build flag and dossier in docs/ios-submission.md; no submission is attempted in this phase. **no sideloading escape hatch** outside the eu. if apple rejects the concept, ios becomes a client (messaging, using apps already vetted) rather than a full open platform. 5. android restrictions persistent mesh participation requires a **foreground service** with a permanent notification; doze and oem battery managers can still throttle networking. battery cost of always-on ble + multicast is real and must be budgeted/opt-in. **google play policy** restricts apps that download executable code. interpreted js in a sandbox is a recognized carve-out, but a p2p app store pushes the boundary. escape hatch (which ios lacks): distribute the host apk directly / via f-droid — itself fitting the project's p2p ethos. wi-fi direct / aware are inconsistent across oems; plan treats them as future opportunistic interfaces, not committed ones. lan autointerface + ble are the committed local transports. 6. pears stack scope **hyperswarm/hyperdrive require ip connectivity** (udx over udp, dht access). they do not run over reticulum. off-grid (lora/ble-only) distribution therefore falls back to reticulum resource transfer, which is orders of magnitude slower — a mini-app must be assumed installable at lora speeds only if it is very small. compromise: size budgets for bundles, delta updates, and lan/desktop seeding as the primary bulk path. **measured install budgets (phase 3 m9, conservative bitrates):** package size lan (~8 mbps) ble (~24 kbps) rnode (~1.2 kbps) `tiny` (budget hello-world) ~900 b <1 s <1 s ~6 s `example-app` (minimal mini-app) ~780 b <1 s <1 s ~6 s `chat` (phase 4 example) ~2.6 kib <1 s <1 s ~18 s `file-drop` (phase 4 example) ~1.8 kib <1 s <1 s ~12 s `board` (phase 4 example) ~2.1 kib <1 s <1 s ~15 s under-one-minute ceilings at these rates: lan ~60 mib, ble ~180 kib, rnode ~9 kib. `bridge-hyper` blocks automatic bulk fetch over rnode-only links above 64 kib and warns above 32 kib; ble warnings start at 256 kib. see   `conformance/budgets/measured.json` for regenerated numbers (`npm run test:budgets`). android emulator bare worker spawn/kill/busy-loop metrics: `conformance/android-emulator/measured-worker.json` (`android_benchmark_record=1 npm run test:android-emulator:e5` on kvm emulator). holepunch's dht bootstrap nodes are an external dependency; fully-sovereign deployments need self-hosted bootstrap or lan-only swarm mode. the pears components are the most replaceable part of the design (per the constraint hierarchy): if bare-kit or hyperdrive proves unworkable on mobile, fallbacks are node (nodejs-mobile) + plain rns resources for distribution. **desktop host (phase 6):** `apps/host-desktop` runs the same bare worklet as mobile under electron supervision (stdio ipc, not in-process node). windows nsis artifacts are built in ci but not verified until register **h17**. propagation node-to-node peering is a stretch goal — client sync against `lxmd` is implemented; meshed multi-node stores should use `lxmd` until peering ships. 7. mini-app model **embeddings are request-scoped, not a vector database:** `ai.embed` and `ai.search` require a separate grant and host-configured embedding model, share the per-app ai in-flight slot, cap each input at 16,384 characters, cap batches at 64 inputs and vectors at 4,096 dimensions, and persist no index. `ai.search` accepts at most 63 documents because the query occupies the remaining batch slot. mini-apps are **not native apps**: no arbitrary native modules, no background autonomy, capabilities only via the host sdk. some app categories (games needing native perf, apps needing exotic hardware) won't fit; the tiered-apk channel was deliberately deferred. js sandboxing inside one runtime is a real attack surface. phase 7 completed a software-tier adversarial review of the broker chokepoint (docs/security-review.md); mini-app installation still trusts the publisher signature for declared behavior. phase 4 ships a broker chokepoint, deny-by-default capability grants, data-only widget trees, and hostile-input conformance tests. capability substitution and broker ui-event forgery gaps found in review are fixed; **bare worker hostile parity on device** remains open (h11). watchdog thresholds may false-positive on low-end devices. desktop node worker sandbox metrics: `conformance/miniapp-benchmark/measured-desktop.json` (`npm run test:miniapp-benchmark`; record with `miniapp_benchmark_record=1`). one foreground mini-app at a time in v1; no background execution. dev side-loading is localhost/adb-only, off by default, and badged **dev** in the ui. no central registry means **no central moderation**: discovery is by announce/registry subscription, and malicious-app defense rests on signatures, capability grants, and user/community trust. lxmf block/mute lists and report records are local; exporting a report does not submit it or cause a network-wide ban. multipart propagation is a twistedpear framing convention over ordinary signed lxmf messages, not an lxmf attachment standard. it defaults to 64 kib, hard-stops at 1,000,000 bytes, and uses 32-byte content frames with 16-byte titles to remain on the packet propagation path. it is resumable but airtime-expensive; use resources or content-addressed sharing for bulk data. `ai.chatstream` coalesces provider events before crossing the broker; deltas are not token boundaries. streaming and whole-response chat share one in-flight request per app, and stopping iteration cancels the host-side stream. **dev environment (devstudio) v1 limits:** projects are single-file bundles (no in-host bundler); workspace files are capped at 256 kib as a host safety quota, while `code-editor` changes use conflict-checked deltas; ai editing streams a whole-file proposal through an openrouter-compatible endpoint configured host-side; one dev-preview slot; desktop qr support renders codes but accepts pasted 256t strings only (camera scan is a mobile-host follow-up); memory-limit changes apply at the next launch, while rate and storage-quota changes apply live; 256t locator announces must have been received before an install can resolve (no locator re-request yet). 8. web platform (see docs/web-host.md) **leaf-only, gateway-dependent:** browsers cannot accept inbound connections or open raw tcp/udp sockets, so the web host reaches reticulum only through the websocket interface of a gateway node it can dial. no transport-node, seeder, or propagation roles — ever, on this target. **no radios (gateway path):** web bluetooth is central-only (cannot run the peripheral gatt stream), and there is no multicast/autointerface. rnode over webserial (chromium-only) is implemented as a stretch path with simulated-serial ci (`test:web-rnode`); real usb lora e2e remains device-gated. **weaker key custody:** identity keys sit in indexeddb encrypted under a webcrypto key; the portable `.tpidentity` and recovery-word settings flow is not yet exposed by the web host — no hardware keystore equivalent. the serving origin is part of the tcb: whoever serves the page bytes can substitute them. default posture is self-serving from the user's own node (`tp node --serve-web`). **sandbox mechanism differs:** mini-app isolation rests on opaque-origin sandboxed iframes + workers and csp rather than os processes; it must pass the same adversarial review as the native backends before any web release. **bulk plane via gateway:** hyperswarm/hyperdrive do not run in the browser tab. the web host installs over hyperdrive by calling the gateway's `/bulk-fetch` http proxy (the node joins hyperswarm and streams the archive). reticulum resource transfer remains the offline/fallback path. direct ws dht-relay client lookup still depends on `@hyperswarm/dht-relay` ↔ `hyperdht` compatibility and is treated as experimental. **storage is evictable:** opfs/indexeddb live under browser quota and can be cleared by the user agent; `navigator.storage.persist()` mitigates but does not guarantee. 9. general **reader-guide image coverage:** 33 of 106 referenced images are reproducible captures from the actual desktop renderer, mini-app runtime, or built web host. the other 73 remain placeholders where the exact caption needs hardware, a multi-peer or populated-app fixture, a clean terminal session, devstudio interaction state, or editorial composition. the three `images/readme.md` files name every remainder; startup-only or invented ui is not substituted. **identity recovery ui coverage:** encrypted vaults, portable backup import/export, and two-part bip-39 recovery are implemented in `tp` and the desktop host. mobile and browser host settings do not yet expose those operations. recovery does not rotate or revoke a key, and simultaneous use of a restored identity on two hosts remains unsupported. **anonymity/privacy caveats:** ble mac addresses, wifi multicast presence, and always-on radios are locally observable even though reticulum payloads are encrypted and packets carry no source address. physical-layer observability is out of scope for the stack. **time-to-usefulness:** a mesh platform is only as useful as its peer density; early deployments depend on desktop transport nodes and tcp testnet links, not pure phone meshes. phase 6 adds always-on desktop peers (`tp node`, `host-desktop`) with transport + seeding on by default; measured always-on quota behavior is tracked in register **h20**. amateur-radio carriers (ax.25/kiss) carry legal restrictions (no encryption on ham bands in most jurisdictions) — supported by reticulum but out of scope for this app's defaults."}],"applets":[{"id":"ai-chat","title":"AI chat (host-mediated)","group":"runtime","executionModes":["inline"],"preview":null,"capabilities":["ai:chat","ai:embed"],"surfaces":["ai.chat"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/ai-chat/main.js"},{"id":"announce-loop","title":"Announce publish/subscribe","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["announce:publish","announce:subscribe"],"surfaces":["announce.publish","announce.subscribe"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/announce-loop/main.js"},{"id":"apps-package-preview","title":"Package + preview (confirmed)","group":"runtime","executionModes":["inline","preview"],"preview":{"project":"handbook-probe-app","manifest":{"name":"hb-probe","version":"0.0.1","entry":"bundle.js","capabilities":["identity"]},"grants":["identity"],"files":{"app.json":"{\"name\":\"hb-probe\",\"version\":\"0.0.1\",\"entry\":\"bundle.js\",\"capabilities\":[\"identity\"]}","bundle.js":"import { ui } from \"@twistedpear/miniapp-sdk\";\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"Handbook preview probe\" } } });\n"}},"capabilities":["apps:package","apps:preview","workspace"],"surfaces":["apps.packageProject","apps.preview","apps.stopPreview","workspace.write"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-package-preview/main.js"},{"id":"apps-publish-install","title":"Publish + install (confirmed)","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["apps:publish","apps:install","apps:package","workspace"],"surfaces":["apps.packageProject","apps.publish","apps.install"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-publish-install/main.js"},{"id":"apps-update","title":"Publish version bump (OTA update)","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["apps:package","apps:publish","apps:install","workspace"],"surfaces":["apps.packageProject","apps.publish","apps.install"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-update/main.js"},{"id":"ble-peer","title":"BLE peer visibility","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"unavailable","node":"unavailable"},"sourcePath":"applets/ble-peer/main.js"},{"id":"camera-qr-scan","title":"Camera QR scan","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"unavailable","web":"unavailable","node":"unavailable"},"sourcePath":"applets/camera-qr-scan/main.js"},{"id":"host-info","title":"Host info probe","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/host-info/main.js"},{"id":"identity-hash","title":"App destination hash","group":"crypto","executionModes":["inline"],"preview":null,"capabilities":["identity"],"surfaces":["identity.destinationHash"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/identity-hash/main.js"},{"id":"lxmf-roundtrip","title":"LXMF self-message","group":"crypto","executionModes":["inline"],"preview":null,"capabilities":["identity","lxmf:send","lxmf:receive"],"surfaces":["identity.destinationHash","lxmf.send","lxmf.receive"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/lxmf-roundtrip/main.js"},{"id":"multicast-auto","title":"Multicast / AutoInterface","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"unavailable","node":"unavailable"},"sourcePath":"applets/multicast-auto/main.js"},{"id":"presence-snapshot","title":"Presence snapshot","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["presence.snapshot"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/presence-snapshot/main.js"},{"id":"resource-fetch","title":"Resource fetch with budget","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["resource:fetch"],"surfaces":["resource.fetch"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/resource-fetch/main.js"},{"id":"rnode-serial","title":"RNode serial / LoRa path","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"device-gated","node":"unavailable"},"sourcePath":"applets/rnode-serial/main.js"},{"id":"share-cas","title":"CAS share put/get","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["share:cas"],"surfaces":["share.put","share.get"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/share-cas/main.js"},{"id":"storage-hyperbee","title":"Hyperbee round-trip","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["storage:hyperbee"],"surfaces":["storage.bee.open","storage.bee.put","storage.bee.get","storage.bee.list","storage.bee.del"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-hyperbee/main.js"},{"id":"storage-kv","title":"KV round-trip","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["storage:kv"],"surfaces":["storage.kv.get","storage.kv.set","storage.kv.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-kv/main.js"},{"id":"widget-gallery","title":"Widget gallery smoke","group":"runtime","executionModes":["inline"],"preview":null,"capabilities":["workspace"],"surfaces":["ui.render"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/widget-gallery/main.js"},{"id":"workspace-rw","title":"Workspace read/write","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["workspace"],"surfaces":["workspace.write","workspace.read","workspace.list","workspace.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/workspace-rw/main.js"}],"seeds":[{"path":"applets/ai-chat/applet.json","content":"{\n  \"id\": \"ai-chat\",\n  \"title\": \"AI chat (host-mediated)\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"ai:chat\",\n    \"ai:embed\"\n  ],\n  \"surfaces\": [\n    \"ai.chat\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/ai-chat/main.js","content":"/**\n * Handbook applet: ai.chatStream against the host-configured endpoint.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    let content = \"\";\n    let response = null;\n    for await (const event of sdk.ai.chatStream({\n      messages: [{ role: \"user\", content: \"Reply with the single word: handbook\" }]\n    })) {\n      if (event.type === \"delta\") content += event.delta;\n      if (event.type === \"done\") response = event.response;\n    }\n    if (response === null || typeof response !== \"object\" || response.message === undefined) {\n      report({\n        status: \"fail\",\n        details: `Expected AI response object, got: ${JSON.stringify(response)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (content.length === 0 || response.message?.content !== content) {\n      report({\n        status: \"fail\",\n        details: \"AI response message.content was empty\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `AI replied (${response.model ?? \"unknown model\"}): ${content.slice(0, 80)}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|AI_UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/announce-loop/applet.json","content":"{\n  \"id\": \"announce-loop\",\n  \"title\": \"Announce publish/subscribe\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"announce:publish\",\n    \"announce:subscribe\"\n  ],\n  \"surfaces\": [\n    \"announce.publish\",\n    \"announce.subscribe\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/announce-loop/main.js","content":"/**\n * Handbook applet: announce.publish then announce.subscribe in a local namespace.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const namespace = \"handbook-probe\";\n  const payload = new TextEncoder().encode(`announce-${started}`);\n  try {\n    await sdk.announce.publish(payload, namespace);\n    const events = await sdk.announce.subscribe(namespace);\n    if (!Array.isArray(events)) {\n      report({\n        status: \"fail\",\n        details: `Expected announce array, got: ${typeof events}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (events.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Subscribe returned no announces after publish\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and observed ${events.length} announce(s) in ${namespace}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-package-preview/applet.json","content":"{\n  \"id\": \"apps-package-preview\",\n  \"title\": \"Package + preview (confirmed)\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\",\n    \"preview\"\n  ],\n  \"preview\": {\n    \"project\": \"handbook-probe-app\",\n    \"manifest\": {\n      \"name\": \"hb-probe\",\n      \"version\": \"0.0.1\",\n      \"entry\": \"bundle.js\",\n      \"capabilities\": [\n        \"identity\"\n      ]\n    },\n    \"grants\": [\n      \"identity\"\n    ],\n    \"files\": {\n      \"app.json\": \"{\\\"name\\\":\\\"hb-probe\\\",\\\"version\\\":\\\"0.0.1\\\",\\\"entry\\\":\\\"bundle.js\\\",\\\"capabilities\\\":[\\\"identity\\\"]}\",\n      \"bundle.js\": \"import { ui } from \\\"@twistedpear/miniapp-sdk\\\";\\nawait ui.render({ root: { id: \\\"root\\\", type: \\\"text\\\", props: { value: \\\"Handbook preview probe\\\" } } });\\n\"\n    }\n  },\n  \"capabilities\": [\n    \"apps:package\",\n    \"apps:preview\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.preview\",\n    \"apps.stopPreview\",\n    \"workspace.write\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-package-preview/main.js","content":"/**\n * Handbook applet: seed a tiny project, package it, then preview (host confirmation).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-probe-app\";\n  const manifest = {\n    name: \"hb-probe\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({ name: manifest.name, version: manifest.version, entry: manifest.entry, capabilities: manifest.capabilities })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"probe\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (packed === null || typeof packed.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected package with 256t id, got: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const preview = await sdk.apps.preview(project, manifest, [\"identity\"]);\n    if (preview === null || preview.launched !== true) {\n      report({\n        status: \"fail\",\n        details: `Expected preview.launched === true, got: ${JSON.stringify(preview)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.apps.stopPreview();\n\n    report({\n      status: \"pass\",\n      details: `Packaged (${packed.t256.slice(0, 12)}…) and previewed`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-publish-install/applet.json","content":"{\n  \"id\": \"apps-publish-install\",\n  \"title\": \"Publish + install (confirmed)\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"apps:publish\",\n    \"apps:install\",\n    \"apps:package\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.publish\",\n    \"apps.install\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-publish-install/main.js","content":"/**\n * Handbook applet: package → publish → install (each step host-confirmed).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-distrib-app\";\n  const manifest = {\n    name: \"hb-distrib\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({\n        name: manifest.name,\n        version: manifest.version,\n        entry: manifest.entry,\n        capabilities: manifest.capabilities\n      })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"distrib\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (typeof packed?.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Package failed: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const published = await sdk.apps.publish(packed.t256);\n    if (published === null || typeof published.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Publish failed: ${JSON.stringify(published)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const installed = await sdk.apps.install(published.t256);\n    if (installed === null || typeof installed.appId !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Install failed: ${JSON.stringify(installed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and installed ${installed.appId}@${installed.version}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-update/applet.json","content":"{\n  \"id\": \"apps-update\",\n  \"title\": \"Publish version bump (OTA update)\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"apps:package\",\n    \"apps:publish\",\n    \"apps:install\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.publish\",\n    \"apps.install\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-update/main.js","content":"/**\n * Handbook applet: package v1 → publish → install → bump version → republish (OTA path).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-update-app\";\n  const manifestV1 = {\n    name: \"hb-update\",\n    version: \"0.1.0\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  const manifestV2 = { ...manifestV1, version: \"0.2.0\" };\n\n  try {\n    const writeProject = async (version) => {\n      await sdk.workspace.write(\n        `${project}/app.json`,\n        JSON.stringify({ ...manifestV1, version }, null, 2)\n      );\n      await sdk.workspace.write(\n        `${project}/bundle.js`,\n        `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"v${version}\" } } });\\n`\n      );\n    };\n\n    await writeProject(manifestV1.version);\n    const packedV1 = await sdk.apps.packageProject(project, manifestV1);\n    const publishedV1 = await sdk.apps.publish(packedV1.t256);\n    const installedV1 = await sdk.apps.install(publishedV1.t256);\n    if (installedV1?.version !== manifestV1.version) {\n      report({\n        status: \"fail\",\n        details: `v1 install version mismatch: ${JSON.stringify(installedV1)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await writeProject(manifestV2.version);\n    const packedV2 = await sdk.apps.packageProject(project, manifestV2);\n    const publishedV2 = await sdk.apps.publish(packedV2.t256);\n    const installedV2 = await sdk.apps.install(publishedV2.t256);\n    if (installedV2?.version !== manifestV2.version) {\n      report({\n        status: \"fail\",\n        details: `v2 update version mismatch: ${JSON.stringify(installedV2)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Updated ${installedV2.appId} ${manifestV1.version} → ${manifestV2.version}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/ble-peer/applet.json","content":"{\n  \"id\": \"ble-peer\",\n  \"title\": \"BLE peer visibility\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/ble-peer/main.js","content":"/**\n * Handbook applet: BLE peer visibility (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. On both phones, open the host app and enable the BLE interface.\",\n    \"2. Keep both devices in foreground for ~30 s until AutoInterface/BLE discovery runs.\",\n    \"3. Confirm presence shows at least one peer on the preferred BLE path.\",\n    \"4. Re-run this applet — expect pass when a BLE peer is visible.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"ble\")) {\n      report({\n        status: \"unavailable\",\n        details: `BLE interface not listed on ${info.platform}.\\n\\nGuided procedure (real device):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.peers ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `BLE interface present but no peer connected (peers=${snap.peers ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `BLE peer visible (peers=${snap.peers}, preferred=${snap.preferredInterface ?? \"none\"})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/camera-qr-scan/applet.json","content":"{\n  \"id\": \"camera-qr-scan\",\n  \"title\": \"Camera QR scan\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"unavailable\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/camera-qr-scan/main.js","content":"/**\n * Handbook applet: camera QR install path (device-gated).\n * Probes host platform — real camera scan is a host UI flow, not an SDK call.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. From another device, export a Handbook diagnostic report or package 256t id (QR on Diagnostics screen).\",\n    \"2. On this phone, open the host installer and choose Scan QR / camera import.\",\n    \"3. Grant camera permission when prompted.\",\n    \"4. Scan the QR — confirm install or compare completes.\",\n    \"5. Re-run this applet after a successful scan to record pass (manual confirmation).\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const mobile = info.platform === \"android\" || info.platform === \"ios\";\n    if (!mobile) {\n      report({\n        status: \"unavailable\",\n        details: `Camera QR install is a mobile host flow (${info.platform} has no camera installer path).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"unavailable\",\n      details: `Camera QR scan requires a physical device and user action — not exercisable headlessly.\\n\\nGuided procedure:\\n${procedure}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/host-info/applet.json","content":"{\n  \"id\": \"host-info\",\n  \"title\": \"Host info probe\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/host-info/main.js","content":"/**\n * Handbook applet: host.info() platform / roles / interfaces / quotas.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    if (sdk.host === undefined || typeof sdk.host.info !== \"function\") {\n      report({\n        status: \"unavailable\",\n        details: \"host.info is not available in this sandbox (upgrade host API).\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const info = await sdk.host.info();\n    if (info === null || typeof info !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a host info object, got: ${String(info)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const platform = typeof info.platform === \"string\" ? info.platform : \"?\";\n    const api = typeof info.hostApiVersion === \"string\" ? info.hostApiVersion : \"?\";\n    const roles = info.roles ?? {};\n    const interfaces = Array.isArray(info.interfaceTypes) ? info.interfaceTypes.join(\",\") : \"\";\n    const grants = Array.isArray(info.grantedCapabilities) ? info.grantedCapabilities.length : 0;\n\n    report({\n      status: \"pass\",\n      details: `platform=${platform} api=${api} grants=${grants} transport=${roles.transport === true} seeder=${roles.seeder === true} interfaces=[${interfaces}]`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /UNKNOWN_METHOD|not available|upgrade host/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/identity-hash/applet.json","content":"{\n  \"id\": \"identity-hash\",\n  \"title\": \"App destination hash\",\n  \"group\": \"crypto\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"identity\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/identity-hash/main.js","content":"/**\n * Handbook applet: prove identity.destinationHash() on this host.\n * Export async function run(sdk, report).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const hash = await sdk.identity.destinationHash();\n    if (typeof hash !== \"string\" || hash.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected a non-empty destination hash string, got: ${String(hash)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `destinationHash = ${hash}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted =\n      message.includes(\"CAPABILITY_DENIED\") ||\n      message.includes(\"has not been granted\") ||\n      message.includes(\"Capability\");\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/applet.json","content":"{\n  \"id\": \"lxmf-roundtrip\",\n  \"title\": \"LXMF self-message\",\n  \"group\": \"crypto\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"identity\",\n    \"lxmf:send\",\n    \"lxmf:receive\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\",\n    \"lxmf.send\",\n    \"lxmf.receive\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/main.js","content":"/**\n * Handbook applet: send an LXMF message to this app (by app id) and read it back.\n * The default host LXMF backend keys inboxes by app id (same as the chat example).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const me = await sdk.identity.destinationHash();\n    const body = `handbook-lxmf-${started}`;\n    // Deliver to this Handbook app's inbox (app id === \"handbook\").\n    await sdk.lxmf.send({ to: \"handbook\", subject: \"handbook-probe\", body });\n    const inbox = await sdk.lxmf.receive();\n    if (!Array.isArray(inbox)) {\n      report({\n        status: \"fail\",\n        details: `Expected inbox array, got: ${typeof inbox}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const hit = inbox.find((message) => message && message.body === body);\n    if (hit === undefined) {\n      report({\n        status: \"fail\",\n        details: `Inbox had ${inbox.length} message(s); self-message not found`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Self-message round-trip (destinationHash=${me})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/multicast-auto/applet.json","content":"{\n  \"id\": \"multicast-auto\",\n  \"title\": \"Multicast / AutoInterface\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/multicast-auto/main.js","content":"/**\n * Handbook applet: multicast / AutoInterface discovery (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. Put two hosts on the same Wi‑Fi LAN (phone + desktop, or two phones).\",\n    \"2. Enable AutoInterface / multicast discovery in each host app.\",\n    \"3. Wait for announces — presence should show peers without manual TCP config.\",\n    \"4. Re-run this applet — expect pass when auto peers are visible.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"auto\")) {\n      report({\n        status: \"unavailable\",\n        details: `AutoInterface not listed on ${info.platform} (types: ${types.join(\", \") || \"none\"}).\\n\\nGuided procedure (LAN + hardware):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.peers ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `AutoInterface present but no LAN peer yet (peers=${snap.peers ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `AutoInterface peer visible (peers=${snap.peers}, preferred=${snap.preferredInterface ?? \"none\"})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/presence-snapshot/applet.json","content":"{\n  \"id\": \"presence-snapshot\",\n  \"title\": \"Presence snapshot\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/presence-snapshot/main.js","content":"/**\n * Handbook applet: presence.snapshot() on this host.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const snap = await sdk.presence.snapshot();\n    if (snap === null || typeof snap !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a presence snapshot object, got: ${String(snap)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `peers=${snap.peers} interfaces=${snap.onlineInterfaces} preferred=${snap.preferredInterface ?? \"none\"}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/resource-fetch/applet.json","content":"{\n  \"id\": \"resource-fetch\",\n  \"title\": \"Resource fetch with budget\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"resource:fetch\"\n  ],\n  \"surfaces\": [\n    \"resource.fetch\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/resource-fetch/main.js","content":"/**\n * Handbook applet: resource.fetch under a host budget.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const bytes = await sdk.resource.fetch({\n      resourceId: \"handbook:probe\",\n      budgetBytes: 4096\n    });\n    if (!(bytes instanceof Uint8Array) || bytes.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected non-empty Uint8Array, got: ${typeof bytes}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Fetched ${bytes.length} byte(s) for handbook:probe`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable|not found/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/rnode-serial/applet.json","content":"{\n  \"id\": \"rnode-serial\",\n  \"title\": \"RNode serial / LoRa path\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"device-gated\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/rnode-serial/main.js","content":"/**\n * Handbook applet: RNode serial / LoRa interface (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. Connect an RNode over USB (desktop/Android) or BLE (iOS) per host docs.\",\n    \"2. Enable the RNode interface in the host app.\",\n    \"3. Confirm host.info lists `rnode` and the interface reports online.\",\n    \"4. Optional: exchange a small LXMF message with a peer over LoRa.\",\n    \"5. Re-run this applet — expect pass when the RNode path is online.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"rnode\")) {\n      report({\n        status: \"unavailable\",\n        details: `RNode interface not listed on ${info.platform}.\\n\\nGuided procedure (hardware):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.onlineInterfaces ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `RNode interface declared but no online interfaces (online=${snap.onlineInterfaces ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `RNode path online (interfaces=${snap.onlineInterfaces}, peers=${snap.peers ?? 0})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/share-cas/applet.json","content":"{\n  \"id\": \"share-cas\",\n  \"title\": \"CAS share put/get\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"share:cas\"\n  ],\n  \"surfaces\": [\n    \"share.put\",\n    \"share.get\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/share-cas/main.js","content":"/**\n * Handbook applet: share.put → share.get round-trip.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const content = `handbook-cas-${started}`;\n  try {\n    const put = await sdk.share.put(content);\n    if (put === null || typeof put !== \"object\" || typeof put.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Expected { t256 }, got: ${JSON.stringify(put)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (put.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected 94-char 256t id, got length ${put.t256.length}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const got = await sdk.share.get(put.t256);\n    if (got !== content) {\n      report({\n        status: \"fail\",\n        details: `CAS get mismatch: ${String(got)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `CAS round-trip (${put.t256.slice(0, 12)}…)`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-hyperbee/applet.json","content":"{\n  \"id\": \"storage-hyperbee\",\n  \"title\": \"Hyperbee round-trip\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"storage:hyperbee\"\n  ],\n  \"surfaces\": [\n    \"storage.bee.open\",\n    \"storage.bee.put\",\n    \"storage.bee.get\",\n    \"storage.bee.list\",\n    \"storage.bee.del\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-hyperbee/main.js","content":"/**\n * Handbook applet: storage.bee open → put → get → list → del.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = `handbook:bee:${started}`;\n  const payload = new TextEncoder().encode(`bee-${started}`);\n  try {\n    await sdk.storage.bee.open();\n    await sdk.storage.bee.put(key, payload);\n    const got = await sdk.storage.bee.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee get returned null after put\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (new TextDecoder().decode(got) !== `bee-${started}`) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value mismatch\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.storage.bee.list({ gte: key, limit: 5 });\n    if (!Array.isArray(listed) || listed.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee list did not include the put key\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.bee.del(key);\n    const after = await sdk.storage.bee.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value still present after del\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"Hyperbee open → put → get → list → del succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-kv/applet.json","content":"{\n  \"id\": \"storage-kv\",\n  \"title\": \"KV round-trip\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"storage:kv\"\n  ],\n  \"surfaces\": [\n    \"storage.kv.get\",\n    \"storage.kv.set\",\n    \"storage.kv.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-kv/main.js","content":"/**\n * Handbook applet: storage.kv set → get → delete.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = \"handbook:applet-kv-probe\";\n  const payload = new TextEncoder().encode(`probe-${started}`);\n  try {\n    await sdk.storage.kv.set(key, payload);\n    const got = await sdk.storage.kv.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"KV get returned null after set\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const text = new TextDecoder().decode(got);\n    if (text !== `probe-${started}`) {\n      report({\n        status: \"fail\",\n        details: `KV value mismatch: ${text}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.kv.delete(key);\n    const after = await sdk.storage.kv.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"KV value still present after delete\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"KV set → get → delete succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/widget-gallery/applet.json","content":"{\n  \"id\": \"widget-gallery\",\n  \"title\": \"Widget gallery smoke\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"ui.render\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/widget-gallery/main.js","content":"/**\n * Handbook applet: validate that every widget component type can appear in a tree.\n * Inline mode shares the Handbook sandbox; the runtime re-renders the chapter after.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    await sdk.workspace.write(\"probes/widget-gallery.txt\", \"gallery-seed\");\n\n    await sdk.ui.render({\n      root: {\n        id: \"gallery-root\",\n        type: \"scroll\",\n        style: { padding: 8, gap: 6 },\n        children: [\n          {\n            id: \"g-view\",\n            type: \"view\",\n            style: { gap: 4 },\n            children: [\n              { id: \"g-text\", type: \"text\", props: { value: \"Widget gallery\" } },\n              { id: \"g-image\", type: \"image\", props: { asset: \"handbook-icon\", alt: \"icon\" } },\n              { id: \"g-button\", type: \"button\", props: { label: \"Ok\", event: \"hb.gallery.noop\" } },\n              {\n                id: \"g-input\",\n                type: \"text-input\",\n                props: { value: \"\", placeholder: \"type\", event: \"hb.gallery.input\" }\n              },\n              { id: \"g-switch\", type: \"switch\", props: { value: false, event: \"hb.gallery.switch\" } },\n              { id: \"g-progress\", type: \"progress\", props: { value: 0.4 } },\n              { id: \"g-divider\", type: \"divider\" },\n              { id: \"g-spacer\", type: \"spacer\", props: { size: 8 } },\n              { id: \"g-list\", type: \"list\", props: { items: [\"item-a\", \"item-b\"] } },\n              {\n                id: \"g-editor\",\n                type: \"code-editor\",\n                props: { documentId: \"probes/widget-gallery.txt\", language: \"text\", readOnly: true }\n              },\n              {\n                id: \"g-qr\",\n                type: \"qr-code\",\n                props: { value: \"handbook-gallery\", caption: \"gallery\", size: 96 }\n              }\n            ]\n          }\n        ]\n      }\n    });\n\n    report({\n      status: \"pass\",\n      details:\n        \"Rendered scroll/view/text/image/button/text-input/switch/progress/divider/spacer/list/code-editor/qr-code\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/workspace-rw/applet.json","content":"{\n  \"id\": \"workspace-rw\",\n  \"title\": \"Workspace read/write\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"workspace.write\",\n    \"workspace.read\",\n    \"workspace.list\",\n    \"workspace.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/workspace-rw/main.js","content":"/**\n * Handbook applet: workspace write → patch → read → list → remove.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const path = `probes/workspace-${started}.txt`;\n  const body = `workspace-probe-${started}`;\n  try {\n    await sdk.workspace.write(path, body);\n    await sdk.workspace.patch(path, body.length, [{ start: body.length, end: body.length, text: \"-patched\" }]);\n    const read = await sdk.workspace.read(path);\n    if (read !== `${body}-patched`) {\n      report({\n        status: \"fail\",\n        details: `Workspace read mismatch: ${String(read)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.workspace.list(\"probes/\");\n    if (!Array.isArray(listed) || !listed.some((entry) => entry.path === path || entry === path)) {\n      const paths = Array.isArray(listed)\n        ? listed.map((entry) => (typeof entry === \"string\" ? entry : entry.path)).join(\", \")\n        : String(listed);\n      report({\n        status: \"fail\",\n        details: `Workspace list missing ${path}; got: ${paths}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.workspace.remove(path);\n    report({\n      status: \"pass\",\n      details: `Workspace write → patch → read → list → remove for ${path}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"chapters/concepts-in-practice/source.md","content":"# Concepts in practice\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe applets below run on **this** host — the same probes used in Part III and\nPart IV diagnostics, grouped for readers who want to see Reticulum building\nblocks work before diving into SDK chapters.\n\nIf the Handbook installed and these applets pass, you have verified identity\nderivation, announce loopback, and LXMF self-delivery on your current host.\n\n## Identity\n\nDerives the app destination hash from the host identity. No private keys in the\nsandbox.\n\n{{applet:identity-hash}}\n\n## Announce loop\n\nPublishes then subscribes in a local namespace — the discovery primitive apps use\nbefore install.\n\n{{applet:announce-loop}}\n\n## LXMF self-message\n\nSends and receives a message to this app’s own destination — store-and-forward on\nReticulum.\n\n{{applet:lxmf-roundtrip}}\n\nNext: [Identity & signing](chapter:sdk-identity) · [Running diagnostics](chapter:running-diagnostics)\n"},{"path":"chapters/device-gated-probes/source.md","content":"# Device-gated probes\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThese applets need **real hardware or a guided manual step** on a phone. In CI and\nsimulators they report `unavailable` with the procedure below — that is expected, not\na failure.\n\nWhen you complete a procedure on real hardware, register the run in the repo’s\n`STATUS-HARDWARE.md` (Handbook rows H21–H22).\n\n## Before you start\n\n- Use two peers on the same LAN for BLE and AutoInterface probes when possible.\n- Keep the host app in the **foreground** during discovery windows.\n- Export a diagnostic report on each device and use **Compare report** to diff results.\n\n## BLE peer\n\nRequires two phones with BLE enabled and the BLE interface turned on in host settings.\nExpect `unavailable` in simulators; on hardware you should see at least one peer in\npresence before the applet reports `pass`.\n\n{{applet:ble-peer}}\n\n## RNode serial / LoRa\n\nConnect an RNode per the host interface docs. Enable the RNode interface, then run the\nprobe. Desktop and Android support USB serial; iOS uses BLE to the RNode.\n\n{{applet:rnode-serial}}\n\n## Multicast / AutoInterface\n\nTwo LAN peers with AutoInterface or Bonjour discovery enabled. iOS may need the\nmulticast entitlement — see [Known limitations](chapter:ref-limitations) §4.\n\n{{applet:multicast-auto}}\n\n## Camera QR scan\n\nPoint the device camera at a Handbook diagnostic report QR or any valid 256t id QR\ngenerated on another screen. Simulators lack a camera path and report `unavailable`.\n\n{{applet:camera-qr-scan}}\n\nAfter hardware runs, compare reports: [Running diagnostics](chapter:running-diagnostics).\n"},{"path":"chapters/difference-matrix/source.md","content":"# Live difference matrix\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nHosts share one SDK and widget protocol, but platform sandboxes and entitlements\nshape what is actually available. Per-host chapters describe architecture and\nlifecycle; `host.info()` returns the facts for **this** host — platform id, host /\nAPI versions, enabled roles, interface types, and quota snapshot — instead of\nasserting differences in stale prose.\n\n- [Android host](chapter:host-android) · [iOS host](chapter:host-ios) ·\n  [Desktop host](chapter:host-desktop) · [Web host](chapter:host-web) ·\n  [Headless node & seeder](chapter:host-headless)\n\n## Probe\n\n{{applet:host-info}}\n\n## How to read differences\n\n| Signal | Typical cause | See also |\n|---|---|---|\n| `platform=web` + no `auto`/`ble` | Browser leaf: WebSocket gateway only | [Web host](chapter:host-web), [Known limitations](chapter:ref-limitations) §8 |\n| `platform=ios` + missing multicast | Multicast entitlement / Bonjour path | [iOS host](chapter:host-ios), [Known limitations](chapter:ref-limitations) §4 |\n| `transport=false` on phones | Leaf role; desktops default transport + seeder | [Android](chapter:host-android) / [Desktop](chapter:host-desktop) |\n| Interface listed but offline | Feature present; peer/hardware not connected | Part IV diagnostics |\n| `not-granted` applet cards | User withheld a manifest capability | [Capability model](chapter:sdk-capabilities) |\n| BLE / RNode / camera `device-gated` | Hardware or second device required | [Device-gated probes](chapter:device-gated-probes) |\n| Large install over BLE slow | Bulk plane vs Resource fallback | [Budgets & quotas](chapter:sdk-budgets) |\n\nCross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all\napplets, export a report via `share:cas`, then paste another device's 256t id to\ndiff results side-by-side.\n"},{"path":"chapters/host-android/source.md","content":"# Android host\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe Android host is a React Native shell around the same **Bare worklet** used on\niOS and desktop. Reticulum, LXMF, catalog install, and the mini-app runtime all\nrun in the worklet; the JVM layer supplies lifecycle, BLE, multicast bridges, and\na foreground service so the node can stay reachable in the background.\n\n## Architecture\n\n- **Expo / RN shell** — settings, grants, confirmations, widget renderer.\n- **Bare worklet child** — `reticulum-ts`, `host-core` leaf roles, broker, sandboxes.\n- **Native bridges** — TCP, AutoInterface multicast, Bonjour, BLE central/peripheral,\n  RNode serial-over-BLE, camera (QR install).\n\n## Roles\n\nAndroid phones default to **leaf** peers: transport routing and package seeding are\noff unless the operator enables them on a dedicated device. Most users run a leaf\nthat dials LAN peers or a desktop gateway.\n\n## Lifecycle\n\n- **Foreground** — full interface set, mini-app execution, BLE active.\n- **Background** — `NodeForegroundService` keeps the worklet alive; interfaces\n  quiesce on a grace timer then reconnect on resume (see\n  [Known limitations](chapter:ref-limitations) §3).\n- **Suspended** — no mini-app execution; LXMF store-and-forward only.\n\n## Storage\n\nApp data lives under the host's private app storage. Identity keys and package\narchives are worklet-managed; clearing app data resets the peer.\n\n## What to expect on this host\n\nUse the [live difference matrix](chapter:difference-matrix) on a real device or\nemulator — `host.info()` reports `platform=android`, interface types, and roles\nfor **this** install. BLE pair, RNode, multicast, and camera probes are\n[device-gated](chapter:device-gated-probes) in CI.\n"},{"path":"chapters/host-desktop/source.md","content":"# Desktop host\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe desktop host is the **always-on peer** in a typical mesh: transport routing,\npackage seeding, optional LXMF propagation, and a gateway for browser tabs via\nthe WebSocket Reticulum interface.\n\n## Architecture\n\n- **Electron shell** (`apps/host-desktop`) — tray, power events, native multicast/\n  Bonjour bridges, crash supervision, DOM widget renderer.\n- **Bare worklet child** — same stack as mobile; stdio IPC to the shell.\n- **`host-core`** — shared engine with headless `tp node` / `tp seed`.\n\n## Default roles\n\n| Role | Default | Notes |\n|---|---|---|\n| Transport node | on | Off when `--attach-rnsd` leaf mode |\n| Seeder / LAN mirror | on | Quota'd Hyperdrive serving |\n| Propagation server | off | Enable in UI or `--propagation` |\n| WebSocket gateway | off | `--ws-listen` for web-host tabs |\n\n## Lifecycle\n\n- **Suspend** (system sleep) — worklet quiesces interfaces.\n- **Resume** — reconnect and re-announce.\n- **Crash** — supervisor restarts the worklet with exponential backoff.\n\n## First-boot apps\n\nFresh desktop installs seed **handbook**, **devstudio**, and **chat** from the\nTwistedPear platform publisher. Open **Installed** and launch **handbook** — you\nare reading it.\n\n## Config & data\n\nPlatform data directory (identity, `config.json`, quotas):\n\n- macOS: `~/Library/Application Support/TwistedPear/host`\n- Linux: `~/.local/share/twistedpear/host`\n- Windows: `%APPDATA%/TwistedPear/host`\n\nFull schema: [Host configuration](chapter:ref-host-config).\n\nOpt-in status JSON: `http://127.0.0.1:9473/status` when `--status-endpoint` is set.\n\nLive capability view: [Live difference matrix](chapter:difference-matrix).\nStorage paths and roles: [Host configuration](chapter:ref-host-config).\n"},{"path":"chapters/host-headless/sample-0.txt","content":"tp node --data-dir ~/.local/share/twistedpear/host\ntp node --ws-listen 9480 --serve-web\ntp node --attach-rnsd 127.0.0.1:4242 --no-transport\ntp node --propagation --status-endpoint\n"},{"path":"chapters/host-headless/sample-1.txt","content":"tp seed --transport --state-dir .tp/seeder\n"},{"path":"chapters/host-headless/source.md","content":"# Headless node & seeder\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`tp node` and `tp seed` run **`host-core`** without a UI — the same engine as the\ndesktop worklet, suitable for servers, CI, and LAN gateways.\n\n## `tp node`\n\nAlways-on desktop-class peer from the CLI:\n\n```bash\ntp node --data-dir ~/.local/share/twistedpear/host\ntp node --ws-listen 9480 --serve-web\ntp node --attach-rnsd 127.0.0.1:4242 --no-transport\ntp node --propagation --status-endpoint\n```\n\nCommon flags:\n\n- `--no-transport` / `--no-seeder` — leaf or attach-only modes\n- `--ws-listen [host:]port` — WebSocket gateway for browser tabs\n- `--ws-token <token>` — optional shared secret on the gateway\n- `--serve-web [dir]` — serve the built web-host bundle from this machine\n- `--status-endpoint` — localhost JSON status on port 9473\n\n## `tp seed`\n\nHeadless package mirror focused on Hyperdrive seeding:\n\n```bash\ntp seed --transport --state-dir .tp/seeder\n```\n\nUse when you want seeding without the Electron shell. Quotas match desktop defaults\n(see [Quotas & limits](chapter:ref-quotas)).\n\n## When to use headless vs desktop\n\n| Need | Headless | Desktop host |\n|---|---|---|\n| WebSocket gateway for web tabs | `tp node --ws-listen` | enable in config / CLI |\n| Tray UI + crash supervision | — | Electron shell |\n| CI / docker interop | `tp node` in containers | optional |\n| Developer mini-app side-load | `tp dev` targets either | `tp dev` |\n\n## Handbook on node\n\nCI runs the Handbook with `npm run test:handbook` — pack, install, render every\nchapter, execute applets on the Node Worker sandbox backend. This is the same\ncatalog desktop seeds, without graphics.\n\nCLI reference: [CLI commands](chapter:ref-cli).\n"},{"path":"chapters/host-ios/source.md","content":"# iOS host\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe iOS host mirrors Android: a React Native shell supervising a **Bare worklet**\nwith the same protocol stack. Platform entitlements and background rules shape\nwhich interfaces stay online when the app is not in the foreground.\n\n## Architecture\n\n- **Expo / RN shell** — peer browser, grants, confirmations, widget renderer.\n- **Bare worklet child** — identical broker and sandbox model to Android/desktop.\n- **Native bridges** — TCP client, Bonjour, BLE (central/peripheral), RNode\n  over BLE only (no USB serial on iOS).\n\n## Lifecycle (no foreground-service equivalent)\n\niOS has no Android-style foreground service. Backgrounding is a **state\ntransition**:\n\n- **Foreground** — interfaces and the active mini-app run normally.\n- **Background grace** — native lifecycle sends `suspend-node`; worklet quiesces\n  TCP/multicast timers; existing BLE links may survive briefly.\n- **Suspended** — no mini-app execution; pending LXMF is persisted for later sync.\n\nStore-posture builds refuse catalog install and dev side-load; development builds\nkeep parity with Android for `tp dev` and Handbook installs.\n\n## Entitlements\n\nLocal network, Bonjour (`_reticulum._udp`), Bluetooth, and multicast require\nusage strings and (for multicast) the networking multicast entitlement. Until\nentitlement filing completes, multicast may report unavailable even though the\ncode path exists — check `host.info()` on **this** device.\n\n## Simulator vs device\n\nThe simulator validates worklet boot, TCP/localhost, store-posture refusal, and\nHandbook software-tier slices. BLE, real background timing, and LAN multicast\nneed hardware — see [Device-gated probes](chapter:device-gated-probes).\n\nCompare live signals: [Live difference matrix](chapter:difference-matrix).\n"},{"path":"chapters/host-web/sample-0.txt","content":"Browser tab (Expo web)\n  host UI + RNW widget renderer\nCore Web Worker — reticulum-ts, host-core leaf, broker\nPer-app sandbox — iframe + Worker, broker-only API\nWebSocketClientInterface ──wss──▶ gateway node\n"},{"path":"chapters/host-web/source.md","content":"# Web host\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe web host is a **browser tab** running the full mini-app stack in-page — not a\nremote UI for another node. `reticulum-ts` executes in a core Web Worker;\nper-app sandboxes use opaque-origin iframes plus workers; the host UI renders\nwidgets with React Native for Web.\n\n## Leaf-only posture\n\nBrowsers cannot accept inbound connections or open raw TCP/UDP. The web host is\npermanently a **leaf peer**:\n\n- No transport-node, seeder, or propagation roles — ever.\n- Reticulum reachability goes through a **WebSocket gateway** on a desktop or\n  `tp node` peer (`--ws-listen`).\n- Bulk installs use the gateway's `/bulk-fetch` proxy; offline fallback is\n  Reticulum Resource transfer.\n\n## Architecture\n\n```\nBrowser tab (Expo web)\n  host UI + RNW widget renderer\nCore Web Worker — reticulum-ts, host-core leaf, broker\nPer-app sandbox — iframe + Worker, broker-only API\nWebSocketClientInterface ──wss──▶ gateway node\n```\n\n## Security notes\n\nIdentity keys live in IndexedDB encrypted with WebCrypto — weaker than a hardware\nkeystore. The **page origin is part of the trust base**: default posture is\nself-serving from your own node (`tp node --serve-web`). See\n[Known limitations](chapter:ref-limitations) §8.\n\n## Radios & serial\n\nNo BLE peripheral, no multicast AutoInterface. WebSerial RNode (Chromium) is a\nstretch path; real USB LoRa E2E is device-gated. Probes report `unavailable`\nhonestly on `platform=web`.\n\nGateway spec: [WebSocket interface](chapter:ref-interfaces). Live matrix:\n[Live difference matrix](chapter:difference-matrix).\n"},{"path":"chapters/pears-bulk-plane/source.md","content":"# Pears bulk plane\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nReticulum is the **control plane** — identity, announces, links, LXMF, and\noff-grid Resource transfer. When IP connectivity exists, large package syncs\nprefer the **Pears bulk plane**: Hypercore, Hyperdrive, and Hyperswarm.\n\n## Why two planes\n\nReticulum links are optimized for constrained carriers (BLE, LoRa) with small\nMTUs and high latency. Shipping a multi-megabyte `.tpkg` over those links works\nbut is slow. Hyperswarm discovery plus Hyperdrive replication uses TCP where\navailable and falls back to Reticulum Resources when it is not.\n\n## Building blocks\n\n- **Hypercore** — append-only signed logs. Each app package is a deterministic\n  archive keyed by the publisher's feed.\n- **Hyperdrive** — a filesystem view over one or more Hypercores. `tp publish`\n  seeds the signed `.tpkg`; peers replicate blocks from seeders on the LAN or\n  DHT.\n- **Hyperswarm** — topic-based peer discovery for Hyperdrive replication. Desktop\n  and headless hosts run seeders by default; phones are usually leaf consumers.\n\n## In practice\n\n| Operation | Typical plane |\n|---|---|\n| Discover an app announce | Reticulum control plane |\n| Install over LAN / internet | Hyperdrive bulk fetch |\n| Install with no IP path | Reticulum Resource transfer |\n| LXMF chat message | Reticulum only |\n| Handbook diagnostic report (`share.put`) | CAS + optional Hyperdrive seed |\n\nHeadless seeding: [Headless node & seeder](chapter:host-headless). Distribution\ntutorial: [Publish & install](chapter:sdk-apps-publish).\n"},{"path":"chapters/ref-capabilities/source.md","content":"# Capabilities\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nGenerated from `CAPABILITY_DEFINITIONS` in `packages/miniapp-runtime`.\nEvery id below must be exercised by at least one Handbook applet (coverage gate).\n\n- **`identity`** — Use an app-scoped identity for signing and addressing.\n- **`presence`** — Read coarse peer/interface presence and host info.\n- **`announce:subscribe`** — Receive announces in the app namespace.\n- **`announce:publish`** — Publish the app destination.\n- **`lxmf:send`** — Send LXMF messages from the app destination.\n- **`lxmf:receive`** — Receive LXMF messages for the app destination.\n- **`storage:kv`** — Store local key/value data for this app.\n- **`storage:hyperbee`** — Store ordered local Hyperbee data for this app.\n- **`resource:fetch`** — Fetch package resources through host budget rules.\n- **`workspace`** — Read and write project source files in this app's private workspace.\n- **`ai:chat`** — Send prompts to the host-configured AI service; prompts may include workspace content.\n- **`ai:embed`** — Send bounded text to the host-configured embedding model and rank vectors locally.\n- **`apps:package`** — Package and sign apps under this device's publisher identity (asks each time).\n- **`apps:publish`** — Publish signed apps so other users can find and install them (asks each time).\n- **`apps:install`** — Ask the host to install apps from a 256t id (asks each time, with capability review).\n- **`apps:preview`** — Run a built app in the host's sandboxed dev-preview slot.\n- **`share:cas`** — Store and retrieve bounded content-addressed data shared by 256t id.\n\nManifests declare the full list; users may grant a subset at install.\nWithholding a capability turns matching probes into `not-granted` cards.\n\nTutorial: [Capability model](chapter:sdk-capabilities).\nPer-namespace guides: [Developing mini-apps](chapter:sdk-identity).\n"},{"path":"chapters/ref-cli/source.md","content":"# CLI commands\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nThe `tp` CLI scaffolds, packs, publishes, and runs headless peers. Publisher\nidentity comes from `tp init` (Reticulum keypair in the project or data dir).\n\n## Project workflow\n\n- `tp init [--force]` — create or load publisher identity\n- `tp create <hello|chat-min> [app-dir]` — scaffold a mini-app template\n- `tp dev <app-dir> [--host host:port]` — build and side-load to a dev-mode host\n- `tp pack <app-dir> [--out file.tpkg]` — build unsigned `.tpkg` archive\n- `tp sign <file.tpkg>` — re-sign an existing package\n- `tp publish <app-dir>` — pack, sign, publish to Hyperdrive\n- `tp update <app-dir> --version <semver>` — bump version and republish\n\n## Headless hosts\n\n- `tp node` — transport/seeder/propagation peer (`--ws-listen`, `--serve-web`, …)\n- `tp seed` — headless Hyperdrive seeder (`--transport`, `--state-dir`)\n\n## Trust\n\n- `tp trust list|show|add|remove` — manage trusted publisher keys\n\nHandbook packaging in CI: `npm run build:handbook` then `tp pack` in a temp dir.\nTutorial: [Packaging & preview](chapter:sdk-apps-package).\n"},{"path":"chapters/ref-host-api/source.md","content":"# Host API\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nCurrent `HOST_API_VERSION`: **`0.7.0`**.\nManifests pin `minHostApi`; hosts reject packages that require a newer API.\n\n## Changelog\n\n- **`0.1.0`** — Initial mini-app host API: capabilities, broker, lifecycle, widget tree UI, and SDK v1 namespaces.\n- **`0.2.0`** — Dev-environment capabilities (workspace, ai:chat, apps:*, share:cas), host confirmation channel, dynamic resource limits, pre-launch capability review, code-editor and qr-code widgets.\n- **`0.3.0`** — host.info() — platform id, host version, HOST_API_VERSION, enabled roles, interface types, and quota snapshot for Handbook diagnostics.\n- **`0.4.0`** — host.info() includes grantedCapabilities for the calling mini-app (Handbook grant intro and diagnostics).\n- **`0.5.0`** — ai.chatStream() adds cancellable, coalesced streaming while preserving ai.chat().\n- **`0.6.0`** — ai.embed() and ai.search() add host-proxied embeddings and bounded cosine vector search.\n- **`0.7.0`** — workspace.patch() and delta code-editor events add conflict-safe incremental editing.\n\n## host.info()\n\nReturns platform id, host version, API version, roles, interface types, and quota\nsnapshot — used by the [live difference matrix](chapter:difference-matrix).\n\n## Workspace quotas\n\n- 262144 bytes/file\n- 4194304 bytes total per app\n- 512 files per app\n"},{"path":"chapters/ref-host-config/source.md","content":"# Host configuration\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nGenerated from `defaultHostConfig()` defaults in `packages/host-core`.\nDesktop and `tp node` persist overrides in `<data-dir>/config.json`.\n\n## Data directory\n\n- macOS: `~/Library/Application Support/TwistedPear/host`\n- Linux: `~/.local/share/twistedpear/host`\n- Windows: `%APPDATA%/TwistedPear/host`\n- Identity: `<data-dir>/identity`\n- Config: `<data-dir>/config.json`\n\nPlatform paths: [Desktop host](chapter:host-desktop). Headless flags:\n[CLI commands](chapter:ref-cli).\n\n## Roles (desktop defaults)\n\n- Transport node: true\n- Seeder / LAN mirror: true\n- Propagation server: false\n- Attach to external rnsd: off\n\nWeb hosts force leaf roles — see [Web host](chapter:host-web).\n\n## Interfaces (desktop defaults)\n\n- TCP client: off (target 127.0.0.1:4242)\n- WebSocket gateway: off (listen 127.0.0.1:9480)\n- AutoInterface multicast: true\n- Bonjour discovery: true\n- I2P SAM: false\n- RNode serial: false\n\nInterface behavior: [Network interfaces](chapter:ref-interfaces).\n\n## Quotas\n\nSeed storage, propagation store, message count, and bandwidth caps match\n[Quotas & limits](chapter:ref-quotas). Override under the `quotas` key.\n\n## AI endpoint\n\n`ai` is `null` until configured (desktop **Settings → AI** or `config.json`). Chat and\nembedding models are configured separately. Mini-apps use `ai:chat` and `ai:embed` through\nthe host proxy — see [AI chat](chapter:sdk-ai-chat).\n\n## Status endpoint\n\nOpt-in JSON at `http://127.0.0.1:9473/status` when `statusEndpoint: true`\nor `tp node --status-endpoint`.\n"},{"path":"chapters/ref-interfaces/source.md","content":"# Network interfaces\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nReticulum peers attach through typed **PacketInterface** implementations.\nThe [live difference matrix](chapter:difference-matrix) lists which types\n`host.info()` reports for **this** host.\n\n## WebSocket (browser gateway)\n\n- **Leaf client** — browser tab or CI harness dials `ws://` / `wss://` on a gateway.\n- **Gateway** — desktop host or `tp node --ws-listen [host:]port`.\n- **Framing** — one Reticulum wire packet per binary WebSocket message.\n- **Auth** — optional shared token (`--ws-token`).\n\nWeb host chapter: [Web host](chapter:host-web).\n\nWebSocket wire format is documented in the platform repo under\n`docs/websocket-interface.md` (not shipped inside the Handbook bundle).\n\n## TCP / AutoInterface / Bonjour\n\nDesktop and mobile worklets enable TCP client mode, LAN multicast (AutoInterface),\nand Bonjour discovery when the platform permits. iOS multicast requires the\nnetworking multicast entitlement; web hosts omit these entirely.\n\n## BLE phone pipe\n\nAndroid and iOS expose a BLE GATT byte stream for peer links. Web Bluetooth is\ncentral-only and not used for the phone-pipe role. Device-gated Handbook probes:\n[Device-gated probes](chapter:device-gated-probes).\n\n## RNode serial\n\nUSB serial on desktop/Android; BLE-only on iOS. WebSerial (Chromium) is optional.\nLoRa bandwidth budgets apply — see [Known limitations](chapter:ref-limitations) §6.\n"},{"path":"chapters/ref-limitations/source.md","content":"# Known limitations\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nPlatform compromises and measured constraints. Cross-linked from host chapters\nand the [live difference matrix](chapter:difference-matrix).\n\n# Limitations, Compromises, and Restrictions\n\n\n<!-- tp-doc\nlifecycle: reference\naudited: 2026-07-21\nregister: none\n-->\n\nCompanion to archive/design/plan-v0.md. Reticulum compatibility is the only hard constraint;\neverything below is a known cost of the chosen design or of the platforms involved.\n\n## 1. Reticulum implementation\n\n- **No production JS implementation exists.** The reference RNS is Python. The only JS\n  implementation, `rns.js` (v0.0.4), is self-described as extremely limited: no transport-node\n  routing, no ratchets, no Resources, no link heartbeats, no UDP interface, no LXMF signature\n  validation, no rate limiting. We are committing to building and maintaining\n  `reticulum-ts` — a substantial, ongoing engineering effort, not an integration task.\n- **Wire-format chase.** Reticulum evolves (ratchets were added relatively recently). Every\n  protocol change in the reference must be re-implemented and re-verified; until parity is\n  reached, some network features may silently not work with newer Python peers.\n- **Crypto parity risk.** We must match X25519/Ed25519/AES-256-CBC/HMAC-SHA256 semantics\n  byte-for-byte. Any deviation is a security bug, not just an interop bug. JS crypto is also\n  slower than the C-backed Python primitives; older phones may see slow link setup and\n  hashing (mitigated by libsodium native bindings in Bare).\n\n  **Measured Node pure-provider throughput (200 iterations, CI baseline):**\n\n  | Operation | ops/s (Node pure) |\n  |---|---:|\n  | x25519-keygen | 1,134 |\n  | x25519-shared-secret | 1,158 |\n  | hkdf-link-key | 31,470 |\n  | aes-256-cbc-encrypt-512 | 57,823 |\n  | ed25519-sign-64 | 2,807 |\n  | sha256-resource-chunk | 206,950 |\n\n  Source: `conformance/bare-runtime/baseline-node.json` (`npm run test:bare-benchmark-compare`).\n\n  **Measured sodium-native provider on host Node (200 iterations, CI baseline):**\n\n  | Operation | ops/s (sodium-native) |\n  |---|---:|\n  | x25519-keygen | 50,000 |\n  | x25519-shared-secret | 25,000 |\n  | hkdf-link-key | 28,571 |\n  | aes-256-cbc-encrypt-512 | 50,000 |\n  | ed25519-sign-64 | 33,333 |\n  | sha256-resource-chunk | 200,000 |\n\n  Source: `conformance/bare-runtime/baseline-bare.json` (`npm run test:bare-benchmark-bare-compare`).\n  Bare worklet on-device numbers remain open until H11. Link-setup latency\n  (Node pure, docker link-echo peer): see `conformance/link-benchmark/measured.json`\n  (`INTEROP=1 npm run test:link-benchmark`; CI `interop` job records with `LINK_BENCHMARK_RECORD=1`).\n\n## 2. Expo Go — sacrificed\n\n- The system requires native modules (bare-kit worklet, BLE central+peripheral, IPv6\n  multicast, foreground service, USB serial). **Expo Go cannot load custom native modules,\n  so the host app will not run in Expo Go.**\n- Compromise: keep the Expo toolchain but use **development builds** (`expo-dev-client`)\n  and config plugins. Developers get most of the Expo DX; they just install a custom dev\n  client instead of Expo Go. *Mini-app* developers are unaffected (pure JS against our SDK).\n\n## 3. Bluetooth\n\n- **Reticulum has no phone-to-phone Bluetooth interface today.** Official BLE support is\n  only for connecting to RNode LoRa hardware. Our phone-to-phone BLE interface is a custom\n  interface we define. Reticulum explicitly supports custom interfaces (≥5 bps, 500-byte\n  MTU), so it is protocol-legal — but until other implementations adopt our spec, BLE\n  meshing only works host-app-to-host-app.\n- **BLE is slow.** Practical GATT throughput is tens of kbps at best; fine for messaging\n  and announces, marginal for app installs (a 1 MB mini-app can take minutes). MTU ~185–512\n  bytes forces fragmentation/reassembly below Reticulum's 500-byte MTU.\n- **No Bluetooth Classic on iOS** (no SPP for arbitrary apps); BLE only. Android OEM BLE\n  stacks vary wildly; peripheral mode is unsupported on some older/cheap devices.\n- Simultaneous central+peripheral roles, background advertising limits (iOS rotates/strips\n  advertisement data in background), and pairing UX are all sources of flakiness.\n\n## 4. iOS restrictions (most constrained platform)\n\n- **Background execution:** iOS will suspend the app; there is no equivalent of Android's\n  foreground service for a general network daemon. An iPhone cannot be a reliable\n  always-on Reticulum transport node. Compromise: opportunistic connectivity (foreground,\n  brief background windows, BLE background modes) and reliance on desktop/Android peers\n  for routing.\n- **Multicast entitlement:** AutoInterface peer discovery uses IPv6 multicast, which\n  requires `com.apple.developer.networking.multicast` — granted by Apple on application,\n  with lead time and no guarantee. Application draft prepared (Phase 2 M8); **status:\n  not yet submitted / H12 pending** — see\n  docs/ios-multicast-entitlement.md and\n  STATUS-HARDWARE.md (H12–H15). Fallback: LAN discovery via Bonjour\n  (`_reticulum._udp`) + direct UDP, or manual/TCP peers.\n- **Bonjour fallback gap:** an un-entitled iPhone can discover TS nodes that advertise\n  `_reticulum._udp`, but cannot discover stock Python RNS AutoInterface peers through\n  Bonjour. Reaching those peers requires the multicast entitlement, a TCP link, or a TS\n  peer relaying as a transport node.\n- **Downloaded code (App Review 3.3.2):** mini-apps are downloaded JS. Apple permits\n  downloaded JS executed by Apple frameworks when it doesn't change the app's core\n  purpose — an app *store inside an app* is exactly the gray zone Apple scrutinizes.\n  Compromises: declarative UI whitelist (host renders, mini-apps don't ship arbitrary UI\n  code paths), curated capability model, and acceptance that **the iOS build may need a\n  reduced distribution feature set** or TestFlight/enterprise/EU-alternative-distribution\n  channels. Phase 5 adds a store-posture build flag and dossier in\n  docs/ios-submission.md; no submission is attempted in this\n  phase.\n- **No sideloading escape hatch** outside the EU. If Apple rejects the concept, iOS becomes\n  a client (messaging, using apps already vetted) rather than a full open platform.\n\n## 5. Android restrictions\n\n- Persistent mesh participation requires a **foreground service** with a permanent\n  notification; Doze and OEM battery managers can still throttle networking. Battery cost\n  of always-on BLE + multicast is real and must be budgeted/opt-in.\n- **Google Play policy** restricts apps that download executable code. Interpreted JS in a\n  sandbox is a recognized carve-out, but a P2P app store pushes the boundary. Escape hatch\n  (which iOS lacks): distribute the host APK directly / via F-Droid — itself fitting the\n  project's P2P ethos.\n- Wi-Fi Direct / Aware are inconsistent across OEMs; plan treats them as future\n  opportunistic interfaces, not committed ones. LAN AutoInterface + BLE are the committed\n  local transports.\n\n## 6. Pears stack scope\n\n- **Hyperswarm/Hyperdrive require IP connectivity** (UDX over UDP, DHT access). They do not\n  run over Reticulum. Off-grid (LoRa/BLE-only) distribution therefore falls back to\n  Reticulum Resource transfer, which is orders of magnitude slower — a mini-app must be\n  assumed installable at LoRa speeds only if it is very small. Compromise: size budgets for\n  bundles, delta updates, and LAN/desktop seeding as the primary bulk path.\n\n  **Measured install budgets (Phase 3 M9, conservative bitrates):**\n\n  | Package | Size | LAN (~8 Mbps) | BLE (~24 kbps) | RNode (~1.2 kbps) |\n  |---|---:|---|---|---|\n  | `tiny` (budget hello-world) | ~900 B | <1 s | <1 s | ~6 s |\n  | `example-app` (minimal mini-app) | ~780 B | <1 s | <1 s | ~6 s |\n  | `chat` (Phase 4 example) | ~2.6 KiB | <1 s | <1 s | ~18 s |\n  | `file-drop` (Phase 4 example) | ~1.8 KiB | <1 s | <1 s | ~12 s |\n  | `board` (Phase 4 example) | ~2.1 KiB | <1 s | <1 s | ~15 s |\n\n  Under-one-minute ceilings at these rates: LAN ~60 MiB, BLE ~180 KiB, RNode ~9 KiB.\n  `bridge-hyper` blocks automatic bulk fetch over RNode-only links above 64 KiB and warns\n  above 32 KiB; BLE warnings start at 256 KiB. See   `conformance/budgets/measured.json`\n  for regenerated numbers (`npm run test:budgets`).\n- Android emulator Bare Worker spawn/kill/busy-loop metrics: `conformance/android-emulator/measured-worker.json`\n  (`ANDROID_BENCHMARK_RECORD=1 npm run test:android-emulator:e5` on KVM emulator).\n- Holepunch's DHT bootstrap nodes are an external dependency; fully-sovereign deployments\n  need self-hosted bootstrap or LAN-only swarm mode.\n- The Pears components are the most replaceable part of the design (per the constraint\n  hierarchy): if bare-kit or Hyperdrive proves unworkable on mobile, fallbacks are Node\n  (nodejs-mobile) + plain RNS Resources for distribution.\n- **Desktop host (Phase 6):** `apps/host-desktop` runs the same Bare worklet as mobile under\n  Electron supervision (stdio IPC, not in-process Node). Windows NSIS artifacts are built in\n  CI but not verified until register **H17**. Propagation node-to-node peering is a stretch\n  goal — client sync against `lxmd` is implemented; meshed multi-node stores should use\n  `lxmd` until peering ships.\n\n## 7. Mini-app model\n\n- **Embeddings are request-scoped, not a vector database:** `ai.embed` and `ai.search`\n  require a separate grant and host-configured embedding model, share the per-app AI\n  in-flight slot, cap each input at 16,384 characters, cap batches at 64 inputs and vectors\n  at 4,096 dimensions, and persist no index. `ai.search` accepts at most 63 documents because\n  the query occupies the remaining batch slot.\n\n- Mini-apps are **not native apps**: no arbitrary native modules, no background autonomy,\n  capabilities only via the host SDK. Some app categories (games needing native perf,\n  apps needing exotic hardware) won't fit; the tiered-APK channel was deliberately deferred.\n- JS sandboxing inside one runtime is a real attack surface. Phase 7 completed a software-tier\n  adversarial review of the broker chokepoint (docs/security-review.md);\n  mini-app installation still trusts the publisher signature for declared behavior.\n- Phase 4 ships a broker chokepoint, deny-by-default capability grants, data-only widget\n  trees, and hostile-input conformance tests. Capability substitution and broker UI-event\n  forgery gaps found in review are fixed; **Bare Worker hostile parity on device** remains\n  open (H11). Watchdog thresholds may false-positive on low-end devices.\n- Desktop Node Worker sandbox metrics: `conformance/miniapp-benchmark/measured-desktop.json`\n  (`npm run test:miniapp-benchmark`; record with `MINIAPP_BENCHMARK_RECORD=1`).\n- One foreground mini-app at a time in v1; no background execution. Dev side-loading is\n  localhost/adb-only, off by default, and badged **DEV** in the UI.\n- No central registry means **no central moderation**: discovery is by announce/registry\n  subscription, and malicious-app defense rests on signatures, capability grants, and\n  user/community trust. LXMF block/mute lists and report records are local; exporting a report\n  does not submit it or cause a network-wide ban.\n- Multipart propagation is a TwistedPear framing convention over ordinary signed LXMF\n  messages, not an LXMF attachment standard. It defaults to 64 KiB, hard-stops at 1,000,000\n  bytes, and uses 32-byte content frames with 16-byte titles to remain on the packet\n  propagation path. It is resumable but airtime-expensive; use Resources or\n  content-addressed sharing for bulk data.\n- `ai.chatStream` coalesces provider events before crossing the broker; deltas are not token\n  boundaries. Streaming and whole-response chat share one in-flight request per app, and\n  stopping iteration cancels the host-side stream.\n- **Dev environment (DevStudio) v1 limits:** projects are single-file bundles (no\n  in-host bundler); workspace files are capped at 256 KiB as a host safety quota, while\n  `code-editor` changes use conflict-checked deltas; AI editing streams a whole-file proposal through an\n  OpenRouter-compatible endpoint configured host-side; one dev-preview slot; desktop\n  QR support renders codes but accepts pasted 256t strings only (camera scan is a\n  mobile-host follow-up); memory-limit changes apply at the next launch, while rate\n  and storage-quota changes apply live; 256t locator announces must have been received\n  before an install can resolve (no locator re-request yet).\n\n## 8. Web platform (see [docs/web-host.md](chapter:host-web))\n\n- **Leaf-only, gateway-dependent:** browsers cannot accept inbound connections or open raw\n  TCP/UDP sockets, so the web host reaches Reticulum only through the WebSocket interface\n  of a gateway node it can dial. No transport-node, seeder, or propagation roles — ever,\n  on this target.\n- **No radios (gateway path):** Web Bluetooth is central-only (cannot run the peripheral\n  GATT stream), and there is no multicast/AutoInterface. RNode over WebSerial\n  (Chromium-only) is implemented as a stretch path with simulated-serial CI\n  (`test:web-rnode`); real USB LoRa E2E remains device-gated.\n- **Weaker key custody:** identity keys sit in IndexedDB encrypted under a WebCrypto key;\n  the portable `.tpidentity` and recovery-word settings flow is not yet exposed by the web host —\n  no hardware keystore equivalent. The serving origin is part of the TCB: whoever serves\n  the page bytes can substitute them. Default posture is self-serving from the user's own\n  node (`tp node --serve-web`).\n- **Sandbox mechanism differs:** mini-app isolation rests on opaque-origin sandboxed\n  iframes + workers and CSP rather than OS processes; it must pass the same adversarial\n  review as the native backends before any web release.\n- **Bulk plane via gateway:** Hyperswarm/Hyperdrive do not run in the browser tab. The web\n  host installs over Hyperdrive by calling the gateway's `/bulk-fetch` HTTP proxy (the node\n  joins Hyperswarm and streams the archive). Reticulum Resource transfer remains the\n  offline/fallback path. Direct WS DHT-relay client lookup still depends on\n  `@hyperswarm/dht-relay` ↔ `hyperdht` compatibility and is treated as experimental.\n- **Storage is evictable:** OPFS/IndexedDB live under browser quota and can be cleared by\n  the user agent; `navigator.storage.persist()` mitigates but does not guarantee.\n\n## 9. General\n\n- **Reader-guide image coverage:** 33 of 106 referenced images are reproducible captures\n  from the actual desktop renderer, mini-app runtime, or built web host. The other 73 remain placeholders where\n  the exact caption needs hardware, a multi-peer or populated-app fixture, a clean terminal\n  session, DevStudio interaction state, or editorial composition. The three `images/README.md`\n  files name every remainder; startup-only or invented UI is not substituted.\n- **Identity recovery UI coverage:** encrypted vaults, portable backup import/export, and\n  two-part BIP-39 recovery are implemented in `tp` and the desktop host. Mobile and browser\n  host settings do not yet expose those operations. Recovery does not rotate or revoke a key,\n  and simultaneous use of a restored identity on two hosts remains unsupported.\n- **Anonymity/privacy caveats:** BLE MAC addresses, WiFi multicast presence, and always-on\n  radios are locally observable even though Reticulum payloads are encrypted and packets\n  carry no source address. Physical-layer observability is out of scope for the stack.\n- **Time-to-usefulness:** a mesh platform is only as useful as its peer density; early\n  deployments depend on desktop transport nodes and TCP testnet links, not pure phone\n  meshes. Phase 6 adds always-on desktop peers (`tp node`, `host-desktop`) with transport +\n  seeding on by default; measured always-on quota behavior is tracked in register **H20**.\n- Amateur-radio carriers (AX.25/KISS) carry legal restrictions (no encryption on ham bands\n  in most jurisdictions) — supported by Reticulum but out of scope for this app's defaults.\n"},{"path":"chapters/ref-packages/source.md","content":"# Package format\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nMini-apps ship as deterministic **`.tpkg`** archives:\n\n- Signed manifest (name, version, entry, capabilities, publisher key, `minHostApi`)\n- Entry bundle (`bundle.js`) and assets\n- Ed25519 signature over the manifest hash\n\nPackaging flow: [Packaging & preview](chapter:sdk-apps-package).\nDistribution tutorial: [Publish, install & update](chapter:sdk-apps-update).\n"},{"path":"chapters/ref-quotas/source.md","content":"# Quotas & limits\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nGenerated from `DEFAULT_QUOTAS` (`host-core`) and miniapp-runtime defaults.\n`host.info()` includes a quota snapshot for diagnostics.\n\n## Host node quotas (desktop / `tp node`)\n\n- Seed storage: 2147483648 bytes\n- Propagation store: 268435456 bytes\n- Propagation messages: 10000\n- Bandwidth cap: 524288 bytes/s\n\nOverride in `<data-dir>/config.json` — see [Host configuration](chapter:ref-host-config).\n\n## Mini-app workspace (`workspace` capability)\n\n- 262144 bytes per file\n- 4194304 bytes total per app\n- 512 files per app\n\n## Widget & AI limits\n\n- Widget tree JSON: 256 KiB (default validator)\n- AI chat: 64 messages, 8192 max tokens cap\n\n## Transport budgets\n\nBLE install budgets (~180 KiB at measured rates) and Resource fetch caps are\nenforced per link type. See [Resource fetch](chapter:sdk-resource-fetch) and\n`conformance/budgets/measured.json`.\n"},{"path":"chapters/ref-widgets/source.md","content":"# Widget protocol\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nGenerated from `WIDGET_TYPES` / `WIDGET_PROP_KEYS` in `packages/miniapp-runtime`.\n\nHosts render a declarative tree (`ui.render`). Unknown types, props, styles,\nduplicate ids, or oversized trees are rejected.\n\n## Components\n\n- **`button`** — props: `event`, `label`\n- **`code-editor`** — props: `documentId`, `event`, `language`, `readOnly`\n- **`divider`** — props: none\n- **`image`** — props: `alt`, `asset`\n- **`list`** — props: `event`, `items`\n- **`progress`** — props: `max`, `value`\n- **`qr-code`** — props: `caption`, `size`, `value`\n- **`scroll`** — props: `event`, `scrollOffset`\n- **`spacer`** — props: `size`\n- **`switch`** — props: `event`, `value`\n- **`text`** — props: `value`\n- **`text-input`** — props: `event`, `placeholder`, `value`\n- **`view`** — props: `accessibilityLabel`\n\n## Styles\n\n- `alignItems`\n- `backgroundColor`\n- `color`\n- `display`\n- `flexDirection`\n- `fontSize`\n- `fontWeight`\n- `gap`\n- `height`\n- `justifyContent`\n- `margin`\n- `padding`\n- `width`\n\n## Limits\n\n- Widget tree JSON budget: 256 KiB (default validator)\n- `code-editor` languages: javascript, json, text\n- `qr-code` value: up to 512 characters (94-char 256t ids fit)\n\nLive gallery: [Widget gallery](chapter:sdk-widget-gallery).\n"},{"path":"chapters/reticulum-fundamentals/source.md","content":"# Reticulum fundamentals\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nReticulum is a cryptography-based networking stack designed for constrained and\nunreliable links. TwistedPear uses it as the only hard networking constraint.\n\n## Building blocks\n\n- **Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.\n- **Announce** — a signed public advertisement that a destination is reachable.\n- **Link** — an encrypted channel between two destinations.\n- **Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).\n- **LXMF** — store-and-forward messaging on top of Reticulum.\n\n## App-scoped destinations\n\nMini-apps never hold private keys. The host derives an **app destination** from\nthe device identity plus the app id. Bulk transfer when IP is available:\n[Pears bulk plane](chapter:pears-bulk-plane). See [Concepts in practice](chapter:concepts-in-practice)\nfor a live identity probe, or [Identity & signing](chapter:sdk-identity).\n"},{"path":"chapters/running-diagnostics/source.md","content":"# Running diagnostics\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\nEach applet reports `{ appletId, status, details, timings }` with first-class\n`unavailable` and `not-granted` outcomes — teaching moments, not hard errors.\n\n## On this screen\n\nFrom the Handbook **Contents**, open **Diagnostics** to:\n\n- **Run all diagnostics** — runs every catalog applet inline on this host, grouped\n  by area (crypto, interfaces, storage, distribution, runtime)\n- **Export report** — packs host info + results into JSON, stores via `share.put`,\n  shows a 256t id / QR\n- **Compare report** — paste another device's report id to render a status matrix\n  with expected platform differences marked\n\nOpen an SDK chapter and tap **Run applet** for a single probe.\n\n## Software-tier probes\n\n- Host info — `host.info` (`presence`)\n- App destination hash — `identity`\n- Presence snapshot — `presence`\n- KV round-trip — `storage:kv`\n- Hyperbee round-trip — `storage:hyperbee`\n- LXMF self-message — `identity`, `lxmf:*`\n- Announce publish/subscribe — `announce:*`\n- Resource fetch — `resource:fetch`\n- Workspace read/write — `workspace`\n- CAS share — `share:cas`\n- Package + preview — `apps:package`, `apps:preview`\n- Publish + install — `apps:publish`, `apps:install`\n- OTA update — republish with bumped semver\n- AI chat / embedding configuration — `ai:chat`, `ai:embed`\n- Widget gallery — widget protocol\n\nDevice-gated probes (BLE peer, RNode, multicast, camera QR) live in\n[Device-gated probes](chapter:device-gated-probes) — they report `unavailable` in CI\nand simulators with guided procedures for real hardware.\n\nCompare matrices use each applet’s expectation table to label platform differences\nas expected (`≈`) or unexpected (`≠`).\n"},{"path":"chapters/sdk-ai-chat/sample-0.js","content":"import { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n\nlet text = \"\";\nfor await (const event of ai.chatStream({\n  messages: [{ role: \"user\", content: \"hello\" }]\n})) {\n  if (event.type === \"delta\") text += event.delta;\n}\n\nconst ranked = await ai.search({\n  query: \"radio package budget\",\n  documents: [\n    { id: \"budgets\", text: \"Keep radio packages small.\" },\n    { id: \"identity\", text: \"Backups use recovery words.\" }\n  ],\n  limit: 1\n});\n"},{"path":"chapters/sdk-ai-chat/source.md","content":"# AI chat\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\n`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint;\n`ai:embed` sends bounded text to its separately configured embedding model.\nThe host clamps budgets, enforces a model allowlist, and allows one in-flight\nrequest per app. The API key never enters the sandbox.\n\n## Host configuration\n\nDesktop hosts configure AI under **Settings → AI** or in `config.json`. Until an\nendpoint is set, probes report `unavailable` — that is honest, not a failure.\nEmbeddings remain unavailable until an embedding model is also set.\n\n## API\n\n```javascript\nimport { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n\nlet text = \"\";\nfor await (const event of ai.chatStream({\n  messages: [{ role: \"user\", content: \"hello\" }]\n})) {\n  if (event.type === \"delta\") text += event.delta;\n}\n\nconst ranked = await ai.search({\n  query: \"radio package budget\",\n  documents: [\n    { id: \"budgets\", text: \"Keep radio packages small.\" },\n    { id: \"identity\", text: \"Backups use recovery words.\" }\n  ],\n  limit: 1\n});\n```\n\nWhole responses and final stream events include model id and usage counters when the host\nprovides them. Stream deltas are coalesced and are not token boundaries. Both calls share one\nin-flight slot per app; breaking out of iteration cancels the stream.\nEmbedding and search calls share that slot. Search accepts at most 63 documents and returns\nids plus cosine scores; it does not create a persistent host index.\n\n## Outcomes\n\n- `pass` — round-trip succeeded.\n- `unavailable` — no AI endpoint configured.\n- `not-granted` — `ai:chat` withheld.\n- `not-granted` — `ai:embed` withheld for embedding/search probes.\n\n## Live probe\n\nHosts without an AI endpoint report `unavailable`. When configured, the applet\nbelow exercises a single round-trip.\n\n{{applet:ai-chat}}\n\nDevStudio uses the same proxy for whole-file edits — [DevStudio walkthrough](chapter:sdk-devstudio).\n"},{"path":"chapters/sdk-announce/sample-0.js","content":"import { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish({ namespace: \"my-app\" });\nconst stream = await announce.subscribe({ namespace: \"my-app\" });\n"},{"path":"chapters/sdk-announce/source.md","content":"# Announce & subscribe\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nAnnounces are signed advertisements that a destination is reachable. Subscribe lets a\nmini-app observe announces in a namespace — useful for discovery without polling links.\n\n## Control-plane role\n\nAnnounces are part of the Reticulum **control plane**. They do not carry bulk data;\nthey tell peers *where* to open a link or which 256t id to fetch.\n\n## Capabilities\n\n- `announce:publish` — publish this app’s destination.\n- `announce:subscribe` — receive matching announces.\n\nBoth are required for the loopback probe below.\n\n## API\n\n```javascript\nimport { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish({ namespace: \"my-app\" });\nconst stream = await announce.subscribe({ namespace: \"my-app\" });\n```\n\nNamespaces are app-scoped. Publishing without subscribe (or vice versa) limits what\nprobes can demonstrate.\n\n## Live probe\n\n{{applet:announce-loop}}\n\nConcept background: [Reticulum fundamentals](chapter:reticulum-fundamentals).\nDistribution uses announces for app discovery — [Publish & install](chapter:sdk-apps-publish).\n"},{"path":"chapters/sdk-apps-package/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n"},{"path":"chapters/sdk-apps-package/source.md","content":"# Packaging & preview\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`apps:package` and `apps:preview` are double-gated: the capability grant plus a\nhost-chrome confirmation the mini-app cannot dismiss. Package signs under the\ndevice publisher identity; preview runs the project in the single sandboxed\ndev-preview slot.\n\n## Deterministic packages\n\n`tp pack` and `apps.packageProject` produce deterministic `.tpkg` archives —\nsame inputs yield the same hash. That makes 256t ids stable for distribution\nand CI.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n```\n\nOnly one preview slot exists per host. Stop preview before starting another.\n\n## Live probe\n\nUse **Run applet** for the automated inline probe (package → preview → stop, used in CI).\n\nUse **Run as real app** to launch the sample in the host dev-preview slot — the full\nsandbox/grant/launch loop with host confirmation. Stop preview when finished.\n\n{{applet:apps-package-preview}}\n\nNext: [Publish & install](chapter:sdk-apps-publish). Format reference: [Package format](chapter:ref-packages).\n"},{"path":"chapters/sdk-apps-publish/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n"},{"path":"chapters/sdk-apps-publish/source.md","content":"# Publish & install\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`apps:publish` announces a packaged 256t id under the publisher identity.\n`apps:install` asks the host to fetch, verify, and review capabilities before\nanything runs. Both raise a confirmation dialog on every call.\n\n## Discover → trust → install\n\nDiscovery is announce-driven: users find a 256t id, verify the publisher signature,\ngrant capabilities, then launch. There is no central store — trust is signature-based.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n```\n\nPackage first with `apps.packageProject` — see [Packaging & preview](chapter:sdk-apps-package).\n\n## Outcomes\n\n- `pass` — publish and install succeeded with host confirmations approved.\n- `not-granted` — `apps:publish` or `apps:install` withheld.\n- `unavailable` — distribution backend not configured on this host.\n\n## Live probe\n\n{{applet:apps-publish-install}}\n\nOTA updates reuse the same APIs with a bumped semver — [Publish, install & update](chapter:sdk-apps-update).\n"},{"path":"chapters/sdk-apps-update/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nawait apps.publish(packed.t256);\nconst installed = await apps.install(packed.t256);\n"},{"path":"chapters/sdk-apps-update/sample-1.js","content":"const manifestV2 = { ...manifest, version: \"0.2.0\" };\nawait workspace.write(\"my-app/app.json\", JSON.stringify(manifestV2, null, 2));\nconst packedV2 = await apps.packageProject(\"my-app\", manifestV2);\nawait apps.publish(packedV2.t256);\nconst updated = await apps.install(packedV2.t256);\n"},{"path":"chapters/sdk-apps-update/source.md","content":"# Publish, install & update\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nDistribution is a three-step loop: **package** a signed `.tpkg`, **publish** its\n256t id under your publisher identity, and **install** on any host that discovers\nthe announce. **Update** is the same path with a bumped semver — the host fetches\nthe newer archive and replaces the installed copy.\n\n## Why confirmations exist\n\n`apps:publish` and `apps:install` are double-gated: the manifest must declare the\ncapability and the host shows a confirmation on every call. That mirrors how end\nusers experience installs outside DevStudio.\n\n## Publish & install\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nawait apps.publish(packed.t256);\nconst installed = await apps.install(packed.t256);\n```\n\nSee [Publish & install](chapter:sdk-apps-publish) for the first-install probe.\n\n## OTA update\n\nBump `version` in the manifest, repack, and publish again. Hosts that already\ninstalled the app resolve the new 256t id through Hyperdrive or Resource fallback.\n\n```javascript\nconst manifestV2 = { ...manifest, version: \"0.2.0\" };\nawait workspace.write(\"my-app/app.json\", JSON.stringify(manifestV2, null, 2));\nconst packedV2 = await apps.packageProject(\"my-app\", manifestV2);\nawait apps.publish(packedV2.t256);\nconst updated = await apps.install(packedV2.t256);\n```\n\nCLI equivalent: `tp update <app-dir> --version <semver>` — see\n[CLI commands](chapter:ref-cli).\n\n## Live probe\n\n{{applet:apps-update}}\n\nTransport budgets for large packages: [Budgets & quotas](chapter:sdk-budgets).\nPackage format: [Package format](chapter:ref-packages).\n"},{"path":"chapters/sdk-budgets/sample-0.js","content":"import { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n"},{"path":"chapters/sdk-budgets/source.md","content":"# Budgets & quotas\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nHosts enforce limits at several layers so constrained links (BLE, LoRa) and\nshared devices stay predictable. Budgets are not optional hints — exceeding them\nreturns typed errors or truncated transfers.\n\n## Resource fetch (per call)\n\n`resource:fetch` takes an explicit `budgetBytes` cap. The host pulls through\nits link strategy without exposing sockets to the sandbox.\n\n```javascript\nimport { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n```\n\n{{applet:resource-fetch}}\n\n## Package install (per transport)\n\n`conformance/budgets/measured.json` records install time at measured bitrates.\nThe BLE guidance target is ~180 KiB for under-one-minute installs; the **full**\nHandbook is ~295 KiB (~100 s at measured BLE rates) — intentionally above the\ntiny-app example budget.\n\n| Package | Size | LAN | BLE | RNode |\n|---|---|---|---|---|\n| tiny hello | < 1 KiB | ~1 s | ~1 s | ~6 s |\n| handbook (full) | ~304 KiB | ~1 s | ~100 s | ~34 min |\n| handbook-part-1-concepts | ~62 KiB | ~1 s | ~21 s | ~7 min |\n| handbook-part-2-hosts | ~76 KiB | ~1 s | ~26 s | ~9 min |\n| handbook-part-3-sdk | ~147 KiB | ~1 s | ~49 s | ~17 min |\n| handbook-part-4-diagnostics | ~61 KiB | ~1 s | ~21 s | ~7 min |\n| handbook-part-5-reference | ~114 KiB | ~1 s | ~38 s | ~13 min |\n\n**Per-part packages** (`handbook-part-1-concepts`, …) are built alongside the\nfull Handbook (`npm run build:handbook` → `generated/part-packages/`). Install\none part at a time when BLE bandwidth is tight.\n\n## Host & workspace quotas\n\nNode seeding, propagation store, bandwidth caps, workspace file limits, widget\ntree size, and AI message caps are listed in [Quotas & limits](chapter:ref-quotas).\nOverride desktop/node defaults in `<data-dir>/config.json` — see\n[Host configuration](chapter:ref-host-config).\n"},{"path":"chapters/sdk-capabilities/sample-0.json","content":"{\n  \"capabilities\": [\n    \"identity\",\n    \"storage:kv\",\n    \"workspace\"\n  ]\n}\n"},{"path":"chapters/sdk-capabilities/sample-1.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\ntry {\n  await identity.destinationHash();\n} catch (error) {\n  if (error?.code === \"CAPABILITY_DENIED\") {\n    // Explain what identity would allow; offer to open Settings\n  }\n}\n"},{"path":"chapters/sdk-capabilities/source.md","content":"# Capability model\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nMini-apps declare every SDK surface they may use in `app.manifest.json`. At\ninstall the host shows the full list; the user may grant a **subset**. The\nbroker enforces grants on every call — withheld capabilities are not errors in\nthe Handbook, they become `not-granted` teaching cards.\n\n## Manifest\n\n```json\n{\n  \"capabilities\": [\n    \"identity\",\n    \"storage:kv\",\n    \"workspace\"\n  ]\n}\n```\n\nOnly ids from `CAPABILITY_DEFINITIONS` are valid. The reference list is\ngenerated at build time: [Capabilities](chapter:ref-capabilities).\n\n## Typed errors\n\nThe runtime throws `CapabilityError` with a stable `code`:\n\n| Code | Meaning |\n|---|---|\n| `UNKNOWN_CAPABILITY` | Manifest names a capability the host does not recognize |\n| `UNDECLARED_CAPABILITY` | Code calls a capability not listed in the manifest |\n| `CAPABILITY_DENIED` | Manifest lists it but the user withheld the grant |\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\ntry {\n  await identity.destinationHash();\n} catch (error) {\n  if (error?.code === \"CAPABILITY_DENIED\") {\n    // Explain what identity would allow; offer to open Settings\n  }\n}\n```\n\n## Live probe\n\nWithhold `identity` at install (or tap **Revoke** in host settings) and re-run\nthe applet — it reports `not-granted` instead of throwing into your UI.\n\n{{applet:identity-hash}}\n\nDouble-gated capabilities (`apps:package`, `apps:publish`, `apps:install`,\n`apps:preview`) also require a host-chrome confirmation the sandbox cannot\ndismiss. See [Packaging & preview](chapter:sdk-apps-package).\n"},{"path":"chapters/sdk-devstudio/source.md","content":"# DevStudio walkthrough\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nDevStudio is a mini-app IDE — same sandbox and\ncapability model as any other app. Desktop first-boot seeds it alongside this\nHandbook.\n\n## Development loop\n\n1. **New project** — DevStudio seeds `hello-app/app.json` + `bundle.js` in the\n   app workspace.\n2. **Edit** — the `code-editor` widget is content-by-reference: the tree carries\n   a `documentId`; edits flow back as events and persist with `workspace.write`.\n3. **AI assist** — with `ai:chat` granted, describe a change; the host holds the\n   API key and model (never in the sandbox). Review whole-file proposals before\n   **Apply**.\n4. **Preview** — `apps:preview` runs the project in the single dev-preview slot\n   while DevStudio keeps running.\n5. **Package & sign** — host confirmation; deterministic `.tpkg` under the\n   device publisher identity; 256t id + QR.\n6. **Publish** — host confirmation; seed on Hyperdrive and announce the locator.\n\n## Open in DevStudio from the Handbook\n\nEvery applet card includes **Open in DevStudio**. The Handbook exports the\napplet source plus a `tp.devstudio.workspace.v1` handoff via `share:cas`; paste\nor scan the QR in DevStudio to import the sample as a starting project.\n\nTry it on the identity probe below, then continue in DevStudio with\n[Packaging & preview](chapter:sdk-apps-package).\n\n{{applet:identity-hash}}\n"},{"path":"chapters/sdk-identity/sample-0.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n"},{"path":"chapters/sdk-identity/source.md","content":"# Identity & signing\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe `identity` capability grants an app-scoped destination and brokered signing.\nPrivate keys never enter the sandbox — the host derives an app destination from the\ndevice identity plus app id and performs crypto on the broker.\n\n## Why app-scoped destinations\n\nPublisher trust and app addressing share one root: the Reticulum keypair. Mini-apps\nnever see private key material; they receive hashes and signatures only.\n\n## API\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n```\n\n`destinationHash` is stable for a given install. `sign` accepts raw bytes and returns\na signature verifiable against the app destination.\n\n## Outcomes\n\n- `pass` — hash and signing path work on this host.\n- `not-granted` — identity capability withheld at install.\n\n## Live probe\n\nThe applet below calls `identity.destinationHash()` on this host and reports\npass / fail / not-granted.\n\n{{applet:identity-hash}}\n\nUse **Open in DevStudio** on any applet to copy the sample into a DevStudio\nproject via `share:cas`. Concept overview: [Concepts in practice](chapter:concepts-in-practice).\n"},{"path":"chapters/sdk-lxmf/sample-0.js","content":"import { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n"},{"path":"chapters/sdk-lxmf/source.md","content":"# LXMF messaging\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nLXMF is store-and-forward messaging on top of Reticulum. Mini-apps use it for\napp-to-app mailboxes without holding private keys — the host signs and decrypts on\nbehalf of the app destination.\n\n## When to use LXMF\n\nUse LXMF when you need asynchronous messages between app destinations: chat,\nnotifications, or command/response patterns that tolerate delay. For bulk binary\npayloads, use [Resource fetch](chapter:sdk-resource-fetch) instead.\n\n## Capabilities\n\n- `lxmf:send` — enqueue an outbound message from this app’s destination.\n- `lxmf:receive` — read deliveries addressed to this app.\n\nWithholding either capability turns the probe below into a `not-granted` card.\n\n## API\n\n```javascript\nimport { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n```\n\nMessages are namespaced to the app id. The host never exposes the device private key.\n\n## Common outcomes\n\n- `pass` — round-trip to self succeeded on this host.\n- `unavailable` — LXMF path not configured (leaf without gateway, etc.).\n- `not-granted` — send or receive capability withheld at install.\n\n## Live probe\n\n{{applet:lxmf-roundtrip}}\n\nSee also [Identity & signing](chapter:sdk-identity) and [Announce & subscribe](chapter:sdk-announce).\n"},{"path":"chapters/sdk-presence/sample-0.js","content":"import { presence } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { peers, preferredInterface, ... }\n"},{"path":"chapters/sdk-presence/source.md","content":"# Presence\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`presence` exposes coarse peer and interface state: how many peers are visible, which\ninterface is preferred, and whether the host considers itself online. It complements\n`host.info()` for the [live difference matrix](chapter:difference-matrix).\n\n## What presence is not\n\nPresence is not a full routing table. It is a snapshot for UI and diagnostics — enough\nto tell whether BLE, TCP, or WebSocket paths look healthy on **this** host.\n\n## API\n\n```javascript\nimport { presence } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { peers, preferredInterface, ... }\n```\n\nGrant `presence` at install. Without it, host info and presence probes become\n`not-granted` teaching cards.\n\n## Reading results\n\n- `peers === 0` on a phone may be normal in CI; on LAN with a second peer it often\n  indicates discovery still warming up.\n- Compare with `host.info().interfaceTypes` — an interface can be listed but offline.\n\n## Live probe\n\n{{applet:presence-snapshot}}\n\nSee also the [live difference matrix](chapter:difference-matrix) (`host.info` applet).\n"},{"path":"chapters/sdk-resource-fetch/sample-0.js","content":"import { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n"},{"path":"chapters/sdk-resource-fetch/source.md","content":"# Resource fetch\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`resource:fetch` asks the host to pull a Resource through its budget rules.\nThe mini-app never sees sockets or peer handles — only bytes (or a typed error).\n\nResources are the Reticulum bulk path when Hyperswarm is unavailable. Budgets\nvary by link type — see [Budgets & quotas](chapter:sdk-budgets).\n\n## API\n\n```javascript\nimport { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n```\n\nExceeding `budgetBytes` fails before transfer starts. The host enforces per-link\ncaps documented in [Known limitations](chapter:ref-limitations) §6.\n\n## Outcomes\n\n- `pass` — fetch completed within budget.\n- `unavailable` — no resource server or peer path on this host.\n- `not-granted` — `resource:fetch` withheld.\n\n## Live probe\n\n{{applet:resource-fetch}}\n"},{"path":"chapters/sdk-share-cas/sample-0.js","content":"import { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n"},{"path":"chapters/sdk-share-cas/source.md","content":"# Content-addressed share\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`share:cas` stores a bounded string and returns a 94-character 256t id.\nPaste or scan that id on another device to `share.get` the same bytes —\ndiagnostics reports and DevStudio hand-offs use this path.\n\n## Why CAS for reports\n\nDiagnostic JSON can be large. `share.put` returns a stable id suitable for QR\ncodes on the Diagnostics screen. Compare report pastes that id to diff against\nanother host.\n\n## API\n\n```javascript\nimport { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n```\n\nPayload size is capped by the host quota snapshot in `host.info()`.\n\n## Outcomes\n\n- `pass` — put/get round-trip matched.\n- `not-granted` — `share:cas` withheld.\n\n## Live probe\n\n{{applet:share-cas}}\n\nUsed by [Running diagnostics](chapter:running-diagnostics) export and **Open in DevStudio**.\n"},{"path":"chapters/sdk-storage-hyperbee/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n"},{"path":"chapters/sdk-storage-hyperbee/source.md","content":"# Hyperbee storage\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee)\nnamespaced to the app. Keys stay sorted so list ranges are useful for feeds\nand indexes.\n\n## KV vs Hyperbee\n\n| Store | Best for |\n|---|---|\n| KV | Small opaque blobs, settings |\n| Hyperbee | Sorted keys, pagination, indexes |\n\nBoth are local to the app install and quota-enforced by the host. Hyperbee data\ndoes not sync to other devices unless your app implements its own exchange.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n```\n\n## Outcomes\n\n- `pass` — put/get/list/delete round-trip succeeded.\n- `not-granted` — `storage:hyperbee` withheld.\n\n## Live probe\n\n{{applet:storage-hyperbee}}\n\nSee also [Key/value storage](chapter:sdk-storage-kv).\n"},{"path":"chapters/sdk-storage-kv/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n"},{"path":"chapters/sdk-storage-kv/source.md","content":"# Key/value storage\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\n`storage:kv` is a per-app local store with a byte quota enforced by the host. Values\nare opaque byte arrays — encode JSON or UTF-8 in the sandbox before writing.\n\n## When to use KV\n\nUse KV for small persistent state: settings, last-read positions, cached tokens.\nFor ordered iteration or large datasets, prefer [Hyperbee storage](chapter:sdk-storage-hyperbee).\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n```\n\nThe Handbook persists reading position and seed version in KV.\n\n## Outcomes\n\n- `pass` — round-trip write/read/delete succeeded.\n- `not-granted` — `storage:kv` withheld.\n\n## Live probe\n\n{{applet:storage-kv}}\n\nQuotas: [Quotas & limits](chapter:ref-quotas).\n"},{"path":"chapters/sdk-widget-gallery/source.md","content":"# Widget gallery\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nThe widget protocol is the cross-platform UI seam. Allowed components:\n`view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`,\n`progress`, `divider`, `spacer`, `code-editor`, `qr-code`.\n\nHosts on Android, iOS, desktop, and web render the same declarative tree —\nmini-apps do not ship native UI code.\n\n## Content-by-reference\n\n`code-editor` loads workspace files by `documentId`; `qr-code` accepts up to\n512 characters (94-char 256t ids fit). The host rejects unknown props, styles,\nduplicate ids, and oversized trees.\n\n## Component roles\n\n- **Layout** — `view`, `scroll`, `spacer`, `divider`\n- **Input** — `button`, `text-input`, `switch`\n- **Display** — `text`, `image`, `progress`, `list`, `qr-code`\n- **Docs** — `code-editor` for samples and applet sources\n\nSchema reference: [Widget protocol](chapter:ref-widgets).\n\n## Live probe\n\nThe applet submits a tree that includes every component type. After it reports,\nthe Handbook re-renders this chapter with the result card.\n\n{{applet:widget-gallery}}\n"},{"path":"chapters/sdk-workspace/sample-0.js","content":"import { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nawait workspace.patch(\"src/main.js\", text.length, [{ start: 0, end: 0, text: \"// edited\\n\" }]);\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n"},{"path":"chapters/sdk-workspace/source.md","content":"# Workspace\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-21\nregister: none\n-->\n\n`workspace` is a private per-app project filesystem of relative paths\n(strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this\nHandbook use it for sources and applet seeds.\n\n## Content-by-reference\n\nLarge chapter text and applet sources live in workspace files. Widget trees\nreference them via `code-editor` `documentId` — keeping render payloads under\nthe byte budget.\n\n## API\n\n```javascript\nimport { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nawait workspace.patch(\"src/main.js\", text.length, [{ start: 0, end: 0, text: \"// edited\\n\" }]);\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n```\n\nPaths are relative; traversal outside the app root is rejected. Patch offsets are UTF-16\nstring indexes. Edits must be ordered and non-overlapping; a stale base length is rejected.\n\n## Outcomes\n\n- `pass` — write/read/list/remove succeeded.\n- `not-granted` — `workspace` withheld.\n\n## Live probe\n\n{{applet:workspace-rw}}\n\nPackaging reads workspace projects — [Packaging & preview](chapter:sdk-apps-package).\n"},{"path":"chapters/what-is-twistedpear/source.md","content":"# What TwistedPear is\n\n\n<!-- tp-doc\nlifecycle: live\naudited: 2026-07-10\nregister: none\n-->\n\nTwistedPear is a peer-to-peer app platform. A **host** on each device is a full\nReticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the\nhost only through the SDK.\n\n## Two planes\n\n- **Control plane** — Reticulum handles identity, announces, links, LXMF, and\n  off-grid Resource transfer.\n- **Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package\n  syncs when IP connectivity exists. [Pears bulk plane](chapter:pears-bulk-plane).\n\n## Trust model\n\nPublisher identity **is** network identity. Packages are Ed25519-signed with the\ndeveloper's Reticulum key, so discovering an app and trusting its author use the\nsame root.\n\n## This Handbook\n\nThis document is itself a mini-app. If it installed and rendered on *this* host,\nyou have already exercised packaging, install, sandbox, broker, and the widget\nrenderer. Chapters later add interactive applets that probe live capabilities.\n\nOpen **Diagnostics** from the table of contents to run every probe, export a\nreport, or compare against another device. Reference pages in Part V are\ngenerated from the same runtime sources the host uses. Host-specific behavior:\n[Part II — The hosts](chapter:host-desktop).\n"}]};
import {
  ai,
  apps,
  announce,
  host,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

// Handbook runtime — TOC, chapter renderer, inline applet runner, diagnostics.
// CATALOG is injected by build.mjs immediately above this file in bundle.js.

const POSITION_KEY = "handbook:position";
const SCROLL_KEY_PREFIX = "handbook:scroll:";
const SEEDED_KEY = "handbook:seeded";
const SEED_VERSION_KEY = "handbook:seed-version";
const GRANT_INTRO_KEY = "handbook:grant-intro-seen";
const LAST_REPORT_KEY = "handbook:last-report";
const REPORT_SCHEMA_VERSION = 1;
const DEVSTUDIO_HANDOFF_KIND = "tp.devstudio.workspace.v1";

const DIAGNOSTIC_GROUP_ORDER = ["crypto", "interfaces", "storage", "distribution", "runtime"];
const DIAGNOSTIC_GROUP_LABELS = {
  crypto: "Crypto & messaging",
  interfaces: "Interfaces & presence",
  storage: "Storage & workspace",
  distribution: "Distribution & fetch",
  runtime: "Runtime & UI"
};

/** @type {"toc" | "chapter" | "diagnostics" | "grant-intro"} */
let view = "toc";
/** @type {string | null} */
let chapterId = null;
/** @type {Record<string, { status: string, details: string, timings?: { ms: number } }>} */
let appletResults = {};
/** @type {string | null} */
let statusLine = null;
/** @type {boolean} */
let seeding = false;
/** @type {boolean} */
let runningAll = false;
/** @type {{ reportId: string | null, generatedAt: string | null, json: string | null }} */
let exportState = { reportId: null, generatedAt: null, json: null };
/** @type {string} */
let compareInput = "";
/** @type {string} */
let searchQuery = "";
/** @type {number} */
let chapterScrollOffset = 0;
/** @type {number | null} */
let scrollSaveTimer = null;
/** @type {{ local: object | null, remote: object | null, rows: Array<object>, error: string | null }} */
let compareState = { local: null, remote: null, rows: [], error: null };
/** @type {Record<string, { t256: string, project: string }>} */
let devstudioHandoffs = {};
/** @type {boolean} */
let previewRunning = false;
/** @type {string | null} */
let previewAppletId = null;

function appletSupportsMode(applet, mode) {
  const modes = applet.executionModes ?? ["inline"];
  return modes.includes(mode);
}

function makeSdk() {
  return {
    identity,
    presence,
    host,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps,
    ai
  };
}

function findChapter(id) {
  return CATALOG.chapters.find((chapter) => chapter.id === id) ?? null;
}

function findApplet(id) {
  return CATALOG.applets.find((applet) => applet.id === id) ?? null;
}

function chapterNavigationOrder() {
  const order = [];
  for (const part of CATALOG.parts) {
    for (const chapter of part.chapters) {
      order.push(chapter.id);
    }
  }
  return order;
}

function chapterNeighbors(id) {
  const order = chapterNavigationOrder();
  const index = order.indexOf(id);
  if (index < 0) {
    return { prev: null, next: null };
  }
  return {
    prev: index > 0 ? order[index - 1] : null,
    next: index < order.length - 1 ? order[index + 1] : null
  };
}

function chapterMatchesSearch(chapterMeta, query) {
  if (query.length === 0) {
    return true;
  }
  const chapter = findChapter(chapterMeta.id);
  const haystack = `${chapterMeta.title} ${chapter?.searchText ?? ""}`.toLowerCase();
  return haystack.includes(query);
}

async function kvGetText(key) {
  const bytes = await storage.kv.get(key);
  if (bytes === null) {
    return null;
  }
  return new TextDecoder().decode(bytes);
}

async function kvSetText(key, value) {
  await storage.kv.set(key, new TextEncoder().encode(value));
}

async function ensureSeeds() {
  const version = await kvGetText(SEED_VERSION_KEY);
  const seeded = await kvGetText(SEEDED_KEY);
  if (seeded === "1" && version === CATALOG.version) {
    return;
  }

  seeding = true;
  try {
    for (const seed of CATALOG.seeds) {
      await workspace.write(seed.path, seed.content);
    }
    await kvSetText(SEEDED_KEY, "1");
    await kvSetText(SEED_VERSION_KEY, CATALOG.version);
  } finally {
    seeding = false;
  }
}

function widgetButton(id, label, event) {
  return { id, type: "button", props: { label, event } };
}

function textNode(id, value, style) {
  const node = { id, type: "text", props: { value } };
  if (style !== undefined) {
    node.style = style;
  }
  return node;
}

function headingStyle(level) {
  if (level === 1) {
    return { fontSize: 24, fontWeight: "bold" };
  }
  if (level === 2) {
    return { fontSize: 20, fontWeight: "bold" };
  }
  return { fontSize: 16, fontWeight: "bold" };
}

function resultCard(appletId, result) {
  if (result === undefined) {
    return textNode(`result-${appletId}-empty`, "Not run yet.");
  }

  const label = result.status.toUpperCase();
  const timing =
    result.timings && typeof result.timings.ms === "number" ? ` (${result.timings.ms} ms)` : "";
  const procedureMatch =
    typeof result.details === "string"
      ? result.details.match(/(?:Guided procedure[^:]*:\n)([\s\S]+)$/)
      : null;
  const body =
    procedureMatch !== null && (result.status === "unavailable" || result.status === "skipped")
      ? `${label}${timing}\n\nGuided procedure:\n${procedureMatch[1].trim()}`
      : `${label}${timing}\n${result.details}`;
  return textNode(`result-${appletId}`, body);
}

function explainStatus(status) {
  if (status === "not-granted") {
    return "This capability was withheld for this app. Grant it at install to run the probe.";
  }
  if (status === "unavailable") {
    return "This host does not implement the feature; that is an expected platform difference.";
  }
  if (status === "skipped") {
    return "Skipped.";
  }
  return null;
}

function renderTableBlock(bid, block, children) {
  children.push(
    textNode(`${bid}-header`, block.headers.join(" · "), { fontWeight: "bold" })
  );
  const items = block.rows.map((row) => row.join(" — "));
  children.push({
    id: `${bid}-rows`,
    type: "list",
    props: { items }
  });
}

async function renderGrantIntro(children) {
  children.push(
    textNode("grant-intro-title", "Capabilities at install", { fontSize: 20, fontWeight: "bold" })
  );
  children.push(
    textNode(
      "grant-intro-blurb",
      "The Handbook requested the capabilities below. You may grant a subset at install — withheld capabilities turn matching applets into not-granted teaching cards instead of errors."
    )
  );

  /** @type {Set<string>} */
  let granted = new Set();
  try {
    const info = await host.info();
    if (Array.isArray(info.grantedCapabilities)) {
      granted = new Set(info.grantedCapabilities);
    }
  } catch {
    // presence withheld — list manifest capabilities without live grant status
  }

  const caps = CATALOG.manifestCapabilities ?? [];
  for (let i = 0; i < caps.length; i += 1) {
    const cap = caps[i];
    const status =
      granted.size === 0
        ? ""
        : granted.has(cap.id)
          ? " ✓ granted"
          : " ✗ withheld";
    children.push(textNode(`grant-cap-${i}`, `• ${cap.id} — ${cap.description}${status}`));
  }

  children.push(
    textNode(
      "grant-intro-note",
      "Revoke or add grants later in host Settings. Double-gated apps:* capabilities also require a host confirmation on each call."
    )
  );
  children.push(
    widgetButton("grant-intro-continue", "Continue to Handbook", "hb.grantintro.dismiss")
  );
}

function appletsByDiagnosticGroup() {
  /** @type {Record<string, typeof CATALOG.applets>} */
  const grouped = {};
  for (const group of DIAGNOSTIC_GROUP_ORDER) {
    grouped[group] = [];
  }
  for (const applet of CATALOG.applets) {
    const group = applet.group ?? "runtime";
    if (grouped[group] === undefined) {
      grouped[group] = [];
    }
    grouped[group].push(applet);
  }
  return grouped;
}

function renderAppletBlock(appletId, children) {
  const applet = findApplet(appletId);
  if (applet === null) {
    children.push(textNode(`missing-${appletId}`, `Missing applet: ${appletId}`));
    return;
  }

  children.push({ id: `applet-sep-${appletId}`, type: "divider" });
  children.push(
    textNode(`applet-title-${appletId}`, `Applet: ${applet.title}`, {
      fontSize: 16,
      fontWeight: "bold"
    })
  );
  children.push(
    textNode(
      `applet-caps-${appletId}`,
      `Requires: ${applet.capabilities.join(", ")}`
    )
  );
  children.push({
    id: `applet-src-${appletId}`,
    type: "code-editor",
    props: {
      documentId: `applets/${appletId}/main.js`,
      language: "javascript",
      readOnly: true
    }
  });
  children.push(
    widgetButton(`applet-run-${appletId}`, "Run applet", "hb.runapplet")
  );
  if (appletSupportsMode(applet, "preview") && applet.preview !== null) {
    children.push(
      widgetButton(`applet-preview-${appletId}`, "Run as real app", "hb.runpreview")
    );
    if (previewRunning && previewAppletId === appletId) {
      children.push(
        widgetButton(`applet-stoppreview-${appletId}`, "Stop preview", "hb.stoppreview")
      );
      children.push(
        textNode(
          `applet-preview-active-${appletId}`,
          "Preview is running in the host dev-preview slot. Stop preview to return here."
        )
      );
    }
  }
  children.push(
    widgetButton(`applet-devstudio-${appletId}`, "Open in DevStudio", "hb.devstudio")
  );

  const handoff = devstudioHandoffs[appletId];
  if (handoff !== undefined) {
    children.push(
      textNode(
        `applet-devstudio-meta-${appletId}`,
        `DevStudio handoff: ${handoff.project}\nPaste in DevStudio → Import from 256t`
      )
    );
    children.push({
      id: `applet-devstudio-qr-${appletId}`,
      type: "qr-code",
      props: {
        value: handoff.t256,
        caption: handoff.project,
        size: 96
      }
    });
  }

  const result = appletResults[appletId];
  children.push(resultCard(appletId, result));
  if (result !== undefined) {
    const explanation = explainStatus(result.status);
    if (explanation !== null) {
      children.push(textNode(`applet-explain-${appletId}`, explanation));
    }
  }
}

function renderChapterBlocks(chapter, children) {
  let blockIndex = 0;
  for (const block of chapter.blocks) {
    const bid = `${chapter.id}-b${blockIndex++}`;
    if (block.type === "heading") {
      children.push(textNode(bid, block.text, headingStyle(block.level)));
      continue;
    }
    if (block.type === "paragraph") {
      children.push(textNode(bid, block.text));
      continue;
    }
    if (block.type === "list") {
      for (let i = 0; i < block.items.length; i += 1) {
        children.push(textNode(`${bid}-i${i}`, `• ${block.items[i]}`));
      }
      continue;
    }
    if (block.type === "table") {
      renderTableBlock(bid, block, children);
      continue;
    }
    if (block.type === "code") {
      children.push({
        id: bid,
        type: "code-editor",
        props: {
          documentId: block.documentId,
          language: block.language,
          readOnly: true
        }
      });
      continue;
    }
    if (block.type === "chapter-link") {
      children.push(
        widgetButton(`link-${block.chapterId}-${bid}`, `→ ${block.label}`, "hb.openchapter")
      );
      continue;
    }
    if (block.type === "applet") {
      renderAppletBlock(block.appletId, children);
    }
  }
}

async function fetchHostInfoSafe() {
  try {
    return await host.info();
  } catch (error) {
    return {
      platform: "unknown",
      hostVersion: "unknown",
      hostApiVersion: "unknown",
      roles: { transport: false, seeder: false, propagation: false },
      interfaceTypes: [],
      quotas: {
        kvQuotaBytes: null,
        seedStorageUsedBytes: null,
        seedStorageQuotaBytes: null,
        memoryBytes: null
      },
      error: error instanceof Error ? error.message : String(error)
    };
  }
}

function buildReportDocument(hostInfo) {
  const results = CATALOG.applets.map((applet) => {
    const result = appletResults[applet.id];
    const row =
      result === undefined
        ? {
            appletId: applet.id,
            status: "skipped",
            details: "Not run",
            timings: { ms: 0 }
          }
        : {
            appletId: applet.id,
            status: result.status,
            details: result.details,
            timings: result.timings ?? { ms: 0 }
          };
    return {
      ...row,
      expectations: applet.expectations ?? {}
    };
  });

  return {
    schemaVersion: REPORT_SCHEMA_VERSION,
    handbookVersion: CATALOG.version,
    generatedAt: new Date().toISOString(),
    host: hostInfo,
    results
  };
}

function diffReports(localReport, remoteReport) {
  const remoteById = new Map(
    (remoteReport.results ?? []).map((row) => [row.appletId, row])
  );
  const localPlatform = localReport.host?.platform ?? "unknown";
  const remotePlatform = remoteReport.host?.platform ?? "unknown";
  const rows = [];
  for (const local of localReport.results ?? []) {
    const remote = remoteById.get(local.appletId);
    const applet = findApplet(local.appletId);
    const localExpected =
      local.expectations?.[localPlatform] ?? applet?.expectations?.[localPlatform] ?? null;
    const remoteExpected =
      remote?.expectations?.[remotePlatform] ?? applet?.expectations?.[remotePlatform] ?? null;
    const remoteStatus = remote?.status ?? "missing";
    const same = remote !== undefined && remote.status === local.status;
    const expectedDiff =
      localExpected !== null &&
      remoteExpected !== null &&
      localExpected !== remoteExpected;
    const unexpected = !same && !expectedDiff;
    let note = "";
    if (expectedDiff) {
      note = `expected ${localExpected} vs ${remoteExpected}`;
    } else if (unexpected) {
      note = "unexpected difference";
    } else if (same) {
      note = "same status";
    }
    rows.push({
      appletId: local.appletId,
      local: local.status,
      remote: remoteStatus,
      same,
      expectedDiff,
      unexpected,
      note,
      localExpected,
      remoteExpected
    });
  }
  return rows;
}

function renderDiagnostics(children) {
  children.push(widgetButton("back-toc-diag", "← Contents", "hb.toc"));
  children.push({ id: "diag-sep", type: "divider" });
  children.push(textNode("diag-title", "Diagnostics", { fontSize: 20, fontWeight: "bold" }));
  children.push(
    textNode(
      "diag-blurb",
      "Run every applet on this host, export a shareable report, or paste another report’s 256t id to compare."
    )
  );

  children.push(
    widgetButton(
      "diag-run-all",
      runningAll ? "Running all…" : "Run all diagnostics",
      "hb.runall"
    )
  );

  const counts = { pass: 0, fail: 0, unavailable: 0, "not-granted": 0, skipped: 0 };
  const grouped = appletsByDiagnosticGroup();
  for (const group of DIAGNOSTIC_GROUP_ORDER) {
    const applets = grouped[group];
    if (applets === undefined || applets.length === 0) {
      continue;
    }
    children.push(
      textNode(
        `diag-group-${group}`,
        DIAGNOSTIC_GROUP_LABELS[group] ?? group,
        { fontSize: 14, fontWeight: "bold" }
      )
    );
    for (const applet of applets) {
      const result = appletResults[applet.id];
      const status = result?.status ?? "skipped";
      if (counts[status] !== undefined) {
        counts[status] += 1;
      }
      children.push(
        textNode(
          `diag-row-${applet.id}`,
          `  ${applet.id}: ${status.toUpperCase()}`
        )
      );
    }
  }
  children.push(
    textNode(
      "diag-summary",
      `Summary — pass ${counts.pass}, fail ${counts.fail}, unavailable ${counts.unavailable}, not-granted ${counts["not-granted"]}, skipped ${counts.skipped}`
    )
  );

  children.push({ id: "diag-export-sep", type: "divider" });
  children.push(widgetButton("diag-export", "Export report (share.put)", "hb.export"));
  if (exportState.reportId !== null) {
    children.push(
      textNode(
        "diag-export-meta",
        `Exported ${exportState.generatedAt ?? ""}\n${exportState.reportId}`
      )
    );
    children.push({
      id: "diag-export-qr",
      type: "qr-code",
      props: {
        value: exportState.reportId,
        caption: "Scan or copy report 256t id"
      }
    });
  }

  children.push({ id: "diag-compare-sep", type: "divider" });
  children.push(textNode("diag-compare-label", "Compare with remote report id:"));
  children.push({
    id: "diag-compare-input",
    type: "text-input",
    props: {
      value: compareInput,
      placeholder: "Paste 256t id",
      event: "hb.compare.input"
    }
  });
  children.push(widgetButton("diag-compare", "Compare report", "hb.compare"));

  if (compareState.error !== null) {
    children.push(textNode("diag-compare-error", compareState.error));
  }
  if (compareState.rows.length > 0) {
    const localPlat = compareState.local?.host?.platform ?? "?";
    const remotePlat = compareState.remote?.host?.platform ?? "?";
    children.push(
      textNode(
        "diag-compare-hosts",
        `Local host: ${localPlat}  ·  Remote host: ${remotePlat}`
      )
    );
    const grouped = appletsByDiagnosticGroup();
    for (const group of DIAGNOSTIC_GROUP_ORDER) {
      const applets = grouped[group];
      if (applets === undefined || applets.length === 0) {
        continue;
      }
      const groupRows = compareState.rows.filter((row) =>
        applets.some((applet) => applet.id === row.appletId)
      );
      if (groupRows.length === 0) {
        continue;
      }
      children.push(
        textNode(
          `diag-compare-group-${group}`,
          DIAGNOSTIC_GROUP_LABELS[group] ?? group,
          { fontSize: 14, fontWeight: "bold" }
        )
      );
      for (const row of groupRows) {
        const mark = row.expectedDiff ? "≈" : row.same ? "=" : "≠";
        const expectNote =
          row.localExpected !== null && row.remoteExpected !== null
            ? ` [exp ${row.localExpected}/${row.remoteExpected}]`
            : "";
        children.push(
          textNode(
            `diag-diff-${row.appletId}`,
            `  ${mark} ${row.appletId}: ${row.local} / ${row.remote}${expectNote}${row.note ? ` — ${row.note}` : ""}`
          )
        );
      }
    }
  }
}

async function render() {
  const children = [
    textNode("brand", CATALOG.title, { fontSize: 24, fontWeight: "bold" })
  ];

  if (statusLine !== null) {
    children.push(textNode("status", statusLine));
  }

  if (seeding) {
    children.push(textNode("seeding", "Seeding documentation workspace…"));
  }

  if (view === "grant-intro") {
    await renderGrantIntro(children);
  } else if (view === "toc") {
    children.push(textNode("toc-heading", "Contents", { fontSize: 20, fontWeight: "bold" }));
    children.push(
      textNode(
        "toc-blurb",
        "Interactive diagnostic documentation. Open a chapter, then run embedded applets on this host."
      )
    );
    children.push(widgetButton("open-diag", "Diagnostics · run all / export / compare", "hb.diagnostics"));
    children.push({
      id: "toc-search",
      type: "text-input",
      props: {
        value: searchQuery,
        placeholder: "Search chapters…",
        event: "hb.search"
      }
    });

    const query = searchQuery.trim().toLowerCase();
    let visibleCount = 0;

    for (const part of CATALOG.parts) {
      const visibleChapters = part.chapters.filter((chapter) => chapterMatchesSearch(chapter, query));
      if (visibleChapters.length === 0) {
        continue;
      }
      visibleCount += visibleChapters.length;
      children.push({ id: `part-sep-${part.id}`, type: "divider" });
      children.push(textNode(`part-${part.id}`, part.title, { fontSize: 16, fontWeight: "bold" }));
      for (const chapter of visibleChapters) {
        const marker = chapterId === chapter.id ? "▶ " : "";
        children.push(
          widgetButton(`ch-${chapter.id}`, `${marker}${chapter.title}`, "hb.openchapter")
        );
      }
    }
    if (query.length > 0) {
      children.push(
        textNode(
          "toc-search-meta",
          visibleCount === 0 ? "No chapters match your search." : `${visibleCount} chapter(s) match.`
        )
      );
    }
  } else if (view === "diagnostics") {
    renderDiagnostics(children);
  } else if (view === "chapter") {
    const chapter = findChapter(chapterId);
    children.push(widgetButton("back-toc", "← Contents", "hb.toc"));
    children.push({ id: "chapter-sep", type: "divider" });

    if (chapter === null) {
      children.push(textNode("missing-chapter", `Chapter not found: ${chapterId}`));
    } else {
      children.push(
        textNode("chapter-part", chapter.partTitle, { fontSize: 12, fontWeight: "medium" })
      );
      children.push(
        textNode("chapter-title", chapter.title, { fontSize: 20, fontWeight: "bold" })
      );
      renderChapterBlocks(chapter, children);
      const { prev, next } = chapterNeighbors(chapter.id);
      children.push({ id: "chapter-nav-sep", type: "divider" });
      if (prev !== null) {
        const prevChapter = findChapter(prev);
        children.push(
          widgetButton(
            `ch-${prev}`,
            `← ${prevChapter?.title ?? prev}`,
            "hb.openchapter"
          )
        );
      }
      if (next !== null) {
        const nextChapter = findChapter(next);
        children.push(
          widgetButton(
            `ch-${next}`,
            `${nextChapter?.title ?? next} →`,
            "hb.openchapter"
          )
        );
      }
    }
  }

  await ui.render({
    root: {
      id: "root",
      type: "scroll",
      props: {
        scrollOffset: view === "chapter" ? chapterScrollOffset : 0,
        event: "hb.scroll"
      },
      style: { padding: 16, gap: 8 },
      children: [
        {
          id: "inner",
          type: "view",
          style: { gap: 8 },
          children
        }
      ]
    }
  });
}

async function loadChapterScroll(id) {
  const raw = await kvGetText(`${SCROLL_KEY_PREFIX}${id}`);
  const parsed = raw === null ? 0 : Number.parseInt(raw, 10);
  chapterScrollOffset = Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
}

function scheduleScrollSave(id, y) {
  if (scrollSaveTimer !== null) {
    clearTimeout(scrollSaveTimer);
  }
  scrollSaveTimer = setTimeout(() => {
    scrollSaveTimer = null;
    void kvSetText(`${SCROLL_KEY_PREFIX}${id}`, String(Math.max(0, Math.round(y))));
  }, 250);
}

async function openChapter(id) {
  if (findChapter(id) === null) {
    statusLine = `Unknown chapter: ${id}`;
    await render();
    return;
  }

  chapterId = id;
  view = "chapter";
  statusLine = null;
  await kvSetText(POSITION_KEY, id);
  await loadChapterScroll(id);
  await render();
}

async function dismissGrantIntro() {
  await kvSetText(GRANT_INTRO_KEY, "1");
  view = "toc";
  statusLine = null;
  await render();
}

async function openToc() {
  view = "toc";
  statusLine = null;
  await render();
}

async function openDiagnostics() {
  view = "diagnostics";
  statusLine = null;
  await render();
}

function stripAppletExports(source) {
  return source
    .replace(/export\s+async\s+function\s+run\s*/, "async function run ")
    .replace(/export\s+\{[^}]+\}\s*;?/g, "");
}

/**
 * Load applet `run(sdk, report)`. Prefer AsyncFunction (Node sandbox). Fall back
 * to blob-URL import when CSP blocks eval (browser iframe worker has no
 * unsafe-eval).
 */
async function loadAppletRunner(source) {
  const body = stripAppletExports(source);
  try {
    const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
    // Probe — some CSPs allow constructing Function but reject calling it.
    const probe = new AsyncFunction("return 1");
    await probe();
    return new AsyncFunction("sdk", "report", `${body}\nawait run(sdk, report);`);
  } catch {
    const moduleSource = `${body}\nexport async function __handbookRun(sdk, report) {\n  await run(sdk, report);\n}\n`;
    const moduleUrl = URL.createObjectURL(new Blob([moduleSource], { type: "text/javascript" }));
    try {
      const mod = await import(moduleUrl);
      if (typeof mod.__handbookRun !== "function") {
        throw new Error("Applet module did not export __handbookRun");
      }
      return (sdk, report) => mod.__handbookRun(sdk, report);
    } finally {
      URL.revokeObjectURL(moduleUrl);
    }
  }
}

async function runAppletInline(appletId, options = {}) {
  const { quiet = false } = options;
  const applet = findApplet(appletId);
  if (applet === null) {
    if (!quiet) {
      statusLine = `Unknown applet: ${appletId}`;
      await render();
    }
    return null;
  }

  if (!quiet) {
    statusLine = `Running ${applet.title}…`;
    await render();
  }

  let source;
  try {
    source = await workspace.read(`applets/${appletId}/main.js`);
  } catch {
    source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  }

  if (typeof source !== "string" || source.length === 0) {
    const failed = {
      status: "fail",
      details: "Applet source not found in workspace seeds."
    };
    appletResults[appletId] = failed;
    if (!quiet) {
      statusLine = null;
      await render();
    }
    return { appletId, ...failed };
  }

  const started = Date.now();
  /** @type {{ status: string, details: string, timings?: { ms: number } } | null} */
  let reported = null;
  const report = (result) => {
    reported = {
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: Date.now() - started }
    };
  };

  try {
    const runner = await loadAppletRunner(source);
    await runner(makeSdk(), report);
    if (reported === null) {
      reported = {
        status: "fail",
        details: "Applet finished without calling report().",
        timings: { ms: Date.now() - started }
      };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted =
      /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    reported = {
      status: notGranted ? "not-granted" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
  }

  appletResults[appletId] = reported;
  if (!quiet) {
    statusLine = `${applet.title}: ${reported.status}`;
    await render();
  }
  return { appletId, ...reported };
}

async function seedPreviewProject(preview) {
  const project = preview.project;
  for (const [name, content] of Object.entries(preview.files)) {
    await workspace.write(`${project}/${name}`, content);
  }
}

async function runAppletPreviewSlot(appletId) {
  const applet = findApplet(appletId);
  if (applet === null || applet.preview === null || !appletSupportsMode(applet, "preview")) {
    statusLine = `Preview not available for: ${appletId}`;
    await render();
    return;
  }

  if (previewRunning) {
    statusLine = "Stop the current preview before starting another.";
    await render();
    return;
  }

  const preview = applet.preview;
  statusLine = `Launching preview for ${applet.title}…`;
  await render();

  const started = Date.now();
  try {
    await seedPreviewProject(preview);
    const packed = await apps.packageProject(preview.project, preview.manifest);
    if (packed === null || typeof packed.t256 !== "string") {
      throw new Error(`Package failed: ${JSON.stringify(packed)}`);
    }

    const launched = await apps.preview(preview.project, preview.manifest, preview.grants);
    if (launched === null || launched.launched !== true) {
      throw new Error(`Preview did not launch: ${JSON.stringify(launched)}`);
    }

    previewRunning = true;
    previewAppletId = appletId;
    appletResults[appletId] = {
      status: "pass",
      details: `Preview running (${packed.t256.slice(0, 12)}…). Use Stop preview when finished.`,
      timings: { ms: Date.now() - started }
    };
    statusLine = `${applet.title}: preview slot active`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(
      message
    );
    appletResults[appletId] = {
      status: notGranted ? "not-granted" : unavailable ? "unavailable" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
    statusLine = `${applet.title}: preview failed`;
  }

  await render();
}

async function stopAppletPreview() {
  if (!previewRunning) {
    return;
  }

  try {
    await apps.stopPreview();
  } catch (error) {
    statusLine = `Stop preview failed: ${error instanceof Error ? error.message : String(error)}`;
    await render();
    return;
  }

  previewRunning = false;
  previewAppletId = null;
  statusLine = "Preview stopped";
  await render();
}

async function runAllDiagnostics() {
  if (runningAll) {
    return;
  }
  runningAll = true;
  statusLine = "Running all diagnostics…";
  view = "diagnostics";
  await render();

  try {
    for (const applet of CATALOG.applets) {
      statusLine = `Running ${applet.title}…`;
      await render();
      await runAppletInline(applet.id, { quiet: true });
      // Restore Handbook chrome after applets that call ui.render (e.g. widget gallery).
      statusLine = `Finished ${applet.title}: ${appletResults[applet.id]?.status ?? "?"}`;
      await render();
    }
    statusLine = `All diagnostics finished (${CATALOG.applets.length} applets)`;
  } finally {
    runningAll = false;
    await render();
  }
}

async function exportReport() {
  statusLine = "Building diagnostic report…";
  await render();

  const hostInfo = await fetchHostInfoSafe();
  const document = buildReportDocument(hostInfo);
  const json = JSON.stringify(document);

  try {
    const put = await share.put(json);
    exportState = {
      reportId: put.t256,
      generatedAt: document.generatedAt,
      json
    };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report exported (${put.t256.slice(0, 12)}…)`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    exportState = { reportId: null, generatedAt: document.generatedAt, json };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report built locally but share.put failed: ${message}`;
  }

  view = "diagnostics";
  await render();
}

function buildDevstudioBundle(appletSource) {
  const body = appletSource.replace(/^export\s+async\s+function\s+run\s*\(/m, "async function appletRun(");
  return `import {
  ai,
  apps,
  announce,
  host,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

${body}

function makeSdk() {
  return {
    identity,
    presence,
    host,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps,
    ai
  };
}

let reported = null;
await appletRun(makeSdk(), (result) => {
  reported = result;
});

await ui.render({
  root: {
    id: "root",
    type: "scroll",
    style: { padding: 12, gap: 8 },
    children: [
      {
        id: "result",
        type: "text",
        props: {
          value: reported
            ? \`\${reported.status.toUpperCase()}\\n\${reported.details}\`
            : "Applet finished without calling report()."
        }
      }
    ]
  }
});
`;
}

async function exportAppletToDevStudio(appletId) {
  const applet = findApplet(appletId);
  if (applet === null) {
    statusLine = `Unknown applet: ${appletId}`;
    await render();
    return;
  }

  statusLine = `Preparing DevStudio handoff for ${applet.title}…`;
  await render();

  let source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  if (source === undefined) {
    try {
      source = await workspace.read(`applets/${appletId}/main.js`);
    } catch {
      source = undefined;
    }
  }

  if (source === undefined) {
    statusLine = "Applet source not found in workspace seeds.";
    await render();
    return;
  }

  const project = `hb-${appletId}`;
  const manifest = {
    name: project,
    version: "0.1.0",
    entry: "bundle.js",
    capabilities: applet.capabilities
  };
  const payload = {
    kind: DEVSTUDIO_HANDOFF_KIND,
    version: 1,
    project,
    files: [
      { path: `${project}/app.json`, content: JSON.stringify(manifest, null, 2) },
      { path: `${project}/applet.js`, content: source },
      { path: `${project}/bundle.js`, content: buildDevstudioBundle(source) }
    ]
  };

  try {
    const put = await share.put(JSON.stringify(payload));
    devstudioHandoffs[appletId] = { t256: put.t256, project };
    statusLine = `DevStudio handoff ready (${put.t256.slice(0, 12)}…)`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    statusLine = notGranted
      ? "Grant share:cas to export DevStudio handoffs."
      : `DevStudio handoff failed: ${message}`;
  }

  await render();
}

async function compareReport() {
  const t256 = compareInput.trim();
  if (t256.length === 0) {
    compareState = { local: compareState.local, remote: null, rows: [], error: "Paste a report 256t id first." };
    await render();
    return;
  }

  statusLine = "Fetching remote report…";
  await render();

  let local = compareState.local;
  if (local === null) {
    const cached = await kvGetText(LAST_REPORT_KEY);
    if (cached !== null) {
      try {
        local = JSON.parse(cached);
      } catch {
        local = null;
      }
    }
  }
  if (local === null) {
    const hostInfo = await fetchHostInfoSafe();
    local = buildReportDocument(hostInfo);
  }

  try {
    const remoteJson = await share.get(t256);
    if (typeof remoteJson !== "string" || remoteJson.length === 0) {
      compareState = {
        local,
        remote: null,
        rows: [],
        error: "Remote report not found (null content)."
      };
      statusLine = null;
      await render();
      return;
    }
    const remote = JSON.parse(remoteJson);
    const rows = diffReports(local, remote);
    compareState = { local, remote, rows, error: null };
    statusLine = `Compared ${rows.length} applet row(s)`;
  } catch (error) {
    compareState = {
      local,
      remote: null,
      rows: [],
      error: error instanceof Error ? error.message : String(error)
    };
    statusLine = null;
  }

  view = "diagnostics";
  await render();
}

function chapterIdFromNode(nodeId) {
  if (nodeId.startsWith("ch-")) {
    return nodeId.slice(3);
  }
  if (nodeId.startsWith("link-")) {
    const rest = nodeId.slice("link-".length);
    let best = null;
    for (const chapter of CATALOG.chapters) {
      const prefix = `${chapter.id}-`;
      if (rest.startsWith(prefix) && (best === null || chapter.id.length > best.length)) {
        best = chapter.id;
      }
    }
    return best;
  }
  return null;
}

function appletIdFromRunNode(nodeId) {
  if (nodeId.startsWith("applet-run-")) {
    return nodeId.slice("applet-run-".length);
  }
  return null;
}

function appletIdFromDevStudioNode(nodeId) {
  if (nodeId.startsWith("applet-devstudio-")) {
    return nodeId.slice("applet-devstudio-".length);
  }
  return null;
}

function appletIdFromPreviewNode(nodeId) {
  if (nodeId.startsWith("applet-preview-")) {
    return nodeId.slice("applet-preview-".length);
  }
  if (nodeId.startsWith("applet-stoppreview-")) {
    return nodeId.slice("applet-stoppreview-".length);
  }
  return null;
}

async function handleEvent({ nodeId, event, value }) {
  if (event === "hb.grantintro.dismiss") {
    await dismissGrantIntro();
    return;
  }

  if (event === "hb.toc") {
    await openToc();
    return;
  }

  if (event === "hb.diagnostics") {
    await openDiagnostics();
    return;
  }

  if (event === "hb.openchapter") {
    const id = chapterIdFromNode(nodeId);
    if (id !== null) {
      await openChapter(id);
    }
    return;
  }

  if (event === "hb.runapplet") {
    const id = appletIdFromRunNode(nodeId);
    if (id !== null) {
      await runAppletInline(id);
    }
    return;
  }

  if (event === "hb.runpreview") {
    const id = appletIdFromPreviewNode(nodeId);
    if (id !== null) {
      await runAppletPreviewSlot(id);
    }
    return;
  }

  if (event === "hb.stoppreview") {
    await stopAppletPreview();
    return;
  }

  if (event === "hb.devstudio") {
    const id = appletIdFromDevStudioNode(nodeId);
    if (id !== null) {
      await exportAppletToDevStudio(id);
    }
    return;
  }

  if (event === "hb.runall") {
    await runAllDiagnostics();
    return;
  }

  if (event === "hb.export") {
    await exportReport();
    return;
  }

  if (event === "hb.compare.input") {
    compareInput = typeof value === "string" ? value : String(value ?? "");
    return;
  }

  if (event === "hb.search") {
    searchQuery = typeof value === "string" ? value : String(value ?? "");
    view = "toc";
    await render();
    return;
  }

  if (event === "hb.scroll" && view === "chapter" && chapterId !== null) {
    const y = typeof value === "object" && value !== null && typeof value.y === "number" ? value.y : 0;
    chapterScrollOffset = y;
    scheduleScrollSave(chapterId, y);
    return;
  }

  if (event === "hb.compare") {
    await compareReport();
  }
}

ui.onEvent((event) => {
  void handleEvent(event).catch(async (error) => {
    statusLine = `Error: ${error instanceof Error ? error.message : String(error)}`;
    await render();
  });
});

await ensureSeeds();

const grantIntroSeen = await kvGetText(GRANT_INTRO_KEY);
if (grantIntroSeen !== "1") {
  view = "grant-intro";
} else {
  const saved = await kvGetText(POSITION_KEY);
  if (saved !== null && findChapter(saved) !== null) {
    chapterId = saved;
    view = "chapter";
    await loadChapterScroll(saved);
  } else {
    view = "toc";
  }
}

const cachedReport = await kvGetText(LAST_REPORT_KEY);
if (cachedReport !== null) {
  try {
    compareState = { ...compareState, local: JSON.parse(cachedReport) };
  } catch {
    // ignore corrupt cache
  }
}

await render();
